    assertEvaluatorResult(result, expected);
}

@Test
public void testAllNulls() {
    List<Expression> list = ImmutableList.of(Expressions.countStar(), Expressions.count("all_nulls"), Expressions.countNull("all_nulls"), Expressions.max("all_nulls"), Expressions.min("all_nulls"));
