@Test
public void testRewriteNot() {
    StructType struct = StructType.of(NestedField.optional(1, "a", Types.IntegerType.get()), NestedField.optional(2, "s", Types.StringType.get()));
    Expression[][] expressions = new Expression[][] { // (rewritten pred, original pred) pairs
    { isNull("a"), isNull("a") }, { notNull("a"), not(isNull("a")) }, { notNull("a"), notNull("a") }, { isNull("a"), not(notNull("a")) }, { equal("a", 5), equal("a", 5) }, { notEqual("a", 5), not(equal("a", 5)) }, { notEqual("a", 5), notEqual("a", 5) }, { equal("a", 5), not(notEqual("a", 5)) }, { in("a", 5, 6), in("a", 5, 6) }, { notIn("a", 5, 6), not(in("a", 5, 6)) }, { notIn("a", 5, 6), notIn("a", 5, 6) }, { in("a", 5, 6), not(notIn("a", 5, 6)) }, { lessThan("a", 5), lessThan("a", 5) }, { greaterThanOrEqual("a", 5), not(lessThan("a", 5)) }, { greaterThanOrEqual("a", 5), greaterThanOrEqual("a", 5) }, { lessThan("a", 5), not(greaterThanOrEqual("a", 5)) }, { lessThanOrEqual("a", 5), lessThanOrEqual("a", 5) }, { greaterThan("a", 5), not(lessThanOrEqual("a", 5)) }, { greaterThan("a", 5), greaterThan("a", 5) }, { lessThanOrEqual("a", 5), not(greaterThan("a", 5)) }, { or(equal("a", 5), isNull("a")), or(equal("a", 5), isNull("a")) }, { and(notEqual("a", 5), notNull("a")), not(or(equal("a", 5), isNull("a"))) }, { and(notEqual("a", 5), notNull("a")), and(notEqual("a", 5), notNull("a")) }, { or(equal("a", 5), isNull("a")), not(and(notEqual("a", 5), notNull("a"))) }, { or(equal("a", 5), notNull("a")), or(equal("a", 5), not(isNull("a"))) }, { startsWith("s", "hello"), not(notStartsWith("s", "hello")) }, { notStartsWith("s", "world"), not(startsWith("s", "world")) } };
    for (Expression[] pair : expressions) {
        // unbound rewrite
        assertThat(rewriteNot(pair[1])).as(String.format("rewriteNot(%s) should be %s", pair[1], pair[0])).hasToString(pair[0].toString());
        // bound rewrite
        Expression expectedBound = Binder.bind(struct, pair[0]);
        Expression toRewriteBound = Binder.bind(struct, pair[1]);
        assertThat(rewriteNot(toRewriteBound)).as(String.format("rewriteNot(%s) should be %s", toRewriteBound, expectedBound)).hasToString(expectedBound.toString());
    }
}

