@Test
public void testSanitizeLongIn() {
    Object[] tooLongRange = IntStream.range(95, 95 + ExpressionUtil.LONG_IN_PREDICATE_ABBREVIATION_THRESHOLD).boxed().toArray();
    Object[] almostTooLongRange = Arrays.copyOf(tooLongRange, tooLongRange.length - 1);
    assertThat(ExpressionUtil.toSanitizedString(Expressions.in("test", almostTooLongRange))).as("Sanitized string should be abbreviated").isEqualTo("test IN ((2-digit-int), (2-digit-int), (2-digit-int), (2-digit-int), (2-digit-int), (3-digit-int), (3-digit-int), (3-digit-int), (3-digit-int))");
    assertThat(ExpressionUtil.toSanitizedString(Expressions.in("test", tooLongRange))).as("Sanitized string should be abbreviated").isEqualTo("test IN ((2-digit-int), (3-digit-int), ... (8 values hidden, 10 in total))");
    // The sanitization resulting in an expression tree does not abbreviate
    List<String> expectedValues = Lists.newArrayList();
    expectedValues.addAll(Collections.nCopies(5, "(2-digit-int)"));
    expectedValues.addAll(Collections.nCopies(5, "(3-digit-int)"));
    assertEquals(Expressions.in("test", expectedValues), ExpressionUtil.sanitize(Expressions.in("test", tooLongRange)));
}

