@Test
public void testStringNotStartsWith() {
    boolean shouldRead = ManifestEvaluator.forRowFilter(notStartsWith("some_nulls", "a"), SPEC, false).eval(FILE);
    assertThat(shouldRead).as("Should read: range matches").isTrue();
    shouldRead = ManifestEvaluator.forRowFilter(notStartsWith("some_nulls", "aa"), SPEC, false).eval(FILE);
    assertThat(shouldRead).as("Should read: range matches").isTrue();
    shouldRead = ManifestEvaluator.forRowFilter(notStartsWith("some_nulls", "dddd"), SPEC, false).eval(FILE);
    assertThat(shouldRead).as("Should read: range matches").isTrue();
    shouldRead = ManifestEvaluator.forRowFilter(notStartsWith("some_nulls", "z"), SPEC, false).eval(FILE);
    assertThat(shouldRead).as("Should read: range matches").isTrue();
    shouldRead = ManifestEvaluator.forRowFilter(notStartsWith("no_nulls", "a"), SPEC, false).eval(FILE);
    assertThat(shouldRead).as("Should read: range matches").isTrue();
    shouldRead = ManifestEvaluator.forRowFilter(notStartsWith("some_nulls", "zzzz"), SPEC, false).eval(FILE);
    assertThat(shouldRead).as("Should read: range matches").isTrue();
    shouldRead = ManifestEvaluator.forRowFilter(notStartsWith("some_nulls", "1"), SPEC, false).eval(FILE);
    assertThat(shouldRead).as("Should read: range matches").isTrue();
    shouldRead = ManifestEvaluator.forRowFilter(notStartsWith("all_same_value_or_null", "a"), SPEC, false).eval(FILE);
    assertThat(shouldRead).as("Should read: range matches on null").isTrue();
    shouldRead = ManifestEvaluator.forRowFilter(notStartsWith("all_same_value_or_null", "aa"), SPEC, false).eval(FILE);
    assertThat(shouldRead).as("Should read: range matches").isTrue();
    shouldRead = ManifestEvaluator.forRowFilter(notStartsWith("all_same_value_or_null", "A"), SPEC, false).eval(FILE);
    assertThat(shouldRead).as("Should read: range matches").isTrue();
    // Iceberg does not implement SQL's 3-way boolean logic, so the choice of an all null column
    // matching is
    // by definition in order to surface more values to the query engine to allow it to make its own
    // decision.
    shouldRead = ManifestEvaluator.forRowFilter(notStartsWith("all_nulls_missing_nan", "A"), SPEC, false).eval(FILE);
    assertThat(shouldRead).as("Should read: range matches").isTrue();
    shouldRead = ManifestEvaluator.forRowFilter(notStartsWith("no_nulls_same_value_a", "a"), SPEC, false).eval(FILE);
    assertThat(shouldRead).as("Should not read: all values start with the prefix").isFalse();
}

@Test
public void testIntegerIn() {
    boolean shouldRead = ManifestEvaluator.forRowFilter(in("id", INT_MIN_VALUE - 25, INT_MIN_VALUE - 24), SPEC, true).eval(FILE);
    assertThat(shouldRead).as("Should not read: id below lower bound (5 < 30, 6 < 30)").isFalse();
    shouldRead = ManifestEvaluator.forRowFilter(in("id", INT_MIN_VALUE - 2, INT_MIN_VALUE - 1), SPEC, true).eval(FILE);
    assertThat(shouldRead).as("Should not read: id below lower bound (28 < 30, 29 < 30)").isFalse();
    shouldRead = ManifestEvaluator.forRowFilter(in("id", INT_MIN_VALUE - 1, INT_MIN_VALUE), SPEC, true).eval(FILE);
    assertThat(shouldRead).as("Should read: id equal to lower bound (30 == 30)").isTrue();
    shouldRead = ManifestEvaluator.forRowFilter(in("id", INT_MAX_VALUE - 4, INT_MAX_VALUE - 3), SPEC, true).eval(FILE);
    assertThat(shouldRead).as("Should read: id between lower and upper bounds (30 < 75 < 79, 30 < 76 < 79)").isTrue();
    shouldRead = ManifestEvaluator.forRowFilter(in("id", INT_MAX_VALUE, INT_MAX_VALUE + 1), SPEC, true).eval(FILE);
    assertThat(shouldRead).as("Should read: id equal to upper bound (79 == 79)").isTrue();
    shouldRead = ManifestEvaluator.forRowFilter(in("id", INT_MAX_VALUE + 1, INT_MAX_VALUE + 2), SPEC, true).eval(FILE);
    assertThat(shouldRead).as("Should not read: id above upper bound (80 > 79, 81 > 79)").isFalse();
    shouldRead = ManifestEvaluator.forRowFilter(in("id", INT_MAX_VALUE + 6, INT_MAX_VALUE + 7), SPEC, true).eval(FILE);
    assertThat(shouldRead).as("Should not read: id above upper bound (85 > 79, 86 > 79)").isFalse();
    shouldRead = ManifestEvaluator.forRowFilter(in("all_nulls_missing_nan", "abc", "def"), SPEC, true).eval(FILE);
    assertThat(shouldRead).as("Should skip: in on all nulls column").isFalse();
    shouldRead = ManifestEvaluator.forRowFilter(in("some_nulls", "abc", "def"), SPEC, true).eval(FILE);
    assertThat(shouldRead).as("Should read: in on some nulls column").isTrue();
    shouldRead = ManifestEvaluator.forRowFilter(in("no_nulls", "abc", "def"), SPEC, true).eval(FILE);
    assertThat(shouldRead).as("Should read: in on no nulls column").isTrue();
}

