    Literal<Double> lit = Literal.of(34.56D);
    Literal<Float> doubleLit = lit.to(Types.FloatType.get());
    assertThat(doubleLit.value()).isCloseTo(34.56F, offset(0.001F));
    // this adjusts Float.MAX_VALUE using multipliers because most integer adjustments are lost by
    // floating point precision.
    assertThat(Literal.of(2 * ((double) Float.MAX_VALUE)).to(Types.FloatType.get())).as("Values above Float.MAX_VALUE should be Literals.aboveMax()").isEqualTo(Literals.aboveMax());
    assertThat(Literal.of(-2 * ((double) Float.MAX_VALUE)).to(Types.FloatType.get())).as("Values below Float.MIN_VALUE should be Literals.belowMin()").isEqualTo(Literals.belowMin());
}

@Test
public void testDoubleToDecimalConversion() {
    Literal<Double> lit = Literal.of(34.56D);
    assertThat(lit.to(Types.DecimalType.of(9, 1)).value()).as("Value should round using HALF_UP").isEqualTo(new BigDecimal("34.6"));
    assertThat(lit.to(Types.DecimalType.of(9, 2)).value()).isEqualTo(new BigDecimal("34.56"));
    assertThat(lit.to(Types.DecimalType.of(9, 4)).value()).isEqualTo(new BigDecimal("34.5600"));
}

@Test
public void testDecimalToDecimalConversion() {
    Literal<BigDecimal> lit = Literal.of(new BigDecimal("34.11"));
    IntStream.range(0, 10).forEach(scale -> {
        assertThat(lit.to(Types.DecimalType.of(9, scale))).as("Should return identical object").isSameAs(lit);
        assertThat(lit.to(Types.DecimalType.of(11, scale))).as("Should return identical object").isSameAs(lit);
    });
}

