    assertThat(transform.apply("bbb")).isLessThan(transform.apply("aaa"));
    assertThat(transform.apply("bbb")).isEqualTo(transform.apply("cca"));
    TestHelpers.Row less = TestHelpers.Row.of("id3", "bbb");
