@Test
public void testUUIDBucket() {
    Schema schema = singleSortFildSchema(Types.UUIDType.get());
    Transform<UUID, Integer> bucket = Transforms.bucket(4);
    SerializableFunction<UUID, Integer> transform = bucket.bind(Types.UUIDType.get());
    assertThat(transform.apply(UUID.fromString("fd02441d-1423-4a3f-8785-c7dd5647e26b"))).isLessThan(transform.apply(UUID.fromString("86873e7d-1374-4493-8e1d-9095eff7046c")));
    assertThat(transform.apply(UUID.fromString("fd02441d-1423-4a3f-8785-c7dd5647e26b"))).isEqualTo(transform.apply(UUID.fromString("81873e7d-1374-4493-8e1d-9095eff7046c")));
