    TestHelpers.Row lessCopy = TestHelpers.Row.of("id1", UUID.fromString("81873e7d-1374-4493-8e1d-9095eff7046c"));
    SortOrder sortOrder = SortOrder.builderFor(schema).sortBy(Expressions.bucket("field", 4), SortDirection.ASC, NullOrder.NULLS_FIRST).build();
