    SortOrder sortOrder = SortOrder.builderFor(schema).sortBy(Expressions.truncate("field", 2), SortDirection.ASC, NullOrder.NULLS_FIRST).build();
    assertComparesCorrectly(schema, sortOrder, less, greater, lessCopy, SINGLE_SORT_FILED_NULL_VALUE);
}

