@Test
public void testTimestampNanoPromotion() {
    Types.TimestampType tsType = Types.TimestampType.withoutZone();
    Types.TimestampNanoType tsNsType = Types.TimestampNanoType.withoutZone();
    Bucket<Object> tsNsBucket = Bucket.get(tsNsType, 1);
    Bucket<Object> tsBucket = Bucket.get(tsType, 1);
    // Values from spec Appendix B: 32-bit Hash Requirements
    assertThat(tsBucket.hash(Literal.of("2017-11-16T22:31:08").to(tsType).value())).as("Spec example: hash(2017-11-16T22:31:08) = -2047944441 for Timestamp and TimestampNano should match").isEqualTo(-2047944441);
    assertThat(tsNsBucket.hash(Literal.of("2017-11-16T22:31:08").to(tsNsType).value())).as("Spec example: hash(2017-11-16T22:31:08) = -2047944441 for Timestamp and TimestampNano should match").isEqualTo(-2047944441);
    assertThat(tsBucket.hash(Literal.of("2017-11-16T22:31:08.000001").to(tsType).value())).as("Spec example: hash(2017-11-16T22:31:08.000001) = -1207196810 for Timestamp and TimestampNano should match").isEqualTo(-1207196810);
    assertThat(tsNsBucket.hash(Literal.of("2017-11-16T22:31:08.000001001").to(tsNsType).value())).as("Spec example: hash(2017-11-16T22:31:08.000001) = -1207196810 for Timestamp and TimestampNano should match").isEqualTo(-1207196810);
}

