@Test
public void testTruncateStringWhenProjectedPredicateTermIsLongerThanWidth() {
    Truncate<String> trunc = Truncate.get(2);
    UnboundPredicate<String> expr = notStartsWith(COLUMN, "abcde");
    BoundPredicate<String> boundExpr = (BoundPredicate<String>) Binder.bind(SCHEMA.asStruct(), expr, false);
    UnboundPredicate<String> projected = trunc.projectStrict(COLUMN, boundExpr);
    Evaluator evaluator = new Evaluator(SCHEMA.asStruct(), projected);
    assertThat(projected.literal().value()).as("The projected literal should be truncated to the truncation width").isEqualTo("ab");
    assertThat(evaluator.eval(TestHelpers.Row.of("abcde"))).as("notStartsWith(abcde, truncate(abcde,2)) => false").isFalse();
    assertThat(evaluator.eval(TestHelpers.Row.of("ab"))).as("notStartsWith(abcde, truncate(ab, 2)) => false").isFalse();
    assertThat(evaluator.eval(TestHelpers.Row.of("abcdz"))).as("notStartsWith(abcde, truncate(abcdz, 2)) => false").isFalse();
    assertThat(evaluator.eval(TestHelpers.Row.of("a"))).as("notStartsWith(abcde, truncate(a, 2)) => true").isTrue();
    assertThat(evaluator.eval(TestHelpers.Row.of("aczcde"))).as("notStartsWith(abcde, truncate(aczcde, 2)) => true").isTrue();
}

