@Test
public void testFunctionSerialization() throws Exception {
    Type[] types = new Type[] { Types.BooleanType.get(), Types.IntegerType.get(), Types.LongType.get(), Types.FloatType.get(), Types.DoubleType.get(), Types.StringType.get(), Types.DateType.get(), Types.TimeType.get(), Types.TimestampType.withoutZone(), Types.TimestampType.withoutZone(), Types.BinaryType.get(), Types.FixedType.ofLength(4), Types.DecimalType.of(9, 4), Types.UUIDType.get() };
    Transform<?, ?>[] transforms = new Transform<?, ?>[] { Transforms.identity(), Transforms.bucket(1024), Transforms.year(), Transforms.month(), Transforms.day(), Transforms.hour(), Transforms.truncate(16) };
    for (Type type : types) {
        for (Transform<?, ?> transform : transforms) {
            assertThat(TestHelpers.roundTripSerialize(transform)).isEqualTo(transform);
            if (transform.canTransform(type)) {
                SerializableFunction<?, ?> func = transform.bind(type);
                assertThat(func).isInstanceOf(TestHelpers.roundTripSerialize(func).getClass());
            }
        }
    }
}

