    assertThat(Types.fromPrimitiveString("geography(srid:4269, andoyer)")).isEqualTo(Types.GeographyType.of("srid:4269", EdgeAlgorithm.ANDOYER));
    assertThat(Types.fromPrimitiveString("geography(srid:4269, karney)")).isEqualTo(Types.GeographyType.of("srid:4269", EdgeAlgorithm.KARNEY));
    assertThat(Types.fromPrimitiveString("geography(srid: 4269, karney)")).isEqualTo(Types.GeographyType.of("srid: 4269", EdgeAlgorithm.KARNEY));
    assertThat(Types.fromPrimitiveString("Geography(projjson: TestIdentifier, karney)")).isEqualTo(Types.GeographyType.of("projjson: TestIdentifier", EdgeAlgorithm.KARNEY));
    assertThatExceptionOfType(IllegalArgumentException.class).isThrownBy(() -> Types.fromPrimitiveString("geography()")).withMessageContaining("Invalid CRS: (empty string)");
    assertThatExceptionOfType(IllegalArgumentException.class).isThrownBy(() -> Types.fromPrimitiveString("geography( , spherical)")).withMessageContaining("Invalid CRS: (empty string)");
    assertThatExceptionOfType(IllegalArgumentException.class).isThrownBy(() -> Types.fromPrimitiveString("geography(srid:4269, BadAlgorithm)")).withMessageContaining("Invalid edge interpolation algorithm").withMessageContaining("BadAlgorithm");
    // Test geography type with various spacing
    assertThat(Types.fromPrimitiveString("geography( srid:4269 )")).isEqualTo(Types.GeographyType.of("srid:4269"));
    assertThat(Types.fromPrimitiveString("geography( srid:4269 , spherical )")).isEqualTo(Types.GeographyType.of("srid:4269", EdgeAlgorithm.SPHERICAL));
    assertThat(Types.fromPrimitiveString("geography(srid:4269,vincenty)")).isEqualTo(Types.GeographyType.of("srid:4269", EdgeAlgorithm.VINCENTY));
    assertThat(Types.fromPrimitiveString("geography( srid:4269  ,  karney  )")).isEqualTo(Types.GeographyType.of("srid:4269", EdgeAlgorithm.KARNEY));
}

