    assertThat(actualDepthOneNoKeys.asStruct()).isEqualTo(expectedDepthOne.asStruct());
    Schema expectedDepthTwo = new Schema(Lists.newArrayList(required(10, "a", Types.IntegerType.get()), required(12, "map", Types.MapType.ofRequired(13, 14, Types.StructType.of(optional(100, "x", Types.IntegerType.get()), optional(101, "y", Types.IntegerType.get())), Types.StructType.of(required(200, "z", Types.IntegerType.get()), optional(201, "innerMap", Types.MapType.ofOptional(202, 203, Types.IntegerType.get(), Types.StructType.of())))))));
    Schema actualDepthTwo = TypeUtil.project(schema, Sets.newHashSet(10, 13, 14, 100, 101, 200, 202, 203));
    assertThat(actualDepthTwo.asStruct()).isEqualTo(expectedDepthTwo.asStruct());
