@Test
public void testRetainAll() {
    CharSequenceSet set = CharSequenceSet.of(ImmutableList.of("123", "456"));
    assertThat(set.retainAll(ImmutableList.of("456", "789", 123))).overridingErrorMessage("Set should be changed").isTrue();
    assertThat(set).hasSize(1).contains("456");
    set = CharSequenceSet.of(ImmutableList.of("123", "456"));
    assertThat(set.retainAll(ImmutableList.of("123", "456"))).overridingErrorMessage("Set should not be changed").isFalse();
    assertThat(set.retainAll(ImmutableList.of(123, 456))).overridingErrorMessage("Set should be changed").isTrue();
    assertThat(set).isEmpty();
}

