/**
 * The test asserts that {@link CloseableIterator#hasNext()} returned by the {@link ArrowReader}
 * is idempotent.
 */
@Test
public void testHasNextIsIdempotent() throws Exception {
    writeTableWithIncrementalRecords();
    Table table = tables.load(tableLocation);
    TableScan scan = table.newScan();
    // Call hasNext() 0 extra times.
    readAndCheckHasNextIsIdempotent(scan, NUM_ROWS_PER_MONTH, 12 * NUM_ROWS_PER_MONTH, 0, ALL_COLUMNS);
    // Call hasNext() 1 extra time.
    readAndCheckHasNextIsIdempotent(scan, NUM_ROWS_PER_MONTH, 12 * NUM_ROWS_PER_MONTH, 1, ALL_COLUMNS);
    // Call hasNext() 2 extra times.
    readAndCheckHasNextIsIdempotent(scan, NUM_ROWS_PER_MONTH, 12 * NUM_ROWS_PER_MONTH, 2, ALL_COLUMNS);
}

@Test
public void testCreateNamespace() {
    Namespace namespace = Namespace.of(genRandomName());
    catalog.createNamespace(namespace);
    GetItemResponse response = dynamo.getItem(GetItemRequest.builder().tableName(catalogTableName).key(DynamoDbCatalog.namespacePrimaryKey(namespace)).build());
    assertThat(response.hasItem()).as("namespace must exist").isTrue();
    assertThat(response.item()).as("namespace must be stored in DynamoDB").hasEntrySatisfying("namespace", attributeValue -> assertThat(attributeValue.s()).isEqualTo(namespace.toString()));
    assertThatThrownBy(() -> catalog.createNamespace(namespace)).isInstanceOf(AlreadyExistsException.class).hasMessageContaining("already exists");
}

