    // check table in Glue
    GetTableResponse response = GLUE.getTable(GetTableRequest.builder().databaseName(namespace).name(tableName).build());
    assertThat(response.table().tableType()).as("external table type is set after update").isEqualTo("EXTERNAL_TABLE");
    assertThat(response.table().storageDescriptor().columns()).hasSameSizeAs(schema.columns());
    assertThat(response.table().partitionKeys()).hasSameSizeAs(partitionSpec.fields());
    assertThat(response.table().description()).isEqualTo(description);
    String updatedComment = "test updated comment";
    table.updateProperties().set(IcebergToGlueConverter.GLUE_DESCRIPTION_KEY, updatedComment).commit();
    // check table in Glue
    response = GLUE.getTable(GetTableRequest.builder().databaseName(namespace).name(tableName).build());
    assertThat(response.table().description()).isEqualTo(updatedComment);
}

