@Test
void validateS3ConditionalWrites() {
    S3Client s3Client = MinioUtil.createS3Client(MINIO);
    String bucket = "test-bucket-" + UUID.randomUUID();
    CreateBucketResponse createBucketResponse = s3Client.createBucket(CreateBucketRequest.builder().bucket(bucket).build());
    assertThat(createBucketResponse.sdkHttpResponse().isSuccessful()).isTrue();
    String key = "test-key-" + UUID.randomUUID().toString();
    for (int i = 0; i < 5; i++) {
        String payload = "test-payload-" + i;
        PutObjectRequest request = PutObjectRequest.builder().bucket(bucket).key(key).ifNoneMatch("*").build();
        RequestBody body = RequestBody.fromString(payload);
        if (i == 0) {
            PutObjectResponse response = s3Client.putObject(request, body);
            assertThat(response.sdkHttpResponse().isSuccessful()).isTrue();
        } else {
            assertThatThrownBy(() -> s3Client.putObject(request, body)).isInstanceOf(S3Exception.class).hasMessageContaining("Service: S3, Status Code: 412").hasMessageContaining("At least one of the pre-conditions you specified did not hold");
        }
    }
    var getResponse = s3Client.getObject(request -> request.bucket(bucket).key(key), ResponseTransformer.toBytes());
    String responseBody = getResponse.asUtf8String();
    assertThat(responseBody).isEqualTo("test-payload-0");
}

@Test
public void testNewInputFile() throws IOException {
    String location = "s3://bucket/path/to/file.txt";
    byte[] expected = new byte[1024 * 1024];
    random.nextBytes(expected);
    InputFile in = s3FileIO.newInputFile(location);
    assertThat(in.exists()).isFalse();
    OutputFile out = s3FileIO.newOutputFile(location);
    try (OutputStream os = out.createOrOverwrite()) {
        IOUtil.writeFully(os, ByteBuffer.wrap(expected));
    }
    assertThat(in.exists()).isTrue();
    byte[] actual = new byte[1024 * 1024];
    try (InputStream is = in.newStream()) {
        IOUtil.readFully(is, actual, 0, expected.length);
    }
    assertThat(actual).isEqualTo(expected);
    s3FileIO.deleteFile(in);
    assertThat(s3FileIO.newInputFile(location).exists()).isFalse();
}

