@ParameterizedTest
@MethodSource("org.apache.iceberg.TestHelpers#serializers")
public void resolvingFileIOLoadWithStorageCredentials(TestHelpers.RoundTripSerializer<ResolvingFileIO> roundTripSerializer) throws IOException, ClassNotFoundException {
    StorageCredential credential = StorageCredential.create("s3://foo/bar", Map.of("key1", "val1"));
    List<StorageCredential> storageCredentials = ImmutableList.of(credential);
    ResolvingFileIO resolvingFileIO = new ResolvingFileIO();
    resolvingFileIO.setCredentials(storageCredentials);
    resolvingFileIO.initialize(ImmutableMap.of(AwsClientProperties.CLIENT_REGION, "us-east-1"));
    FileIO result = DynMethods.builder("io").hiddenImpl(ResolvingFileIO.class, String.class).build(resolvingFileIO).invoke("s3://foo/bar");
    ObjectAssert<S3FileIO> io = assertThat(result).isInstanceOf(S3FileIO.class).asInstanceOf(InstanceOfAssertFactories.type(S3FileIO.class));
    io.extracting(S3FileIO::credentials).isEqualTo(storageCredentials);
    io.satisfies(fileIO -> {
        // make sure there are two separate S3 clients for different prefixes and that the
        // underlying sync/async client is set
        assertThat(fileIO.client("s3://foo/bar")).isNotSameAs(fileIO.client()).isInstanceOf(S3Client.class);
        assertThat(fileIO.asyncClient("s3://foo/bar")).isNotSameAs(fileIO.asyncClient()).isInstanceOf(S3AsyncClient.class);
    });
    // make sure credentials are still present after serde
    ResolvingFileIO resolvingIO = roundTripSerializer.apply(resolvingFileIO);
    assertThat(resolvingIO.credentials()).isEqualTo(storageCredentials);
    result = DynMethods.builder("io").hiddenImpl(ResolvingFileIO.class, String.class).build(resolvingIO).invoke("s3://foo/bar");
    io = assertThat(result).isInstanceOf(S3FileIO.class).asInstanceOf(InstanceOfAssertFactories.type(S3FileIO.class));
    io.extracting(S3FileIO::credentials).isEqualTo(storageCredentials);
    io.satisfies(fileIO -> {
        // make sure there are two separate S3 clients for different prefixes and that the
        // underlying sync/async client is set
        assertThat(fileIO.client("s3://foo/bar")).isNotSameAs(fileIO.client()).isInstanceOf(S3Client.class);
        assertThat(fileIO.asyncClient("s3://foo/bar")).isNotSameAs(fileIO.asyncClient()).isInstanceOf(S3AsyncClient.class);
    });
}

@Test
public void noStorageCredentialConfigured() {
    S3FileIO fileIO = new S3FileIO();
    fileIO.setCredentials(ImmutableList.of());
    fileIO.initialize(ImmutableMap.of(AwsClientProperties.CLIENT_REGION, "us-east-1", "s3.access-key-id", "keyIdFromProperties", "s3.secret-access-key", "accessKeyFromProperties", "s3.session-token", "sessionTokenFromProperties"));
    // make sure that the generic S3 Client is used for all storage paths if there are no storage
    // credentials configured
    assertThat(fileIO.client("s3://my-bucket/table1")).isSameAs(fileIO.client("s3://random-bucket/")).isSameAs(fileIO.client("s3a://random-bucket/tableX"));
    ObjectAssert<S3FileIOProperties> s3FileIOProperties = assertThat(fileIO.clientForStoragePath("s3://my-bucket/table1").s3FileIOProperties());
    s3FileIOProperties.extracting(S3FileIOProperties::accessKeyId).isEqualTo("keyIdFromProperties");
    s3FileIOProperties.extracting(S3FileIOProperties::secretAccessKey).isEqualTo("accessKeyFromProperties");
    s3FileIOProperties.extracting(S3FileIOProperties::sessionToken).isEqualTo("sessionTokenFromProperties");
    // verify that the credentials identity gets the correct credentials for the prefixed S3 client
    assertThat(fileIO.client("s3://my-bucket/table1").serviceClientConfiguration()).extracting(AwsServiceClientConfiguration::credentialsProvider).extracting(IdentityProvider::resolveIdentity).satisfies(x -> {
        AwsSessionCredentialsIdentity identity = (AwsSessionCredentialsIdentity) x.get();
        assertThat(identity).isNotNull();
        assertThat(identity.accessKeyId()).isEqualTo("keyIdFromProperties");
        assertThat(identity.secretAccessKey()).isEqualTo("accessKeyFromProperties");
        assertThat(identity.sessionToken()).isEqualTo("sessionTokenFromProperties");
    });
}

