    iam.putRolePolicy(PutRolePolicyRequest.builder().roleName(roleName).policyName(policyName).policyDocument("{" + "\"Version\":\"2012-10-17\"," + "\"Statement\":[{" + "\"Sid\":\"policy1\"," + "\"Effect\":\"Allow\"," + "\"Action\":[\"glue:CreateDatabase\",\"glue:DeleteDatabase\",\"glue:GetDatabase\",\"glue:GetTables\"]," + "\"Resource\":[\"" + glueArnPrefix + ":catalog\"," + "\"" + glueArnPrefix + ":database/allowed_*\"," + "\"" + glueArnPrefix + ":table/allowed_*/*\"," + "\"" + glueArnPrefix + ":userDefinedFunction/allowed_*/*\"]}]}").build());
    waitForIamConsistency();
    GlueCatalog glueCatalog = new GlueCatalog();
    assumeRoleProperties.put("warehouse", "s3://path");
