@Test
public void testSetTableInputInformation() {
    // Actual TableInput
    TableInput.Builder actualTableInputBuilder = TableInput.builder();
    Schema schema = new Schema(Types.NestedField.required(1, "x", Types.StringType.get(), "comment1"), Types.NestedField.required(2, "y", Types.StructType.of(Types.NestedField.required(3, "z", Types.IntegerType.get())), "comment2"));
    PartitionSpec partitionSpec = PartitionSpec.builderFor(schema).identity("x").withSpecId(1000).build();
    TableMetadata tableMetadata = TableMetadata.newTableMetadata(schema, partitionSpec, "s3://test", tableLocationProperties);
    IcebergToGlueConverter.setTableInputInformation(actualTableInputBuilder, tableMetadata);
    TableInput actualTableInput = actualTableInputBuilder.build();
    // Expected TableInput
    TableInput expectedTableInput = TableInput.builder().storageDescriptor(StorageDescriptor.builder().location("s3://test").additionalLocations(Sets.newHashSet(tableLocationProperties.values())).columns(ImmutableList.of(Column.builder().name("x").type("string").comment("comment1").parameters(ImmutableMap.of(IcebergToGlueConverter.ICEBERG_FIELD_ID, "1", IcebergToGlueConverter.ICEBERG_FIELD_OPTIONAL, "false", IcebergToGlueConverter.ICEBERG_FIELD_CURRENT, "true")).build(), Column.builder().name("y").type("struct<z:int>").comment("comment2").parameters(ImmutableMap.of(IcebergToGlueConverter.ICEBERG_FIELD_ID, "2", IcebergToGlueConverter.ICEBERG_FIELD_OPTIONAL, "false", IcebergToGlueConverter.ICEBERG_FIELD_CURRENT, "true")).build())).build()).build();
    assertThat(actualTableInput.storageDescriptor().additionalLocations()).as("additionalLocations should match").isEqualTo(expectedTableInput.storageDescriptor().additionalLocations());
    assertThat(actualTableInput.storageDescriptor().location()).as("Location should match").isEqualTo(expectedTableInput.storageDescriptor().location());
    assertThat(actualTableInput.storageDescriptor().columns()).as("Columns should match").isEqualTo(expectedTableInput.storageDescriptor().columns());
}

