@ParameterizedTest
@MethodSource("validOAuth2Properties")
void authSessionOAuth2(Map<String, String> properties, String expectedScope, String expectedToken) throws Exception {
    try (S3V4RestSignerClient client = ImmutableS3V4RestSignerClient.builder().properties(properties).build();
        AuthSession authSession = client.authSession()) {
        assertThat(client.optionalOAuthParams()).containsEntry(OAuth2Properties.SCOPE, expectedScope);
        if (expectedToken == null) {
            assertThat(authSession).isInstanceOf(AuthSession.class);
        } else {
            assertThat(authSession).asInstanceOf(type(OAuth2Util.AuthSession.class)).extracting(OAuth2Util.AuthSession::headers).satisfies(headers -> assertThat(headers).containsEntry("Authorization", "Bearer " + expectedToken));
        }
    }
}

