@Test
public void nonExpiredToken() {
    HttpRequest mockRequest = request("/v1/credentials").withMethod(HttpMethod.GET.name());
    Credential credential = ImmutableCredential.builder().prefix("s3").config(ImmutableMap.of(S3FileIOProperties.ACCESS_KEY_ID, "randomAccessKey", S3FileIOProperties.SECRET_ACCESS_KEY, "randomSecretAccessKey", S3FileIOProperties.SESSION_TOKEN, "sessionToken", S3FileIOProperties.SESSION_TOKEN_EXPIRES_AT_MS, Long.toString(Instant.now().plus(1, ChronoUnit.HOURS).toEpochMilli()))).build();
    LoadCredentialsResponse response = ImmutableLoadCredentialsResponse.builder().addCredentials(credential).build();
    HttpResponse mockResponse = response(LoadCredentialsResponseParser.toJson(response)).withStatusCode(200);
    mockServer.when(mockRequest).respond(mockResponse);
    try (VendedCredentialsProvider provider = VendedCredentialsProvider.create(PROPERTIES)) {
        AwsCredentials awsCredentials = provider.resolveCredentials();
        verifyCredentials(awsCredentials, credential);
        for (int i = 0; i < 5; i++) {
            // resolving credentials multiple times should not hit the credentials endpoint again
            assertThat(provider.resolveCredentials()).isSameAs(awsCredentials);
        }
    }
    mockServer.verify(mockRequest, VerificationTimes.once());
}

@Test
public void expiredToken() {
    HttpRequest mockRequest = request("/v1/credentials").withMethod(HttpMethod.GET.name());
    Credential credential = ImmutableCredential.builder().prefix("s3").config(ImmutableMap.of(S3FileIOProperties.ACCESS_KEY_ID, "randomAccessKey", S3FileIOProperties.SECRET_ACCESS_KEY, "randomSecretAccessKey", S3FileIOProperties.SESSION_TOKEN, "sessionToken", S3FileIOProperties.SESSION_TOKEN_EXPIRES_AT_MS, Long.toString(Instant.now().minus(1, ChronoUnit.MINUTES).toEpochMilli()))).build();
    LoadCredentialsResponse response = ImmutableLoadCredentialsResponse.builder().addCredentials(credential).build();
    HttpResponse mockResponse = response(LoadCredentialsResponseParser.toJson(response)).withStatusCode(200);
    mockServer.when(mockRequest).respond(mockResponse);
    try (VendedCredentialsProvider provider = VendedCredentialsProvider.create(PROPERTIES)) {
        AwsCredentials awsCredentials = provider.resolveCredentials();
        verifyCredentials(awsCredentials, credential);
        // resolving credentials multiple times should hit the credentials endpoint again
        AwsCredentials refreshedCredentials = provider.resolveCredentials();
        assertThat(refreshedCredentials).isNotSameAs(awsCredentials);
        verifyCredentials(refreshedCredentials, credential);
    }
    mockServer.verify(mockRequest, VerificationTimes.exactly(2));
}

