@Test
public void nonExpiredTokenInProperties() {
    HttpRequest mockRequest = request("/v1/credentials").withMethod(HttpMethod.GET.name());
    String expiresAt = Long.toString(Instant.now().plus(10, ChronoUnit.HOURS).toEpochMilli());
    Credential credentialFromProperties = ImmutableCredential.builder().prefix("s3").config(ImmutableMap.of(S3FileIOProperties.ACCESS_KEY_ID, "randomAccessKeyFromProperties", S3FileIOProperties.SECRET_ACCESS_KEY, "randomSecretAccessKeyFromProperties", S3FileIOProperties.SESSION_TOKEN, "sessionTokenFromProperties", S3FileIOProperties.SESSION_TOKEN_EXPIRES_AT_MS, expiresAt)).build();
    Credential credential = ImmutableCredential.builder().prefix("s3").config(ImmutableMap.of(S3FileIOProperties.ACCESS_KEY_ID, "randomAccessKey", S3FileIOProperties.SECRET_ACCESS_KEY, "randomSecretAccessKey", S3FileIOProperties.SESSION_TOKEN, "sessionToken", S3FileIOProperties.SESSION_TOKEN_EXPIRES_AT_MS, Long.toString(Instant.now().plus(1, ChronoUnit.HOURS).toEpochMilli()))).build();
    LoadCredentialsResponse response = ImmutableLoadCredentialsResponse.builder().addCredentials(credential).build();
    HttpResponse mockResponse = response(LoadCredentialsResponseParser.toJson(response)).withStatusCode(200);
    mockServer.when(mockRequest).respond(mockResponse);
    try (VendedCredentialsProvider provider = VendedCredentialsProvider.create(ImmutableMap.of(CatalogProperties.URI, CATALOG_URI, VendedCredentialsProvider.URI, CREDENTIALS_URI, S3FileIOProperties.ACCESS_KEY_ID, "randomAccessKeyFromProperties", S3FileIOProperties.SECRET_ACCESS_KEY, "randomSecretAccessKeyFromProperties", S3FileIOProperties.SESSION_TOKEN, "sessionTokenFromProperties", S3FileIOProperties.SESSION_TOKEN_EXPIRES_AT_MS, expiresAt))) {
        AwsCredentials awsCredentials = provider.resolveCredentials();
        verifyCredentials(awsCredentials, credentialFromProperties);
        for (int i = 0; i < 5; i++) {
            // resolving credentials multiple times should not hit the credentials endpoint again
            assertThat(provider.resolveCredentials()).isSameAs(awsCredentials);
