@Test
void authenticateConflictingAuthorizationHeader() {
    HTTPRequest request = Mockito.mock(HTTPRequest.class);
    AuthSession delegate = Mockito.mock(AuthSession.class);
    when(delegate.authenticate(any())).thenReturn(ImmutableHTTPRequest.builder().method(HTTPMethod.GET).baseUri(URI.create("http://localhost:8080")).path("path").headers(HTTPHeaders.of(HTTPHeader.of("Content-Type", "application/json"), HTTPHeader.of("Authorization", "Bearer token"))).build());
