@Test
public void vendedSasTokenAsRequestQueryParameters() {
    String filePath = "file1";
    String container = "container1";
    String validSasToken = "tokenInstance=1";
    String expiredSasToken = "tokenInstance=2";
    VendedAdlsCredentialProvider vendedAdlsCredentialProvider = mock(VendedAdlsCredentialProvider.class);
    VendedAzureSasCredentialPolicy vendedAzureSasCredentialPolicy = new VendedAzureSasCredentialPolicy(STORAGE_ACCOUNT, vendedAdlsCredentialProvider);
    DataLakeFileSystemClient client = new DataLakeFileSystemClientBuilder().httpClient(HttpClient.createDefault()).addPolicy(vendedAzureSasCredentialPolicy).fileSystemName(container).endpoint(ACCOUNT_ENDPOINT).buildClient();
    String requestPath = String.format("/%s/%s/%s", STORAGE_ACCOUNT, container, filePath);
    HttpRequest mockRequestWithValidSasToken = request(requestPath).withMethod(HttpMethod.HEAD.name()).withQueryStringParameter("tokenInstance", "1");
    mockServer.when(mockRequestWithValidSasToken).respond(HttpResponse.response().withStatusCode(200));
    HttpRequest mockRequestWithExpiredSasToken = request(requestPath).withMethod(HttpMethod.HEAD.name()).withQueryStringParameter("tokenInstance", "2");
    mockServer.when(mockRequestWithExpiredSasToken).respond(HttpResponse.response().withStatusCode(403));
    when(vendedAdlsCredentialProvider.credentialForAccount(STORAGE_ACCOUNT)).thenReturn(Mono.just(validSasToken));
    assertThat(client.getFileClient(filePath).exists()).isTrue();
    mockServer.verify(mockRequestWithValidSasToken, VerificationTimes.exactly(1));
    when(vendedAdlsCredentialProvider.credentialForAccount(STORAGE_ACCOUNT)).thenReturn(Mono.just(expiredSasToken));
    // Every new request of the same client fetches latest SasToken credentials from
    // VendedAdlsCredentialProvider to build http request query parameters.
    assertThatThrownBy(() -> client.getFileClient(filePath).exists()).isInstanceOf(DataLakeStorageException.class).hasMessageContaining("If you are using a SAS token, and the server returned an error message that says 'Signature did not match'");
    mockServer.verify(mockRequestWithExpiredSasToken, VerificationTimes.atLeast(1));
}

