    Schema projection = new Schema(SCHEMA.columns().get(0), MetadataColumns.ROW_POSITION, SCHEMA.columns().get(1));
    List<Record> records = readAvro(file, projection, 0, file.getLength());
    for (int i = 0; i < expected.size(); i += 1) {
        assertThat(records.get(i).getField(MetadataColumns.ROW_POSITION.name())).as("Field _pos should match").isEqualTo((long) i);
        assertThat(records.get(i).getField("id")).as("Field id should match").isEqualTo(expected.get(i).getField("id"));
        assertThat(records.get(i).getField("data")).as("Field data should match").isEqualTo(expected.get(i).getField("data"));
    }
}

@Test
public void testPosFieldWithSplits() throws IOException {
    Schema projection = new Schema(SCHEMA.columns().get(0), MetadataColumns.ROW_POSITION, SCHEMA.columns().get(1));
    long end = file.getLength();
    long splitLocation = end / 2;
    List<Record> secondHalf = readAvro(file, projection, splitLocation + 1, end - splitLocation - 1);
    assertThat(secondHalf.size()).as("Second split should not be empty").isNotEqualTo(0);
    List<Record> firstHalf = readAvro(file, projection, 0, splitLocation);
    assertThat(firstHalf.size()).as("First split should not be empty").isNotEqualTo(0);
    assertThat(firstHalf.size() + secondHalf.size()).as("Total records should match expected").isEqualTo(expected.size());
    for (int i = 0; i < firstHalf.size(); i += 1) {
        assertThat(firstHalf.get(i).getField(MetadataColumns.ROW_POSITION.name())).as("Field _pos should match").isEqualTo((long) i);
        assertThat(firstHalf.get(i).getField("id")).as("Field id should match").isEqualTo(expected.get(i).getField("id"));
        assertThat(firstHalf.get(i).getField("data")).as("Field data should match").isEqualTo(expected.get(i).getField("data"));
    }
    for (int i = 0; i < secondHalf.size(); i += 1) {
        assertThat(secondHalf.get(i).getField(MetadataColumns.ROW_POSITION.name())).as("Field _pos should match").isEqualTo((long) (firstHalf.size() + i));
        assertThat(secondHalf.get(i).getField("id")).as("Field id should match").isEqualTo(expected.get(firstHalf.size() + i).getField("id"));
        assertThat(secondHalf.get(i).getField("data")).as("Field data should match").isEqualTo(expected.get(firstHalf.size() + i).getField("data"));
    }
}

