@Test
public void testRemoveIdsHasIds() {
    Schema schema = new Schema(Types.NestedField.required(0, "id", Types.LongType.get()), Types.NestedField.optional(5, "location", Types.MapType.ofOptional(6, 7, Types.StringType.get(), Types.StructType.of(Types.NestedField.required(1, "lat", Types.FloatType.get()), Types.NestedField.optional(2, "long", Types.FloatType.get())))), Types.NestedField.required(8, "types", Types.ListType.ofRequired(9, Types.StringType.get())), Types.NestedField.required(10, "data", Types.VariantType.get()));
    org.apache.avro.Schema avroSchema = RemoveIds.removeIds(schema);
    assertThat(AvroSchemaUtil.hasIds(avroSchema)).as("Avro schema should not have IDs").isFalse();
    avroSchema.getFields().get(0).addProp("field-id", 1);
    assertThat(AvroSchemaUtil.hasIds(avroSchema)).as("Avro schema should have IDs").isTrue();
    // Create a fresh copy
    avroSchema = RemoveIds.removeIds(schema);
    avroSchema.getFields().get(1).schema().getTypes().get(1).getValueType().getTypes().get(1).getFields().get(1).addProp("field-id", 1);
    assertThat(AvroSchemaUtil.hasIds(avroSchema)).as("Avro schema should have IDs").isTrue();
}

