@Test
public void testDefaultAppliedWhenMissingColumn() throws IOException {
    for (Object[] typeAndDefault : TYPES_WITH_DEFAULTS) {
        Type type = (Type) typeAndDefault[0];
        String defaultValueJson = (String) typeAndDefault[1];
        Object defaultValue = SingleValueParser.fromJson(type, defaultValueJson);
        // note that this schema does not have column "defaulted"
        Schema writerSchema = new Schema(required(999, "written", Types.IntegerType.get()));
        File testFile = temp.resolve("test" + System.nanoTime() + ".avro").toFile();
        testFile.delete();
        try (FileAppender<Record> writer = Avro.write(Files.localOutput(testFile)).schema(writerSchema).createWriterFunc(GenericAvroWriter::create).named("test").build()) {
            Record record = new Record(AvroSchemaUtil.convert(writerSchema.asStruct()));
            record.put(0, 1);
            writer.add(record);
        }
        Schema readerSchema = new Schema(Types.NestedField.required("written").withId(999).ofType(Types.IntegerType.get()).build(), Types.NestedField.optional("defaulted").withId(1000).ofType(type).withInitialDefault(Expressions.lit(defaultValue)).build());
        Record expectedRecord = new Record(AvroSchemaUtil.convert(readerSchema.asStruct()));
        expectedRecord.put(0, 1);
        expectedRecord.put(1, defaultValue);
        List<Record> rows;
        try (AvroIterable<Record> reader = Avro.read(Files.localInput(testFile)).project(readerSchema).createResolvingReader(schema -> GenericAvroReader.create(schema)).build()) {
            rows = Lists.newArrayList(reader);
        }
        AvroTestHelpers.assertEquals(readerSchema.asStruct(), expectedRecord, rows.get(0));
    }
}

@Test
public void testDefaultDoesNotOverrideExplicitValue() throws IOException {
    for (Object[] typeAndDefault : TYPES_WITH_DEFAULTS) {
        Type type = (Type) typeAndDefault[0];
        String defaultValueJson = (String) typeAndDefault[1];
        Literal<?> defaultValue = Expressions.lit(SingleValueParser.fromJson(type, defaultValueJson));
        Schema readerSchema = new Schema(Types.NestedField.required("written_1").withId(999).ofType(Types.IntegerType.get()).build(), Types.NestedField.optional("written_2").withId(1000).ofType(type).withInitialDefault(defaultValue).build());
        // Create a record with null value for the column with default value
        Record expectedRecord = new Record(AvroSchemaUtil.convert(readerSchema.asStruct()));
        expectedRecord.put(0, 1);
        expectedRecord.put(1, null);
        File testFile = temp.resolve("test" + System.nanoTime() + ".avro").toFile();
        testFile.delete();
        try (FileAppender<Record> writer = Avro.write(Files.localOutput(testFile)).schema(readerSchema).createWriterFunc(GenericAvroWriter::create).named("test").build()) {
            writer.add(expectedRecord);
        }
        List<Record> rows;
        try (AvroIterable<Record> reader = Avro.read(Files.localInput(testFile)).project(readerSchema).createReaderFunc(GenericAvroReader::create).build()) {
            rows = Lists.newArrayList(reader);
        }
        // Existence of default value should not affect the read result
        AvroTestHelpers.assertEquals(readerSchema.asStruct(), expectedRecord, rows.get(0));
    }
}

