    assertEmpty("Should not have tables in a new namespace, ns_2", catalog, ns2);
    catalog.buildTable(ns1Table1, SCHEMA).create();
    assertThat(catalog.listTables(ns1)).as("Should contain ns_1.table_1 after create").containsExactlyInAnyOrder(ns1Table1);
    catalog.buildTable(ns2Table1, SCHEMA).create();
    assertThat(catalog.listTables(ns2)).as("Should contain ns_2.table_1 after create").containsExactlyInAnyOrder(ns2Table1);
    assertThat(catalog.listTables(ns1)).as("Should not show changes to ns_2 in ns_1").containsExactlyInAnyOrder(ns1Table1);
    catalog.buildTable(ns1Table2, SCHEMA).create();
    assertThat(catalog.listTables(ns2)).as("Should not show changes to ns_1 in ns_2").containsExactlyInAnyOrder(ns2Table1);
    assertThat(catalog.listTables(ns1)).as("Should contain ns_1.table_2 after create").containsExactlyInAnyOrder(ns1Table1, ns1Table2);
    catalog.dropTable(ns1Table1);
    assertThat(catalog.listTables(ns2)).as("Should not show changes to ns_1 in ns_2").containsExactlyInAnyOrder(ns2Table1);
    assertThat(catalog.listTables(ns1)).as("Should not contain ns_1.table_1 after drop").containsExactlyInAnyOrder(ns1Table2);
    catalog.dropTable(ns1Table2);
    assertThat(catalog.listTables(ns2)).as("Should not show changes to ns_1 in ns_2").containsExactlyInAnyOrder(ns2Table1);
    assertEmpty("Should not contain ns_1.table_2 after drop", catalog, ns1);
    catalog.dropTable(ns2Table1);
    assertEmpty("Should not contain ns_2.table_1 after drop", catalog, ns2);
}

