@Test
public void testForEach() {
    // Container 0 (high bits = 0)
    long pos1 = 10L;
    // Container 1 (high bits = 1)
    long pos2 = 1L << 33;
    // Container 1 (high bits = 1)
    long pos3 = pos2 + 1;
    // Container 2 (high bits = 2)
    long pos4 = 2L << 33;
    // Container 2 (high bits = 2)
    long pos5 = pos4 + 1;
    // Container 3 (high bits = 3)
    long pos6 = 3L << 33;
    PositionDeleteIndex index = new BitmapPositionDeleteIndex();
    // add in any order
    index.delete(pos1);
    index.delete(pos6);
    index.delete(pos2);
    index.delete(pos3);
    index.delete(pos5);
    index.delete(pos4);
    // output must be sorted in ascending order across containers
    List<Long> positions = collect(index);
    assertThat(positions).containsExactly(pos1, pos2, pos3, pos4, pos5, pos6);
}

