@Test
public void testIntegerIn() {
    assertThat(shouldRead(in(extract("variant", "$.event_id", "long"), INT_MIN_VALUE - 25, INT_MIN_VALUE - 24))).as("Should not read: id below lower bound (5 < 30, 6 < 30)").isFalse();
    assertThat(shouldRead(in(extract("variant", "$.event_id", "long"), INT_MIN_VALUE - 2, INT_MIN_VALUE - 1))).as("Should not read: id below lower bound (28 < 30, 29 < 30)").isFalse();
    assertThat(shouldRead(in(extract("variant", "$.event_id", "long"), INT_MIN_VALUE - 1, INT_MIN_VALUE))).as("Should read: id equal to lower bound (30 == 30)").isTrue();
    assertThat(shouldRead(in(extract("variant", "$.event_id", "long"), INT_MAX_VALUE - 4, INT_MAX_VALUE - 3))).as("Should read: id between lower and upper bounds (30 < 75 < 79, 30 < 76 < 79)").isTrue();
    assertThat(shouldRead(in(extract("variant", "$.event_id", "long"), INT_MAX_VALUE, INT_MAX_VALUE + 1))).as("Should read: id equal to upper bound (79 == 79)").isTrue();
    assertThat(shouldRead(in(extract("variant", "$.event_id", "long"), INT_MAX_VALUE + 1, INT_MAX_VALUE + 2))).as("Should not read: id above upper bound (80 > 79, 81 > 79)").isFalse();
    assertThat(shouldRead(in(extract("variant", "$.event_id", "long"), INT_MAX_VALUE + 6, INT_MAX_VALUE + 7))).as("Should not read: id above upper bound (85 > 79, 86 > 79)").isFalse();
    // should read as the number of elements in the in expression is too big
    List<Integer> ids = Lists.newArrayListWithExpectedSize(400);
    for (int id = -400; id <= 0; id++) {
        ids.add(id);
    }
    assertThat(shouldRead(in(extract("variant", "$.event_id", "long"), ids))).as("Should read: large in expression").isTrue();
}

