@Test
public void testConcurrentFastAppends(@TempDir File dir) throws Exception {
    assertThat(version(1)).as("Should create v1 metadata").exists().isFile();
    int threadsCount = 5;
    int numberOfCommitedFilesPerThread = 10;
    Table tableWithHighRetries = TABLES.create(SCHEMA, SPEC, ImmutableMap.of(COMMIT_NUM_RETRIES, String.valueOf(threadsCount), COMMIT_MIN_RETRY_WAIT_MS, "10", COMMIT_MAX_RETRY_WAIT_MS, "1000", // Disable extra retry on lock acquire failure since commit will fail anyway.
    LOCK_ACQUIRE_TIMEOUT_MS, "0"), dir.toURI().toString());
    String fileName = UUID.randomUUID().toString();
    DataFile file = DataFiles.builder(tableWithHighRetries.spec()).withPath(FileFormat.PARQUET.addExtension(fileName)).withRecordCount(2).withFileSizeInBytes(0).build();
    ExecutorService executorService = Executors.newFixedThreadPool(threadsCount);
    AtomicInteger barrier = new AtomicInteger(0);
    Tasks.range(threadsCount).stopOnFailure().throwFailureWhenFinished().executeWith(executorService).run(index -> {
        for (int numCommittedFiles = 0; numCommittedFiles < numberOfCommitedFilesPerThread; numCommittedFiles++) {
            final int currentFilesCount = numCommittedFiles;
            Awaitility.await().pollInterval(Duration.ofMillis(10)).atMost(Duration.ofSeconds(60)).until(() -> barrier.get() >= currentFilesCount * threadsCount);
            tableWithHighRetries.newFastAppend().appendFile(file).commit();
            barrier.incrementAndGet();
        }
    });
    tableWithHighRetries.refresh();
    assertThat(Lists.newArrayList(tableWithHighRetries.snapshots())).hasSize(threadsCount * numberOfCommitedFilesPerThread);
}

