@Test
public void testSliceBuffersModification() throws Exception {
    ByteBufferInputStream stream = newStream();
    int length = stream.available();
    int sliceLength = 5;
    List<ByteBuffer> buffers = stream.sliceBuffers(sliceLength);
    assertThat(stream.available()).as("Should advance the original stream").isEqualTo(length - sliceLength);
    assertThat(stream.getPos()).as("Should advance the original stream position").isEqualTo(sliceLength);
    assertThat(buffers.size()).as("Should return a slice of the first buffer").isEqualTo(1);
    ByteBuffer buffer = buffers.get(0);
    assertThat(buffer.remaining()).as("Should have requested bytes").isEqualTo(sliceLength);
    // read the buffer one past the returned limit. this should not change the
    // next value in the original stream
    buffer.limit(sliceLength + 1);
    for (int i = 0; i < sliceLength + 1; i += 1) {
        assertThat(buffer.get()).as("Should have correct data").isEqualTo((byte) i);
    }
    assertThat(stream.getPos()).as("Reading a slice shouldn't advance the original stream").isEqualTo(sliceLength);
    assertThat(stream.read()).as("Reading a slice shouldn't change the underlying data").isEqualTo(sliceLength);
    // change the underlying data buffer
    buffer.limit(sliceLength + 2);
    int originalValue = buffer.duplicate().get();
    ByteBuffer undoBuffer = buffer.duplicate();
    try {
        buffer.put((byte) 255);
        assertThat(stream.getPos()).as("Writing to a slice shouldn't advance the original stream").isEqualTo(sliceLength + 1);
        assertThat(stream.read()).as("Writing to a slice should change the underlying data").isEqualTo(255);
    } finally {
        undoBuffer.put((byte) originalValue);
    }
}

