    String jdbcUrl = "jdbc:sqlite:" + dbFile.toAbsolutePath();
    SQLiteDataSource dataSource = new SQLiteDataSource();
    dataSource.setUrl(jdbcUrl);
    try (JdbcClientPool connections = new JdbcClientPool(jdbcUrl, Maps.newHashMap())) {
        // create "old style" SQL schema
        connections.newClient().prepareStatement(JdbcUtil.V0_CREATE_CATALOG_SQL).executeUpdate();
        // inserting tables
        JdbcUtil.doCommitCreateTable(JdbcUtil.SchemaVersion.V0, connections, "TEST", Namespace.of("namespace1"), TableIdentifier.of(Namespace.of("namespace1"), "table1"), "testLocation");
        JdbcUtil.doCommitCreateTable(JdbcUtil.SchemaVersion.V0, connections, "TEST", Namespace.of("namespace1"), TableIdentifier.of(Namespace.of("namespace1"), "table2"), "testLocation");
        try (PreparedStatement statement = connections.newClient().prepareStatement(JdbcUtil.V0_LIST_TABLE_SQL)) {
            statement.setString(1, "TEST");
            statement.setString(2, "namespace1");
            ResultSet tables = statement.executeQuery();
            tables.next();
            assertThat(tables.getString(JdbcUtil.TABLE_NAME)).isEqualTo("table1");
            tables.next();
            assertThat(tables.getString(JdbcUtil.TABLE_NAME)).isEqualTo("table2");
        }
        // updating the schema from V0 to V1
        connections.newClient().prepareStatement(JdbcUtil.V1_UPDATE_CATALOG_SQL).execute();
        // trying to add a table on the updated schema
        JdbcUtil.doCommitCreateTable(JdbcUtil.SchemaVersion.V1, connections, "TEST", Namespace.of("namespace1"), TableIdentifier.of(Namespace.of("namespace1"), "table3"), "testLocation");
        // testing the tables after migration and new table added
        try (PreparedStatement statement = connections.newClient().prepareStatement(JdbcUtil.V0_LIST_TABLE_SQL)) {
            statement.setString(1, "TEST");
            statement.setString(2, "namespace1");
            ResultSet tables = statement.executeQuery();
            tables.next();
            assertThat(tables.getString(JdbcUtil.TABLE_NAME)).isEqualTo("table1");
            assertThat(tables.getString(JdbcUtil.RECORD_TYPE)).isNull();
            tables.next();
            assertThat(tables.getString(JdbcUtil.TABLE_NAME)).isEqualTo("table2");
            assertThat(tables.getString(JdbcUtil.RECORD_TYPE)).isNull();
            tables.next();
            assertThat(tables.getString(JdbcUtil.TABLE_NAME)).isEqualTo("table3");
            assertThat(tables.getString(JdbcUtil.RECORD_TYPE)).isEqualTo(JdbcUtil.TABLE_RECORD_TYPE);
        }
        // update a table (commit) created on V1 schema
        int updated = JdbcUtil.updateTable(JdbcUtil.SchemaVersion.V1, connections, "TEST", TableIdentifier.of(Namespace.of("namespace1"), "table3"), "newLocation", "testLocation");
        assertThat(updated).isEqualTo(1);
        // update a table (commit) migrated from V0 schema
        updated = JdbcUtil.updateTable(JdbcUtil.SchemaVersion.V1, connections, "TEST", TableIdentifier.of(Namespace.of("namespace1"), "table1"), "newLocation", "testLocation");
        assertThat(updated).isEqualTo(1);
    }
}

