@Test
public void testPartitionStats() throws Exception {
    Table testTable = TestTables.create(tempDir("partition_stats_compute"), "partition_stats_compute", SCHEMA, SPEC, 2, fileFormatProperty);
    DataFile dataFile1 = FileGenerationUtil.generateDataFile(testTable, TestHelpers.Row.of("foo", "A"));
    DataFile dataFile2 = FileGenerationUtil.generateDataFile(testTable, TestHelpers.Row.of("foo", "B"));
    DataFile dataFile3 = FileGenerationUtil.generateDataFile(testTable, TestHelpers.Row.of("bar", "A"));
    DataFile dataFile4 = FileGenerationUtil.generateDataFile(testTable, TestHelpers.Row.of("bar", "B"));
    for (int i = 0; i < 3; i++) {
        // insert same set of seven records thrice to have a new manifest files
        testTable.newAppend().appendFile(dataFile1).appendFile(dataFile2).appendFile(dataFile3).appendFile(dataFile4).commit();
    }
    Snapshot snapshot1 = testTable.currentSnapshot();
    Schema recordSchema = PartitionStatsHandler.schema(Partitioning.partitionType(testTable), 2);
    Types.StructType partitionType = recordSchema.findField(PARTITION_FIELD_ID).type().asStructType();
    computeAndValidatePartitionStats(testTable, recordSchema, Tuple.tuple(partitionRecord(partitionType, "foo", "A"), 0, 3 * dataFile1.recordCount(), 3, 3 * dataFile1.fileSizeInBytes(), 0L, 0, 0L, 0, null, snapshot1.timestampMillis(), snapshot1.snapshotId(), 0), Tuple.tuple(partitionRecord(partitionType, "foo", "B"), 0, 3 * dataFile2.recordCount(), 3, 3 * dataFile2.fileSizeInBytes(), 0L, 0, 0L, 0, null, snapshot1.timestampMillis(), snapshot1.snapshotId(), 0), Tuple.tuple(partitionRecord(partitionType, "bar", "A"), 0, 3 * dataFile3.recordCount(), 3, 3 * dataFile3.fileSizeInBytes(), 0L, 0, 0L, 0, null, snapshot1.timestampMillis(), snapshot1.snapshotId(), 0), Tuple.tuple(partitionRecord(partitionType, "bar", "B"), 0, 3 * dataFile4.recordCount(), 3, 3 * dataFile4.fileSizeInBytes(), 0L, 0, 0L, 0, null, snapshot1.timestampMillis(), snapshot1.snapshotId(), 0));
    DeleteFile posDelete = FileGenerationUtil.generatePositionDeleteFile(testTable, TestHelpers.Row.of("bar", "A"));
    testTable.newRowDelta().addDeletes(posDelete).commit();
    // snapshot2 is unused in the result as same partition was updated by snapshot4
    DeleteFile eqDelete = FileGenerationUtil.generateEqualityDeleteFile(testTable, TestHelpers.Row.of("foo", "A"));
    testTable.newRowDelta().addDeletes(eqDelete).commit();
    Snapshot snapshot3 = testTable.currentSnapshot();
    testTable.updateProperties().set(TableProperties.FORMAT_VERSION, "3").commit();
    DeleteFile dv = FileGenerationUtil.generateDV(testTable, dataFile3);
    testTable.newRowDelta().addDeletes(dv).commit();
    Snapshot snapshot4 = testTable.currentSnapshot();
    recordSchema = PartitionStatsHandler.schema(Partitioning.partitionType(testTable), 3);
    computeAndValidatePartitionStats(testTable, recordSchema, Tuple.tuple(partitionRecord(partitionType, "foo", "A"), 0, 3 * dataFile1.recordCount(), 3, 3 * dataFile1.fileSizeInBytes(), 0L, 0, eqDelete.recordCount(), 1, null, snapshot3.timestampMillis(), snapshot3.snapshotId(), 0), Tuple.tuple(partitionRecord(partitionType, "foo", "B"), 0, 3 * dataFile2.recordCount(), 3, 3 * dataFile2.fileSizeInBytes(), 0L, 0, 0L, 0, null, snapshot1.timestampMillis(), snapshot1.snapshotId(), 0), Tuple.tuple(partitionRecord(partitionType, "bar", "A"), 0, 3 * dataFile3.recordCount(), 3, 3 * dataFile3.fileSizeInBytes(), posDelete.recordCount() + dv.recordCount(), 1, 0L, 0, null, snapshot4.timestampMillis(), snapshot4.snapshotId(), // dv count
    1), Tuple.tuple(partitionRecord(partitionType, "bar", "B"), 0, 3 * dataFile4.recordCount(), 3, 3 * dataFile4.fileSizeInBytes(), 0L, 0, 0L, 0, null, snapshot1.timestampMillis(), snapshot1.snapshotId(), 0));
}

@Test
public void testCopyOnWriteDelete() throws Exception {
    Table testTable = TestTables.create(tempDir("my_test"), "my_test", SCHEMA, SPEC, 2, fileFormatProperty);
    DataFile dataFile1 = DataFiles.builder(SPEC).withPath("/df1.parquet").withPartitionPath("c2=a/c3=a").withFileSizeInBytes(10).withRecordCount(1).build();
    DataFile dataFile2 = DataFiles.builder(SPEC).withPath("/df2.parquet").withPartitionPath("c2=b/c3=b").withFileSizeInBytes(10).withRecordCount(1).build();
    testTable.newAppend().appendFile(dataFile1).appendFile(dataFile2).commit();
    PartitionStatisticsFile statisticsFile = PartitionStatsHandler.computeAndWriteStatsFile(testTable);
    testTable.updatePartitionStatistics().setPartitionStatistics(statisticsFile).commit();
    assertThat(PartitionStatsHandler.readPartitionStatsFile(PartitionStatsHandler.schema(Partitioning.partitionType(testTable), 2), testTable.io().newInputFile(statisticsFile.path()))).allMatch(s -> (s.dataRecordCount() != 0 && s.dataFileCount() != 0));
    testTable.newDelete().deleteFile(dataFile1).commit();
    testTable.newDelete().deleteFile(dataFile2).commit();
    PartitionStatisticsFile statisticsFileNew = PartitionStatsHandler.computeAndWriteStatsFile(testTable);
    // stats must be decremented to zero as all the files removed from table.
    assertThat(PartitionStatsHandler.readPartitionStatsFile(PartitionStatsHandler.schema(Partitioning.partitionType(testTable), 2), testTable.io().newInputFile(statisticsFileNew.path()))).allMatch(s -> (s.dataRecordCount() == 0 && s.dataFileCount() == 0));
}

