    try (DefaultAuthSession session = DefaultAuthSession.of(HTTPHeaders.of(HTTPHeader.of("Authorization", "s3cr3t")))) {
        HTTPRequest original = ImmutableHTTPRequest.builder().method(HTTPMethod.GET).baseUri(URI.create("https://localhost")).path("path").build();
        HTTPRequest authenticated = session.authenticate(original);
        assertThat(authenticated.headers().entries()).singleElement().extracting(HTTPHeader::name, HTTPHeader::value).containsExactly("Authorization", "s3cr3t");
    }
}

@Test
void authenticateWithConflictingHeader() {
    try (DefaultAuthSession session = DefaultAuthSession.of(HTTPHeaders.of(HTTPHeader.of("Authorization", "s3cr3t")))) {
        HTTPRequest original = ImmutableHTTPRequest.builder().method(HTTPMethod.GET).baseUri(URI.create("https://localhost")).path("path").headers(HTTPHeaders.of(HTTPHeader.of("Authorization", "other"))).build();
        HTTPRequest authenticated = session.authenticate(original);
        assertThat(authenticated).isSameAs(original);
    }
}

