@Test
void close() {
    Map<String, String> catalogProperties = Map.of();
    SessionCatalog.SessionContext context = new SessionCatalog.SessionContext("test", "test", Map.of(OAuth2Properties.TOKEN, "context-token"), Map.of());
    Map<String, String> tableProperties = Map.of(OAuth2Properties.TOKEN, "table-token");
    TableIdentifier table = TableIdentifier.of("ns", "tbl");
    try (OAuth2Manager manager = new OAuth2Manager("test") {

        @Override
        protected AuthSessionCache newSessionCache(String name, Map<String, String> properties) {
            return new AuthSessionCache(Duration.ofHours(1), Runnable::run, Ticker.systemTicker());
        }

        @Override
        protected OAuth2Util.AuthSession newSessionFromAccessToken(String token, Map<String, String> properties, OAuth2Util.AuthSession parent) {
            return Mockito.spy(super.newSessionFromAccessToken(token, properties, parent));
        }
    };
        OAuth2Util.AuthSession catalogSession = manager.catalogSession(client, catalogProperties);
        OAuth2Util.AuthSession contextualSession = manager.contextualSession(context, catalogSession);
        OAuth2Util.AuthSession tableSession = manager.tableSession(table, tableProperties, contextualSession)) {
        manager.close();
        assertThat(manager).extracting("sessionCache").as("should close session cache").isNull();
        // all cached sessions should be closed
        Mockito.verify(contextualSession).close();
        Mockito.verify(tableSession).close();
    }
    Mockito.verify(client).withAuthSession(any());
    Mockito.verifyNoMoreInteractions(client);
}

@Test
public void testOAuthScopeTokenValidation() {
    // valid scope tokens are from ascii 0x21 to 0x7E, excluding 0x22 (") and 0x5C (\)
    // test characters that are outside of the ! to ~ range and the excluded characters, " and \
    assertThat(OAuth2Util.isValidScopeToken("a\\b")).as("Should reject scope token with \\").isFalse();
    assertThat(OAuth2Util.isValidScopeToken("a b")).as("Should reject scope token with space").isFalse();
    assertThat(OAuth2Util.isValidScopeToken("a\"b")).as("Should reject scope token with \"").isFalse();
    assertThat(OAuth2Util.isValidScopeToken("\u007F")).as("Should reject scope token with DEL").isFalse();
    // test all characters that are inside of the ! to ~ range and are not excluded
    assertThat(OAuth2Util.isValidScopeToken("!#$%&'()*+,-./")).as("Should accept scope token with !-/").isTrue();
    assertThat(OAuth2Util.isValidScopeToken("0123456789")).as("Should accept scope token with 0-9").isTrue();
    assertThat(OAuth2Util.isValidScopeToken(":;<=>?@")).as("Should accept scope token with :-@").isTrue();
    assertThat(OAuth2Util.isValidScopeToken("ABCDEFGHIJKLM")).as("Should accept scope token with A-M").isTrue();
    assertThat(OAuth2Util.isValidScopeToken("NOPQRSTUVWXYZ")).as("Should accept scope token with N-Z").isTrue();
    assertThat(OAuth2Util.isValidScopeToken("[]^_`")).as("Should accept scope token with [-`, not \\").isTrue();
    assertThat(OAuth2Util.isValidScopeToken("abcdefghijklm")).as("Should accept scope token with a-m").isTrue();
    assertThat(OAuth2Util.isValidScopeToken("nopqrstuvwxyz")).as("Should accept scope token with n-z").isTrue();
    assertThat(OAuth2Util.isValidScopeToken("{|}~")).as("Should accept scope token with {-~").isTrue();
}

@Test
public void testExpiresAt() {
    assertThat(OAuth2Util.expiresAtMillis(null)).isNull();
    assertThat(OAuth2Util.expiresAtMillis("not a token")).isNull();
    assertThat(OAuth2Util.expiresAtMillis("a.b.c")).isNull();
    // expires at epoch second = 1
    String token = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiIxMjM0NTY3ODkwIiwibmFtZSI6IkpvaG4gRG9lIiwiaWF0IjoxNTE2MjM5MDIyLCJleHAiOjF9.gQADTbdEv-rpDWKSkGLbmafyB5UUjTdm9B_1izpuZ6E";
    assertThat(OAuth2Util.expiresAtMillis(token)).isEqualTo(1000L);
    // expires at epoch second = 19999999999
    token = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiIxMjM0NTY3ODkwIiwibmFtZSI6IkpvaG4gRG9lIiwiaWF0IjoxNTE2MjM5MDIyLCJleHAiOjE5OTk5OTk5OTk5fQ._3k92KJi2NTyTG6V1s2mzJ__GiQtL36DnzsZSkBdYPw";
    assertThat(OAuth2Util.expiresAtMillis(token)).isEqualTo(19999999999000L);
    // no expiration
    token = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiIxMjM0NTY3ODkwIiwibmFtZSI6IkpvaG4gRG9lIiwiaWF0IjoxNTE2MjM5MDIyfQ.SflKxwRJSMeKKF2QT4fwpMeJf36POk6yJV_adQssw5c";
    assertThat(OAuth2Util.expiresAtMillis(token)).isNull();
}

@Test
public void testCredentialFlowForSessionRefresh() throws IOException {
    AuthConfig authConfig = ImmutableAuthConfig.builder().keepRefreshed(true).exchangeEnabled(false).token("test_token").credential("testClientId:testClientSecret").oauth2ServerUri("/v1/token").expiresAtMillis(System.currentTimeMillis()).build();
    OAuthTokenResponse response = OAuthTokenResponse.builder().withToken("refreshed_token").withTokenType(BEARER).build();
    try (RESTClient client = Mockito.mock(RESTClient.class);
        OAuth2Util.AuthSession session = new OAuth2Util.AuthSession(Map.of(), authConfig)) {
        Mockito.when(client.postForm(any(), anyMap(), any(), anyMap(), any())).thenReturn(response);
        session.refresh(client);
        Mockito.verify(client).postForm(any(), argThat(formData -> formData.containsKey(GRANT_TYPE) && formData.get(GRANT_TYPE).equals(CLIENT_CREDENTIALS)), Mockito.eq(OAuthTokenResponse.class), anyMap(), any());
    }
}

@Test
public void nullAndEmptyCheck() {
    assertThatThrownBy(() -> CredentialParser.toJson(null)).isInstanceOf(IllegalArgumentException.class).hasMessage("Invalid credential: null");
    assertThatThrownBy(() -> CredentialParser.fromJson((JsonNode) null)).isInstanceOf(IllegalArgumentException.class).hasMessage("Cannot parse credential from null object");
}

@Test
public void invalidOrMissingFields() {
    assertThatThrownBy(() -> CredentialParser.fromJson("{}")).isInstanceOf(IllegalArgumentException.class).hasMessage("Cannot parse missing string: prefix");
    assertThatThrownBy(() -> CredentialParser.fromJson("{\"prefix\": \"y\"}")).isInstanceOf(IllegalArgumentException.class).hasMessage("Cannot parse missing map: config");
    assertThatThrownBy(() -> CredentialParser.fromJson("{\"prefix\": \"\", \"config\": {\"x\": \"23\"}}")).isInstanceOf(IllegalArgumentException.class).hasMessage("Invalid prefix: must be non-empty");
    assertThatThrownBy(() -> CredentialParser.fromJson("{\"prefix\": \"s3\", \"config\": {}}")).isInstanceOf(IllegalArgumentException.class).hasMessage("Invalid config: must be non-empty");
}

@Test
public void s3Credential() {
    Credential credential = ImmutableCredential.builder().prefix("s3://custom-uri").config(ImmutableMap.of("s3.access-key-id", "keyId", "s3.secret-access-key", "accessKey", "s3.session-token", "sessionToken")).build();
    String expectedJson = "{\n" + "  \"prefix\" : \"s3://custom-uri\",\n" + "  \"config\" : {\n" + "    \"s3.access-key-id\" : \"keyId\",\n" + "    \"s3.secret-access-key\" : \"accessKey\",\n" + "    \"s3.session-token\" : \"sessionToken\"\n" + "  }\n" + "}";
    String json = CredentialParser.toJson(credential, true);
    assertThat(json).isEqualTo(expectedJson);
    assertThat(CredentialParser.toJson(CredentialParser.fromJson(json), true)).isEqualTo(expectedJson);
}

