    assertThat(actual.entries()).containsExactly(HTTPHeader.of("header1", "value1a"), HTTPHeader.of("HEADER1", "value1b"), HTTPHeader.of("header2", "value2"), HTTPHeader.of("header3", "value3"));
    assertThatThrownBy(() -> headers.putIfAbsent((HTTPHeader) null)).isInstanceOf(NullPointerException.class).hasMessage("header");
