@Test
public void testTableSnapshotLoading() {
    RESTCatalogAdapter adapter = Mockito.spy(new RESTCatalogAdapter(backendCatalog));
    RESTCatalog catalog = new RESTCatalog(SessionCatalog.SessionContext.createEmpty(), (config) -> adapter);
    catalog.initialize("test", ImmutableMap.of(CatalogProperties.URI, "ignored", CatalogProperties.FILE_IO_IMPL, "org.apache.iceberg.inmemory.InMemoryFileIO", // default loading to refs only
    RESTCatalogProperties.SNAPSHOT_LOADING_MODE, SnapshotMode.REFS.name()));
    if (requiresNamespaceCreate()) {
        catalog.createNamespace(TABLE.namespace());
    }
    // Create a table with multiple snapshots
    Table table = catalog.createTable(TABLE, SCHEMA);
    table.newFastAppend().appendFile(DataFiles.builder(PartitionSpec.unpartitioned()).withPath("/path/to/data-a.parquet").withFileSizeInBytes(10).withRecordCount(2).build()).commit();
    table.newFastAppend().appendFile(DataFiles.builder(PartitionSpec.unpartitioned()).withPath("/path/to/data-b.parquet").withFileSizeInBytes(10).withRecordCount(2).build()).commit();
    ResourcePaths paths = ResourcePaths.forCatalogProperties(Maps.newHashMap());
    Table refsTable = catalog.loadTable(TABLE);
    // don't call snapshots() directly as that would cause to load all snapshots. Instead,
    // make sure the snapshots field holds exactly 1 snapshot
    assertThat(((BaseTable) refsTable).operations().current()).extracting("snapshots").asInstanceOf(InstanceOfAssertFactories.list(Snapshot.class)).hasSize(1);
    assertThat(refsTable.currentSnapshot()).isEqualTo(table.currentSnapshot());
    // verify that the table was loaded with the refs argument
    verify(adapter, times(1)).execute(reqMatcher(HTTPMethod.GET, paths.table(TABLE), Map.of(), Map.of("snapshots", "refs")), eq(LoadTableResponse.class), any(), any());
    // verify that all snapshots are loaded when referenced
    assertThat(refsTable.snapshots()).containsExactlyInAnyOrderElementsOf(table.snapshots());
    verify(adapter, times(1)).execute(reqMatcher(HTTPMethod.GET, paths.table(TABLE), Map.of(), Map.of("snapshots", "all")), eq(LoadTableResponse.class), any(), any());
}

@ParameterizedTest
@ValueSource(strings = { "1", "2" })
public void testTableSnapshotLoadingWithDivergedBranches(String formatVersion) {
    RESTCatalogAdapter adapter = Mockito.spy(new RESTCatalogAdapter(backendCatalog));
    RESTCatalog catalog = new RESTCatalog(SessionCatalog.SessionContext.createEmpty(), (config) -> adapter);
    catalog.initialize("test", ImmutableMap.of(CatalogProperties.URI, "ignored", CatalogProperties.FILE_IO_IMPL, "org.apache.iceberg.inmemory.InMemoryFileIO", RESTCatalogProperties.SNAPSHOT_LOADING_MODE, SnapshotMode.REFS.name()));
    if (requiresNamespaceCreate()) {
        catalog.createNamespace(TABLE.namespace());
    }
    Table table = catalog.createTable(TABLE, SCHEMA, PartitionSpec.unpartitioned(), ImmutableMap.of("format-version", formatVersion));
    table.newFastAppend().appendFile(DataFiles.builder(PartitionSpec.unpartitioned()).withPath("/path/to/data-a.parquet").withFileSizeInBytes(10).withRecordCount(2).build()).commit();
    String branch = "divergedBranch";
    table.manageSnapshots().createBranch(branch, table.currentSnapshot().snapshotId()).commit();
    table.newFastAppend().appendFile(DataFiles.builder(PartitionSpec.unpartitioned()).withPath("/path/to/data-b.parquet").withFileSizeInBytes(10).withRecordCount(2).build()).toBranch(branch).commit();
    table.newFastAppend().appendFile(DataFiles.builder(PartitionSpec.unpartitioned()).withPath("/path/to/data-c.parquet").withFileSizeInBytes(10).withRecordCount(2).build()).toBranch(branch).commit();
    ResourcePaths paths = ResourcePaths.forCatalogProperties(Maps.newHashMap());
    Table refsTable = catalog.loadTable(TABLE);
    // don't call snapshots() directly as that would cause to load all snapshots. Instead,
    // make sure the snapshots field holds exactly 2 snapshots
    assertThat(((BaseTable) refsTable).operations().current()).extracting("snapshots").asInstanceOf(InstanceOfAssertFactories.list(Snapshot.class)).hasSize(2);
    assertThat(refsTable.currentSnapshot()).isEqualTo(table.currentSnapshot());
    // verify that the table was loaded with the refs argument
    verify(adapter, times(1)).execute(reqMatcher(HTTPMethod.GET, paths.table(TABLE), Map.of(), Map.of("snapshots", "refs")), eq(LoadTableResponse.class), any(), any());
    // verify that all snapshots are loaded when referenced
    assertThat(catalog.loadTable(TABLE).snapshots()).containsExactlyInAnyOrderElementsOf(table.snapshots());
    verify(adapter, times(1)).execute(reqMatcher(HTTPMethod.GET, paths.table(TABLE), Map.of(), Map.of("snapshots", "all")), eq(LoadTableResponse.class), any(), any());
    // verify that committing to branch is possible
    catalog.loadTable(TABLE).newAppend().appendFile(DataFiles.builder(PartitionSpec.unpartitioned()).withPath("/path/to/data-c.parquet").withFileSizeInBytes(10).withRecordCount(2).build()).toBranch(branch).commit();
    assertThat(catalog.loadTable(TABLE).snapshots()).hasSizeGreaterThan(Lists.newArrayList(table.snapshots()).size());
}

@Test
public void lazySnapshotLoadingWithDivergedHistory() {
    RESTCatalogAdapter adapter = Mockito.spy(new RESTCatalogAdapter(backendCatalog));
    RESTCatalog catalog = new RESTCatalog(SessionCatalog.SessionContext.createEmpty(), (config) -> adapter);
    catalog.initialize("test", ImmutableMap.of(CatalogProperties.URI, "ignored", CatalogProperties.FILE_IO_IMPL, "org.apache.iceberg.inmemory.InMemoryFileIO", RESTCatalogProperties.SNAPSHOT_LOADING_MODE, SnapshotMode.REFS.name()));
    if (requiresNamespaceCreate()) {
        catalog.createNamespace(TABLE.namespace());
    }
    Table table = catalog.createTable(TABLE, SCHEMA, PartitionSpec.unpartitioned(), ImmutableMap.of());
    int numSnapshots = 5;
    for (int i = 0; i < numSnapshots; i++) {
        table.newFastAppend().appendFile(DataFiles.builder(PartitionSpec.unpartitioned()).withPath(String.format("/path/to/data-%s.parquet", i)).withFileSizeInBytes(10).withRecordCount(2).build()).commit();
    }
    Table refsTable = catalog.loadTable(TABLE);
    // don't call snapshots() directly as that would cause to load all snapshots. Instead,
    // make sure the snapshots field holds exactly 1 snapshot
    assertThat(((BaseTable) refsTable).operations().current()).extracting("snapshots").asInstanceOf(InstanceOfAssertFactories.list(Snapshot.class)).hasSize(1);
    assertThat(refsTable.currentSnapshot()).isEqualTo(table.currentSnapshot());
    assertThat(refsTable.snapshots()).hasSize(numSnapshots);
    assertThat(refsTable.history()).hasSize(numSnapshots);
}

@ParameterizedTest
@ValueSource(strings = { "v1/oauth/tokens", "https://auth-server.com/token" })
public void testCatalogTokenRefresh(String oauth2ServerUri) {
    Map<String, String> emptyHeaders = ImmutableMap.of();
    Map<String, String> catalogHeaders = ImmutableMap.of("Authorization", "Bearer client-credentials-token:sub=catalog");
    RESTCatalogAdapter adapter = Mockito.spy(new RESTCatalogAdapter(backendCatalog));
    Answer<OAuthTokenResponse> addOneSecondExpiration = invocation -> {
        OAuthTokenResponse response = (OAuthTokenResponse) invocation.callRealMethod();
        return OAuthTokenResponse.builder().withToken(response.token()).withTokenType(response.tokenType()).withIssuedTokenType(response.issuedTokenType()).addScopes(response.scopes()).setExpirationInSeconds(1).build();
    };
    Mockito.doAnswer(addOneSecondExpiration).when(adapter).postForm(eq(oauth2ServerUri), anyMap(), eq(OAuthTokenResponse.class), anyMap(), any());
    Map<String, String> contextCredentials = ImmutableMap.of();
    SessionCatalog.SessionContext context = new SessionCatalog.SessionContext(UUID.randomUUID().toString(), "user", contextCredentials, ImmutableMap.of());
    RESTCatalog catalog = new RESTCatalog(context, (config) -> adapter);
    catalog.initialize("prod", ImmutableMap.of(CatalogProperties.URI, "ignored", "credential", "catalog:secret", OAuth2Properties.OAUTH2_SERVER_URI, oauth2ServerUri));
    Awaitility.await().atMost(5, TimeUnit.SECONDS).untilAsserted(() -> {
        // call client credentials with no initial auth
        Mockito.verify(adapter).execute(reqMatcher(HTTPMethod.POST, oauth2ServerUri, emptyHeaders), eq(OAuthTokenResponse.class), any(), any());
        // use the client credential token for config
        Mockito.verify(adapter).execute(reqMatcher(HTTPMethod.GET, ResourcePaths.config(), catalogHeaders), eq(ConfigResponse.class), any(), any());
        // verify the first token exchange
        Map<String, String> firstRefreshRequest = ImmutableMap.of("grant_type", "urn:ietf:params:oauth:grant-type:token-exchange", "subject_token", "client-credentials-token:sub=catalog", "subject_token_type", "urn:ietf:params:oauth:token-type:access_token", "scope", "catalog");
        Mockito.verify(adapter).execute(reqMatcher(HTTPMethod.POST, oauth2ServerUri, catalogHeaders, Map.of(), firstRefreshRequest), eq(OAuthTokenResponse.class), any(), any());
        // verify that a second exchange occurs
        Map<String, String> secondRefreshRequest = ImmutableMap.of("grant_type", "urn:ietf:params:oauth:grant-type:token-exchange", "subject_token", "token-exchange-token:sub=client-credentials-token:sub=catalog", "subject_token_type", "urn:ietf:params:oauth:token-type:access_token", "scope", "catalog");
        Map<String, String> secondRefreshHeaders = ImmutableMap.of("Authorization", "Bearer token-exchange-token:sub=client-credentials-token:sub=catalog");
        Mockito.verify(adapter).execute(reqMatcher(HTTPMethod.POST, oauth2ServerUri, secondRefreshHeaders, Map.of(), secondRefreshRequest), eq(OAuthTokenResponse.class), any(), any());
    });
}

