@Test
public void namespaceToQueryParam() {
    assertThatThrownBy(() -> RESTUtil.namespaceToQueryParam(null)).isInstanceOf(IllegalArgumentException.class).hasMessage("Invalid namespace: null");
    assertThat(RESTUtil.namespaceToQueryParam(Namespace.empty())).isEqualTo("");
    assertThat(RESTUtil.namespaceToQueryParam(Namespace.of(""))).isEqualTo("");
    assertThat(RESTUtil.namespaceToQueryParam(Namespace.of("ns"))).isEqualTo("ns");
    // verify that the unicode character (\001f) and not its UTF-8 escaped version (%1F) is used
    assertThat(RESTUtil.namespaceToQueryParam(Namespace.of("one", "ns"))).isEqualTo("one\u001fns").isNotEqualTo("one%1Fns");
    assertThat(RESTUtil.namespaceToQueryParam(Namespace.of("one", "two", "ns"))).isEqualTo("one\u001ftwo\u001fns").isNotEqualTo("one%1Ftwo%1Fns");
    assertThat(RESTUtil.namespaceToQueryParam(Namespace.of("one.two", "three.four", "ns"))).isEqualTo("one.two\u001fthree.four\u001fns").isNotEqualTo("one.two%1Fthree.four%1Fns");
}

@Test
public void namespaceFromQueryParam() {
    assertThatThrownBy(() -> RESTUtil.namespaceFromQueryParam(null)).isInstanceOf(IllegalArgumentException.class).hasMessage("Invalid namespace: null");
    assertThat(RESTUtil.namespaceFromQueryParam("")).isEqualTo(Namespace.of(""));
    assertThat(RESTUtil.namespaceFromQueryParam("ns")).isEqualTo(Namespace.of("ns"));
    assertThat(RESTUtil.namespaceFromQueryParam("one\u001fns")).isEqualTo(Namespace.of("one", "ns"));
    assertThat(RESTUtil.namespaceFromQueryParam("one\u001ftwo\u001fns")).isEqualTo(Namespace.of("one", "two", "ns"));
    assertThat(RESTUtil.namespaceFromQueryParam("one.two\u001fthree.four\u001fns")).isEqualTo(Namespace.of("one.two", "three.four", "ns"));
    // using the UTF-8 escaped version will produce a wrong namespace instance
    assertThat(RESTUtil.namespaceFromQueryParam("one%1Fns")).isEqualTo(Namespace.of("one%1Fns"));
    assertThat(RESTUtil.namespaceFromQueryParam("one%1Ftwo%1Fns")).isEqualTo(Namespace.of("one%1Ftwo%1Fns"));
    assertThat(RESTUtil.namespaceFromQueryParam("one%1Ftwo\u001fns")).isEqualTo(Namespace.of("one%1Ftwo", "ns"));
}

@ParameterizedTest
@ValueSource(ints = { 21, 30 })
public void testPaginationForListViews(int numberOfItems) {
    RESTCatalogAdapter adapter = Mockito.spy(new RESTCatalogAdapter(backendCatalog));
    RESTCatalog catalog = new RESTCatalog(SessionCatalog.SessionContext.createEmpty(), (config) -> adapter);
    catalog.initialize("test", ImmutableMap.of(RESTCatalogProperties.PAGE_SIZE, "10"));
    String namespaceName = "newdb";
    String viewName = "newview";
    // create initial namespace
    catalog().createNamespace(Namespace.of(namespaceName));
    // create several views under namespace, based off a table for listing and verify
    for (int i = 0; i < numberOfItems; i++) {
        TableIdentifier viewIndentifier = TableIdentifier.of(namespaceName, viewName + i);
        catalog.buildView(viewIndentifier).withSchema(SCHEMA).withDefaultNamespace(viewIndentifier.namespace()).withQuery("spark", "select * from ns.tbl").create();
    }
    List<TableIdentifier> views = catalog.listViews(Namespace.of(namespaceName));
    assertThat(views).hasSize(numberOfItems);
    Mockito.verify(adapter).execute(reqMatcher(HTTPMethod.GET, "v1/config"), eq(ConfigResponse.class), any(), any());
    Mockito.verify(adapter, times(numberOfItems)).execute(reqMatcher(HTTPMethod.POST, String.format("v1/namespaces/%s/views", namespaceName)), eq(LoadViewResponse.class), any(), any());
    // verify initial request with empty pageToken
    Mockito.verify(adapter).handleRequest(eq(Route.LIST_VIEWS), eq(ImmutableMap.of("pageToken", "", "pageSize", "10", "namespace", namespaceName)), any(), eq(ListTablesResponse.class), any());
    // verify second request with update pageToken
    Mockito.verify(adapter).handleRequest(eq(Route.LIST_VIEWS), eq(ImmutableMap.of("pageToken", "10", "pageSize", "10", "namespace", namespaceName)), any(), eq(ListTablesResponse.class), any());
    // verify third request with update pageToken
    Mockito.verify(adapter).handleRequest(eq(Route.LIST_VIEWS), eq(ImmutableMap.of("pageToken", "20", "pageSize", "10", "namespace", namespaceName)), any(), eq(ListTablesResponse.class), any());
}

