@Test
public void testNestedStruct() {
    Schema schema = new Schema(required(11, "level1_struct_a", Types.StructType.of(required(21, "level2_primitive_i", Types.IntegerType.get()), required(22, "level2_struct_a", Types.StructType.of(optional(31, "level3_primitive_s", Types.StringType.get()))), optional(23, "level2_primitive_b", Types.BooleanType.get()))), required(12, "level1_struct_b", Types.StructType.of(required(24, "level2_primitive_i", Types.IntegerType.get()), required(25, "level2_struct_b", Types.StructType.of(optional(32, "level3_primitive_s", Types.StringType.get()))))), required(13, "level1_primitive_i", Types.IntegerType.get()));
    assertThat(MetricsConfig.limitFieldIds(schema, 1)).as("Should only include top level primitive field").isEqualTo(Set.of(13));
    assertThat(MetricsConfig.limitFieldIds(schema, 2)).as("Should include level 2 primitive field before nested struct").isEqualTo(Set.of(13, 21));
    assertThat(MetricsConfig.limitFieldIds(schema, 3)).as("Should include all of level 2 primitive fields of struct a before nested struct").isEqualTo(Set.of(13, 21, 23));
    assertThat(MetricsConfig.limitFieldIds(schema, 4)).as("Should include all eligible fields in struct a").isEqualTo(Set.of(13, 21, 23, 31));
    assertThat(MetricsConfig.limitFieldIds(schema, 5)).as("Should include first primitive field in struct b").isEqualTo(Set.of(13, 21, 23, 31, 24));
    assertThat(MetricsConfig.limitFieldIds(schema, 6)).as("Should include all primitive fields").isEqualTo(Set.of(13, 21, 23, 31, 24, 32));
    assertThat(MetricsConfig.limitFieldIds(schema, 7)).as("Should return all primitive fields when limit is higher").isEqualTo(Set.of(13, 21, 23, 31, 24, 32));
}

