@Test
public void testSnapshotRowIDValidation() {
    Snapshot snapshot = new BaseSnapshot(0, 1, null, 0, DataOperations.APPEND, null, 1, "ml.avro", null, null, null);
    assertThat(snapshot.firstRowId()).isNull();
    assertThat(snapshot.addedRows()).isNull();
    // added-rows will be set to null if first-row-id is null
    snapshot = new BaseSnapshot(0, 1, null, 0, DataOperations.APPEND, null, 1, "ml.avro", null, 10L, null);
    assertThat(snapshot.firstRowId()).isNull();
    assertThat(snapshot.addedRows()).isNull();
    // added-rows and first-row-id can be 0
    snapshot = new BaseSnapshot(0, 1, null, 0, DataOperations.APPEND, null, 1, "ml.avro", 0L, 0L, null);
    assertThat(snapshot.firstRowId()).isEqualTo(0);
    assertThat(snapshot.addedRows()).isEqualTo(0);
    assertThatThrownBy(() -> new BaseSnapshot(0, 1, null, 0, DataOperations.APPEND, null, 1, "ml.avro", 10L, null, null)).isInstanceOf(IllegalArgumentException.class).hasMessage("Invalid added-rows (required when first-row-id is set): null");
    assertThatThrownBy(() -> new BaseSnapshot(0, 1, null, 0, DataOperations.APPEND, null, 1, "ml.avro", 0L, -1L, null)).isInstanceOf(IllegalArgumentException.class).hasMessage("Invalid added-rows (cannot be negative): -1");
    assertThatThrownBy(() -> new BaseSnapshot(0, 1, null, 0, DataOperations.APPEND, null, 1, "ml.avro", -1L, 1L, null)).isInstanceOf(IllegalArgumentException.class).hasMessage("Invalid first-row-id (cannot be negative): -1");
}

