@Test
public void testUpdateFailure() {
    Set<Pair<Type.PrimitiveType, Type.PrimitiveType>> allowedUpdates = Sets.newHashSet(Pair.of(Types.IntegerType.get(), Types.LongType.get()), Pair.of(Types.FloatType.get(), Types.DoubleType.get()), Pair.of(Types.DecimalType.of(9, 2), Types.DecimalType.of(18, 2)));
    List<Type.PrimitiveType> primitives = Lists.newArrayList(Types.BooleanType.get(), Types.IntegerType.get(), Types.LongType.get(), Types.FloatType.get(), Types.DoubleType.get(), Types.DateType.get(), Types.TimeType.get(), Types.TimestampType.withZone(), Types.TimestampType.withoutZone(), Types.StringType.get(), Types.UUIDType.get(), Types.BinaryType.get(), Types.FixedType.ofLength(3), Types.FixedType.ofLength(4), Types.DecimalType.of(9, 2), Types.DecimalType.of(9, 3), Types.DecimalType.of(18, 2), Types.GeometryType.crs84(), Types.GeometryType.of("srid:3857"), Types.GeographyType.crs84(), Types.GeographyType.of("srid:4269", EdgeAlgorithm.KARNEY));
    for (Type.PrimitiveType fromType : primitives) {
        for (Type.PrimitiveType toType : primitives) {
            Schema fromSchema = new Schema(required(1, "col", fromType));
            if (fromType.equals(toType) || allowedUpdates.contains(Pair.of(fromType, toType))) {
                Schema expected = new Schema(required(1, "col", toType));
                Schema result = new SchemaUpdate(fromSchema, 1).updateColumn("col", toType).apply();
                assertThat(result.asStruct()).isEqualTo(expected.asStruct());
                continue;
            }
            String typeChange = fromType + " -> " + toType.toString();
            assertThatThrownBy(() -> new SchemaUpdate(fromSchema, 1).updateColumn("col", toType)).isInstanceOf(IllegalArgumentException.class).hasMessage("Cannot change column type: col: " + typeChange);
        }
    }
}

