    Schema schema = new Schema(required(1, "id", Types.LongType.get()), required(2, "struct", Types.StructType.of(required(3, "count", Types.LongType.get()), required(4, "data", Types.StringType.get()), required(5, "data_1", Types.StringType.get()))));
    Schema expected = new Schema(required(1, "id", Types.LongType.get()), required(2, "struct", Types.StructType.of(required(6, "data", Types.IntegerType.get()), required(3, "count", Types.LongType.get()), required(5, "data_1", Types.StringType.get()))));
    Schema actual = new SchemaUpdate(schema, 5).allowIncompatibleChanges().deleteColumn("struct.data").addRequiredColumn("struct", "data", Types.IntegerType.get()).moveFirst("struct.data").apply();
    assertThat(actual.asStruct()).isEqualTo(expected.asStruct());
}

