    Schema schema = new Schema(Types.NestedField.required(1, "x", Types.LongType.get()), Types.NestedField.required(2, "y", Types.LongType.get()));
    PartitionSpec spec = PartitionSpec.builderFor(schema).withSpecId(0).identity("x").identity("y").build();
    String location = "file://tmp/db/table";
    TableMetadata metadata = TableMetadata.newTableMetadata(schema, spec, SortOrder.unsorted(), location, ImmutableMap.of(), 2);
    assertThat(metadata.spec()).isEqualTo(spec);
    Schema updatedSchema = new Schema(Types.NestedField.required(1, "x", Types.LongType.get()), Types.NestedField.required(2, "z", Types.StringType.get()));
    PartitionSpec updatedSpec = PartitionSpec.builderFor(updatedSchema).withSpecId(0).bucket("z", 8).identity("x").build();
    TableMetadata updated = metadata.buildReplacement(updatedSchema, updatedSpec, SortOrder.unsorted(), location, ImmutableMap.of());
    PartitionSpec expected = PartitionSpec.builderFor(updated.schema()).withSpecId(1).add(3, 1002, "z_bucket", Transforms.bucket(8)).add(1, 1000, "x", Transforms.identity()).build();
    assertThat(updated.spec()).as("Should reassign the partition field IDs and reuse any existing IDs for equivalent fields").isEqualTo(expected);
}

