@Test
public void testManifestListIndexProjection() throws IOException {
    long previousSnapshotId = System.currentTimeMillis() - new Random(1234).nextInt(3600);
    String manifestListLocation = createManifestListWithManifestFile(previousSnapshotId, null, "file:/tmp/manifest1.avro");
    Schema manifestProjection = ManifestFile.schema().select(ManifestFile.PATH.name(), ManifestFile.LENGTH.name(), ManifestFile.SPEC_ID.name(), ManifestFile.SNAPSHOT_ID.name());
    try (CloseableIterable<ManifestFile> manifestIterable = InternalData.read(FileFormat.AVRO, localInput(manifestListLocation)).setRootType(GenericManifestFile.class).project(manifestProjection).reuseContainers().build()) {
        List<ManifestFile> manifests = Lists.newArrayList(manifestIterable);
        assertThat(manifests).hasSize(1);
        manifests.forEach(manifest -> {
            // projected fields
            assertThat(manifest).extracting(ManifestFile::path, ManifestFile::length, ManifestFile::partitionSpecId, ManifestFile::snapshotId).doesNotContainNull();
            // not projected with defaults
            assertThat(manifest.sequenceNumber()).isEqualTo(0);
            assertThat(manifest.minSequenceNumber()).isEqualTo(0);
            assertThat(manifest.content()).isEqualTo(ManifestContent.DATA);
            // not projected
            assertThat(manifest).extracting(ManifestFile::addedFilesCount, ManifestFile::existingFilesCount, ManifestFile::deletedFilesCount, ManifestFile::addedRowsCount, ManifestFile::existingRowsCount, ManifestFile::deletedRowsCount, ManifestFile::partitions, ManifestFile::keyMetadata).containsOnlyNulls();
        });
    }
}

