@Test
public void testReverseBinPackingUnlimitedLookback() {
    assertThat(packEnd(list(1, 2, 3, 4, 5), 3)).as("Should pack the first 2 values").isEqualTo(list(list(1, 2), list(3), list(4), list(5)));
