public void testAcquireOnceSingleProcess() {
    lockManager.acquireOnce(lockEntityId, ownerId);
    assertThatThrownBy(() -> lockManager.acquireOnce(lockEntityId, ownerId)).isInstanceOf(IllegalStateException.class).hasMessageStartingWith("Lock for").hasMessageContaining("currently held by").hasMessageContaining("expiration");
}

@Test
public void testAcquireOnceMultiProcesses() {
    List<Boolean> results = IntStream.range(0, 10).parallel().mapToObj(i -> {
        try {
            lockManager.acquireOnce(lockEntityId, ownerId);
            return true;
        } catch (IllegalStateException e) {
            return false;
        }
    }).collect(Collectors.toList());
    assertThat(results.stream().filter(s -> s).count()).as("only 1 thread should have acquired the lock").isOne();
}

