    assertThat(lockManager.release(lockEntityId, UUID.randomUUID().toString())).as("should return false if ownerId is wrong").isFalse();
}

@Test
public void testAcquireSingleProcess() throws Exception {
    lockManager.initialize(ImmutableMap.of(CatalogProperties.LOCK_ACQUIRE_INTERVAL_MS, "500", CatalogProperties.LOCK_ACQUIRE_TIMEOUT_MS, "2000"));
    assertThat(lockManager.acquire(lockEntityId, ownerId)).isTrue();
    String oldOwner = ownerId;
    CompletableFuture.supplyAsync(() -> {
        try {
            Thread.sleep(200);
        } catch (InterruptedException e) {
            throw new RuntimeException(e);
        }
        assertThat(lockManager.release(lockEntityId, oldOwner)).isTrue();
        return null;
    });
    ownerId = UUID.randomUUID().toString();
    long start = System.currentTimeMillis();
    assertThat(lockManager.acquire(lockEntityId, ownerId)).isTrue();
    assertThat(System.currentTimeMillis() - start).as("should succeed after 200ms").isGreaterThanOrEqualTo(200);
}

@Test
public void testAcquireMultiProcessAllSucceed() {
    lockManager.initialize(ImmutableMap.of(CatalogProperties.LOCK_ACQUIRE_INTERVAL_MS, "500"));
    long start = System.currentTimeMillis();
    List<Boolean> results = IntStream.range(0, 3).parallel().mapToObj(i -> {
        String owner = UUID.randomUUID().toString();
        boolean succeeded = lockManager.acquire(lockEntityId, owner);
        if (succeeded) {
            try {
                Thread.sleep(1000);
            } catch (InterruptedException e) {
                throw new RuntimeException(e);
            }
            assertThat(lockManager.release(lockEntityId, owner)).isTrue();
        }
        return succeeded;
    }).collect(Collectors.toList());
    assertThat(results.stream().filter(s -> s).count()).as("all lock acquire should succeed sequentially").isEqualTo(3);
    assertThat(System.currentTimeMillis() - start).as("must take more than 3 seconds").isGreaterThanOrEqualTo(3000);
}

@Test
public void testAcquireMultiProcessOnlyOneSucceed() {
    lockManager.initialize(ImmutableMap.of(CatalogProperties.LOCK_HEARTBEAT_INTERVAL_MS, "100", CatalogProperties.LOCK_ACQUIRE_INTERVAL_MS, "500", CatalogProperties.LOCK_ACQUIRE_TIMEOUT_MS, "2000"));
    List<Boolean> results = IntStream.range(0, 3).parallel().mapToObj(i -> lockManager.acquire(lockEntityId, ownerId)).collect(Collectors.toList());
    assertThat(results.stream().filter(s -> s).count()).as("only 1 thread should have acquired the lock").isOne();
}

