@Test
public void closeParallelIteratorWithoutCompleteIteration() {
    ExecutorService executor = Executors.newFixedThreadPool(1);
    try {
        Iterable<CloseableIterable<Integer>> transform = Iterables.transform(Lists.newArrayList(1, 2, 3, 4, 5), item -> new CloseableIterable<Integer>() {

            @Override
            public void close() {
            }

            @Override
            public CloseableIterator<Integer> iterator() {
                return CloseableIterator.withClose(Collections.singletonList(item).iterator());
            }
        });
        ParallelIterable<Integer> parallelIterable = new ParallelIterable<>(transform, executor);
        ParallelIterator<Integer> iterator = (ParallelIterator<Integer>) parallelIterable.iterator();
        assertThat(iterator.hasNext()).isTrue();
        assertThat(iterator.next()).isNotNull();
        Awaitility.await("Queue is populated").atMost(5, TimeUnit.SECONDS).untilAsserted(() -> queueHasElements(iterator));
        iterator.close();
        Awaitility.await("Queue is cleared").atMost(5, TimeUnit.SECONDS).untilAsserted(() -> assertThat(iterator.queueSize()).isEqualTo(0));
    } finally {
        executor.shutdown();
    }
}

@Test
public void closeMoreDataParallelIteratorWithoutCompleteIteration() {
    ExecutorService executor = Executors.newFixedThreadPool(1);
    try {
        Iterator<Integer> integerIterator = new Iterator<Integer>() {

            private int number = 1;

            @Override
            public boolean hasNext() {
                if (number > 1000) {
                    return false;
                }
                number++;
                return true;
            }

            @Override
            public Integer next() {
                try {
                    // sleep to control number generate rate
                    Thread.sleep(10);
                } catch (InterruptedException e) {
                    // Sleep interrupted, we ignore it!
                }
                return number;
            }
        };
        Iterable<CloseableIterable<Integer>> transform = Iterables.transform(Lists.newArrayList(1), item -> new CloseableIterable<Integer>() {

            @Override
            public void close() {
            }

            @Override
            public CloseableIterator<Integer> iterator() {
                return CloseableIterator.withClose(integerIterator);
            }
        });
        ParallelIterable<Integer> parallelIterable = new ParallelIterable<>(transform, executor);
        ParallelIterator<Integer> iterator = (ParallelIterator<Integer>) parallelIterable.iterator();
        assertThat(iterator.hasNext()).isTrue();
        assertThat(iterator.next()).isNotNull();
        Awaitility.await("Queue is populated").atMost(5, TimeUnit.SECONDS).untilAsserted(() -> queueHasElements(iterator));
        iterator.close();
        Awaitility.await("Queue is cleared").atMost(5, TimeUnit.SECONDS).untilAsserted(() -> assertThat(iterator.queueSize()).as("Queue is not empty after cleaning").isEqualTo(0));
    } finally {
        executor.shutdown();
    }
}

@Test
public void limitQueueSize() {
    ExecutorService executor = Executors.newSingleThreadExecutor();
    try {
        List<Iterable<Integer>> iterables = ImmutableList.of(() -> IntStream.range(0, 100).iterator(), () -> IntStream.range(0, 100).iterator(), () -> IntStream.range(0, 100).iterator());
        Multiset<Integer> expectedValues = IntStream.range(0, 100).boxed().flatMap(i -> Stream.of(i, i, i)).collect(ImmutableMultiset.toImmutableMultiset());
        int maxQueueSize = 20;
        ParallelIterable<Integer> parallelIterable = new ParallelIterable<>(iterables, executor, maxQueueSize);
        ParallelIterator<Integer> iterator = (ParallelIterator<Integer>) parallelIterable.iterator();
        Multiset<Integer> actualValues = HashMultiset.create();
        while (iterator.hasNext()) {
            assertThat(iterator.queueSize()).as("iterator internal queue size").isLessThanOrEqualTo(100);
            actualValues.add(iterator.next());
        }
        assertThat(actualValues).as("multiset of values returned by the iterator").isEqualTo(expectedValues);
        iterator.close();
    } finally {
        executor.shutdown();
    }
}

@Test
@Timeout(10)
public void noDeadlock() {
    // This test simulates a scenario where iterators use a constrained resource
    // (e.g. an S3 connection pool that has a limit on the number of connections).
    // In this case, the constrained resource shouldn't cause a deadlock when queue
    // is full and the iterator is waiting for the queue to be drained.
    ExecutorService executor = Executors.newFixedThreadPool(1);
    try {
        Semaphore semaphore = new Semaphore(1);
        List<Iterable<Integer>> iterablesA = ImmutableList.of(testIterable(semaphore::acquire, semaphore::release, IntStream.range(0, 100).iterator()));
        List<Iterable<Integer>> iterablesB = ImmutableList.of(testIterable(semaphore::acquire, semaphore::release, IntStream.range(200, 300).iterator()));
        ParallelIterable<Integer> parallelIterableA = new ParallelIterable<>(iterablesA, executor, 1);
        ParallelIterable<Integer> parallelIterableB = new ParallelIterable<>(iterablesB, executor, 1);
        parallelIterableA.iterator().next();
        parallelIterableB.iterator().next();
    } finally {
        executor.shutdownNow();
    }
}

