@Test
public void testExpiration() {
    // purposely use versions and timestamps that do not match to check that version ID is used
    ViewVersion v1 = newViewVersion(1, "select 1 as count");
    ViewVersion v3 = newViewVersion(3, "select count from t1");
    ViewVersion v2 = newViewVersion(2, "select count(1) as count from t2");
    Map<Integer, ViewVersion> versionsById = ImmutableMap.of(1, v1, 2, v2, 3, v3);
    assertThat(ViewMetadata.Builder.expireVersions(versionsById, 3, v1)).containsExactlyInAnyOrder(v1, v2, v3);
    assertThat(ViewMetadata.Builder.expireVersions(versionsById, 2, v1)).containsExactlyInAnyOrder(v1, v3);
    assertThat(ViewMetadata.Builder.expireVersions(versionsById, 1, v1)).containsExactly(v1);
}

@Test
public void testUpdateHistory() {
    ViewVersion v1 = newViewVersion(1, "select 1 as count");
    ViewVersion v2 = newViewVersion(2, "select count(1) as count from t2");
    ViewVersion v3 = newViewVersion(3, "select count from t1");
    ViewHistoryEntry one = ImmutableViewHistoryEntry.builder().versionId(v1.versionId()).timestampMillis(v1.timestampMillis()).build();
    ViewHistoryEntry two = ImmutableViewHistoryEntry.builder().versionId(v2.versionId()).timestampMillis(v2.timestampMillis()).build();
    ViewHistoryEntry three = ImmutableViewHistoryEntry.builder().versionId(v3.versionId()).timestampMillis(v3.timestampMillis()).build();
    assertThat(ViewMetadata.Builder.updateHistory(ImmutableList.of(one, two, three), ImmutableSet.of(1, 2, 3))).containsExactly(one, two, three);
    // one was an invalid entry in the history, so all previous elements are removed
    assertThat(ViewMetadata.Builder.updateHistory(ImmutableList.of(three, two, one, two, three), ImmutableSet.of(2, 3))).containsExactly(two, three);
    // two was an invalid entry in the history, so all previous elements are removed
    assertThat(ViewMetadata.Builder.updateHistory(ImmutableList.of(one, two, three, one, three), ImmutableSet.of(1, 3))).containsExactly(three, one, three);
}

