@Test
public void viewVersionHistoryNormalization() {
    Map<String, String> properties = ImmutableMap.of(ViewProperties.VERSION_HISTORY_SIZE, "2");
    ViewVersion viewVersionOne = newViewVersion(1, "select * from ns.tbl");
    ViewVersion viewVersionTwo = newViewVersion(2, "select count(*) from ns.tbl");
    ViewVersion viewVersionThree = newViewVersion(3, "select count(*) as count from ns.tbl");
    ViewMetadata originalViewMetadata = ViewMetadata.builder().setProperties(properties).setLocation("location").addSchema(new Schema(Types.NestedField.required(1, "x", Types.LongType.get()))).addVersion(viewVersionOne).addVersion(viewVersionTwo).addVersion(viewVersionThree).setCurrentVersionId(3).build();
    // the first build will not expire versions that were added in the builder
    assertThat(originalViewMetadata.versions()).hasSize(3);
    assertThat(originalViewMetadata.history()).hasSize(1);
    // rebuild the metadata to expire older versions
    ViewMetadata viewMetadata = ViewMetadata.buildFrom(originalViewMetadata).build();
    assertThat(viewMetadata.versions()).hasSize(2);
    assertThat(viewMetadata.history()).hasSize(1);
    // make sure that metadata changes reflect the current state after the history was adjusted,
    // meaning that the first view version shouldn't be included
    List<MetadataUpdate> changes = originalViewMetadata.changes();
    assertThat(changes).hasSize(7);
    assertThat(changes).element(0).isInstanceOf(MetadataUpdate.SetProperties.class).asInstanceOf(InstanceOfAssertFactories.type(MetadataUpdate.SetProperties.class)).extracting(MetadataUpdate.SetProperties::updated).isEqualTo(properties);
    assertThat(changes).element(1).isInstanceOf(MetadataUpdate.SetLocation.class).asInstanceOf(InstanceOfAssertFactories.type(MetadataUpdate.SetLocation.class)).extracting(MetadataUpdate.SetLocation::location).isEqualTo("location");
    assertThat(changes).element(2).isInstanceOf(MetadataUpdate.AddSchema.class).asInstanceOf(InstanceOfAssertFactories.type(MetadataUpdate.AddSchema.class)).extracting(MetadataUpdate.AddSchema::schema).extracting(Schema::schemaId).isEqualTo(0);
    assertThat(changes).element(3).isInstanceOf(MetadataUpdate.AddViewVersion.class).asInstanceOf(InstanceOfAssertFactories.type(MetadataUpdate.AddViewVersion.class)).extracting(MetadataUpdate.AddViewVersion::viewVersion).isEqualTo(ImmutableViewVersion.builder().from(viewVersionOne).schemaId(-1).build());
    assertThat(changes).element(4).isInstanceOf(MetadataUpdate.AddViewVersion.class).asInstanceOf(InstanceOfAssertFactories.type(MetadataUpdate.AddViewVersion.class)).extracting(MetadataUpdate.AddViewVersion::viewVersion).isEqualTo(ImmutableViewVersion.builder().from(viewVersionTwo).schemaId(-1).build());
    assertThat(changes).element(5).isInstanceOf(MetadataUpdate.AddViewVersion.class).asInstanceOf(InstanceOfAssertFactories.type(MetadataUpdate.AddViewVersion.class)).extracting(MetadataUpdate.AddViewVersion::viewVersion).isEqualTo(ImmutableViewVersion.builder().from(viewVersionThree).schemaId(-1).build());
    assertThat(changes).element(6).isInstanceOf(MetadataUpdate.SetCurrentViewVersion.class).asInstanceOf(InstanceOfAssertFactories.type(MetadataUpdate.SetCurrentViewVersion.class)).extracting(MetadataUpdate.SetCurrentViewVersion::versionId).isEqualTo(-1);
}

@Test
public void viewVersionHistoryIsCorrectlyRetained() {
    Map<String, String> properties = ImmutableMap.of(ViewProperties.VERSION_HISTORY_SIZE, "2");
    ViewVersion viewVersionOne = newViewVersion(1, "select * from ns.tbl");
    ViewVersion viewVersionTwo = newViewVersion(2, "select count(*) from ns.tbl");
    ViewVersion viewVersionThree = newViewVersion(3, "select count(*) as count from ns.tbl");
    ViewMetadata originalViewMetadata = ViewMetadata.builder().setProperties(properties).setLocation("location").addSchema(new Schema(Types.NestedField.required(1, "x", Types.LongType.get()))).addVersion(viewVersionOne).addVersion(viewVersionTwo).addVersion(viewVersionThree).setCurrentVersionId(3).build();
    assertThat(originalViewMetadata.versions()).hasSize(3).containsExactlyInAnyOrder(viewVersionOne, viewVersionTwo, viewVersionThree);
    assertThat(originalViewMetadata.history()).hasSize(1).first().extracting(ViewHistoryEntry::versionId).isEqualTo(3);
    // rebuild the metadata to expire older versions
    ViewMetadata viewMetadata = ViewMetadata.buildFrom(originalViewMetadata).build();
    assertThat(viewMetadata.versions()).hasSize(2).// there is no requirement about the order of versions
    containsExactlyInAnyOrder(viewVersionThree, viewVersionTwo);
    assertThat(viewMetadata.history()).hasSize(1).first().extracting(ViewHistoryEntry::versionId).isEqualTo(3);
    ViewMetadata updated = ViewMetadata.buildFrom(viewMetadata).setCurrentVersionId(2).build();
    assertThat(updated.versions()).hasSize(2).containsExactlyInAnyOrder(viewVersionTwo, viewVersionThree);
    assertThat(updated.history()).hasSize(2).element(0).extracting(ViewHistoryEntry::versionId).isEqualTo(3);
    assertThat(updated.history()).element(1).extracting(ViewHistoryEntry::versionId).isEqualTo(2);
    ViewMetadata view = ViewMetadata.buildFrom(updated).setCurrentVersionId(3).build();
    assertThat(view.versions()).hasSize(2).containsExactlyInAnyOrder(viewVersionTwo, viewVersionThree);
    assertThat(view.history()).hasSize(3).element(0).extracting(ViewHistoryEntry::versionId).isEqualTo(3);
    assertThat(view.history()).element(1).extracting(ViewHistoryEntry::versionId).isEqualTo(2);
    assertThat(view.history()).element(2).extracting(ViewHistoryEntry::versionId).isEqualTo(3);
    // viewVersionId 1 has been removed from versions, so this should fail
    assertThatThrownBy(() -> ViewMetadata.buildFrom(view).setCurrentVersionId(1).build()).isInstanceOf(IllegalArgumentException.class).hasMessage("Cannot set current version to unknown version: 1");
}

@Test
public void versionHistoryEntryMaintainCorrectTimeline() {
    ViewVersion viewVersionOne = newViewVersion(1, 0, 1000, "select * from ns.tbl");
    ViewVersion viewVersionTwo = newViewVersion(2, 0, 2000, "select count(*) from ns.tbl");
    ViewVersion viewVersionThree = newViewVersion(3, 0, 3000, "select count(*) as count from ns.tbl");
    ViewMetadata viewMetadata = ViewMetadata.builder().setLocation("location").addSchema(new Schema(Types.NestedField.required(1, "x", Types.LongType.get()))).addVersion(viewVersionOne).addVersion(viewVersionTwo).setCurrentVersionId(1).build();
    // setting an existing view version as the new current should update the timestamp in the
    // history
    ViewMetadata updated = ViewMetadata.buildFrom(viewMetadata).setCurrentVersionId(2).build();
    List<ViewHistoryEntry> history = updated.history();
    assertThat(history).hasSize(2).element(0).isEqualTo(ImmutableViewHistoryEntry.builder().versionId(1).timestampMillis(1000).build());
    assertThat(history).element(1).satisfies(v -> {
        assertThat(v.versionId()).isEqualTo(2);
        assertThat(v.timestampMillis()).isGreaterThan(3000).isLessThanOrEqualTo(System.currentTimeMillis());
    });
    // adding a new view version and setting it as current should use the view version's timestamp
    // in the history (which has been set to a fixed value for testing)
    updated = ViewMetadata.buildFrom(updated).addVersion(viewVersionThree).setCurrentVersionId(3).build();
    List<ViewHistoryEntry> historyTwo = updated.history();
    assertThat(historyTwo).hasSize(3).containsAll(history).element(2).isEqualTo(ImmutableViewHistoryEntry.builder().versionId(3).timestampMillis(3000).build());
    // setting an older view version as the new current (aka doing a rollback) should update the
    // timestamp in the history
    ViewMetadata reactiveOldViewVersion = ViewMetadata.buildFrom(updated).setCurrentVersionId(1).build();
    List<ViewHistoryEntry> historyThree = reactiveOldViewVersion.history();
    assertThat(historyThree).hasSize(4).containsAll(historyTwo).element(3).satisfies(v -> {
        assertThat(v.versionId()).isEqualTo(1);
        assertThat(v.timestampMillis()).isGreaterThan(3000).isLessThanOrEqualTo(System.currentTimeMillis());
    });
}

@Test
public void versionsAddedInCurrentBuildAreRetained() {
    ViewVersion v1 = newViewVersion(1, "select 1 as count");
    ViewVersion v2 = newViewVersion(2, "select count from t1");
    ViewVersion v3 = newViewVersion(3, "select count(1) as count from t2");
    ViewMetadata metadata = ViewMetadata.builder().setLocation("location").addSchema(new Schema(Types.NestedField.required(1, "x", Types.LongType.get()))).addVersion(v1).setCurrentVersionId(v1.versionId()).setProperties(ImmutableMap.of(ViewProperties.VERSION_HISTORY_SIZE, "2")).build();
    assertThat(metadata.versions()).containsOnly(v1);
    // make sure all currently added versions are retained
    ViewMetadata updated = ViewMetadata.buildFrom(metadata).addVersion(v2).addVersion(v3).build();
    assertThat(updated.versions()).containsExactlyInAnyOrder(v1, v2, v3);
    // rebuild the metadata to expire older versions
    updated = ViewMetadata.buildFrom(updated).build();
    assertThat(updated.versions()).containsExactlyInAnyOrder(v1, v3);
}

@Test
public void viewMetadataAndMetadataChanges() {
    Map<String, String> properties = ImmutableMap.of("key1", "prop1", "key2", "prop2");
    Schema schemaOne = new Schema(0, Types.NestedField.required(1, "x", Types.LongType.get()));
    Schema schemaTwo = new Schema(1, Types.NestedField.required(1, "y", Types.LongType.get()));
    ViewVersion viewVersionOne = newViewVersion(1, 0, "select * from ns.tbl");
    ViewVersion viewVersionTwo = newViewVersion(2, 0, "select count(*) from ns.tbl");
    ViewVersion viewVersionThree = newViewVersion(3, 1, "select count(*) as count from ns.tbl");
    String uuid = "fa6506c3-7681-40c8-86dc-e36561f83385";
    ViewMetadata viewMetadata = ViewMetadata.builder().assignUUID(uuid).setLocation("custom-location").setProperties(properties).addSchema(schemaOne).addSchema(schemaTwo).addVersion(viewVersionOne).addVersion(viewVersionTwo).addVersion(viewVersionThree).setCurrentVersionId(3).build();
    assertThat(viewMetadata.versions()).hasSize(3).containsExactly(viewVersionOne, viewVersionTwo, viewVersionThree);
    assertThat(viewMetadata.history()).hasSize(1);
    assertThat(viewMetadata.currentVersionId()).isEqualTo(3);
    assertThat(viewMetadata.currentVersion()).isEqualTo(viewVersionThree);
    assertThat(viewMetadata.formatVersion()).isEqualTo(ViewMetadata.DEFAULT_VIEW_FORMAT_VERSION);
    assertThat(viewMetadata.schemas().stream().map(Schema::asStruct)).hasSize(2).containsExactly(schemaOne.asStruct(), schemaTwo.asStruct());
    assertThat(viewMetadata.schema().asStruct()).isEqualTo(schemaTwo.asStruct());
    assertThat(viewMetadata.currentSchemaId()).isEqualTo(schemaTwo.schemaId());
    assertThat(viewMetadata.location()).isEqualTo("custom-location");
    assertThat(viewMetadata.properties()).isEqualTo(properties);
    List<MetadataUpdate> changes = viewMetadata.changes();
    assertThat(changes).hasSize(9);
    assertThat(changes).element(0).isInstanceOf(MetadataUpdate.AssignUUID.class).asInstanceOf(InstanceOfAssertFactories.type(MetadataUpdate.AssignUUID.class)).extracting(MetadataUpdate.AssignUUID::uuid).isEqualTo(uuid);
    assertThat(changes).element(1).isInstanceOf(MetadataUpdate.SetLocation.class).asInstanceOf(InstanceOfAssertFactories.type(MetadataUpdate.SetLocation.class)).extracting(MetadataUpdate.SetLocation::location).isEqualTo("custom-location");
    assertThat(changes).element(2).isInstanceOf(MetadataUpdate.SetProperties.class).asInstanceOf(InstanceOfAssertFactories.type(MetadataUpdate.SetProperties.class)).extracting(MetadataUpdate.SetProperties::updated).isEqualTo(properties);
    assertThat(changes).element(3).isInstanceOf(MetadataUpdate.AddSchema.class).asInstanceOf(InstanceOfAssertFactories.type(MetadataUpdate.AddSchema.class)).extracting(MetadataUpdate.AddSchema::schema).extracting(Schema::schemaId).isEqualTo(0);
    assertThat(changes).element(4).isInstanceOf(MetadataUpdate.AddSchema.class).asInstanceOf(InstanceOfAssertFactories.type(MetadataUpdate.AddSchema.class)).extracting(MetadataUpdate.AddSchema::schema).extracting(Schema::schemaId).isEqualTo(1);
    assertThat(changes).element(5).isInstanceOf(MetadataUpdate.AddViewVersion.class).asInstanceOf(InstanceOfAssertFactories.type(MetadataUpdate.AddViewVersion.class)).extracting(MetadataUpdate.AddViewVersion::viewVersion).isEqualTo(viewVersionOne);
    assertThat(changes).element(6).isInstanceOf(MetadataUpdate.AddViewVersion.class).asInstanceOf(InstanceOfAssertFactories.type(MetadataUpdate.AddViewVersion.class)).extracting(MetadataUpdate.AddViewVersion::viewVersion).isEqualTo(viewVersionTwo);
    assertThat(changes).element(7).isInstanceOf(MetadataUpdate.AddViewVersion.class).asInstanceOf(InstanceOfAssertFactories.type(MetadataUpdate.AddViewVersion.class)).extracting(MetadataUpdate.AddViewVersion::viewVersion).isEqualTo(ImmutableViewVersion.builder().from(viewVersionThree).schemaId(-1).build());
    assertThat(changes).element(8).isInstanceOf(MetadataUpdate.SetCurrentViewVersion.class).asInstanceOf(InstanceOfAssertFactories.type(MetadataUpdate.SetCurrentViewVersion.class)).extracting(MetadataUpdate.SetCurrentViewVersion::versionId).isEqualTo(-1);
}

@Test
public void uuidAssignment() {
    String uuid = "fa6506c3-7681-40c8-86dc-e36561f83385";
    ViewMetadata viewMetadata = ViewMetadata.builder().assignUUID(uuid).setLocation("custom-location").addSchema(new Schema(Types.NestedField.required(1, "x", Types.LongType.get()))).addVersion(ImmutableViewVersion.builder().schemaId(0).versionId(1).timestampMillis(23L).defaultNamespace(Namespace.of("ns")).build()).setCurrentVersionId(1).build();
    assertThat(viewMetadata.uuid()).isEqualTo(uuid);
    // uuid should be carried over
    ViewMetadata updated = ViewMetadata.buildFrom(viewMetadata).build();
    assertThat(updated.uuid()).isEqualTo(uuid);
    assertThat(updated.changes()).isEmpty();
    // assigning the same uuid shouldn't fail and shouldn't cause any changes
    updated = ViewMetadata.buildFrom(viewMetadata).assignUUID(uuid).build();
    assertThat(updated.uuid()).isEqualTo(uuid);
    assertThat(updated.changes()).isEmpty();
    // can't reassign view uuid
    assertThatThrownBy(() -> ViewMetadata.buildFrom(viewMetadata).assignUUID(UUID.randomUUID().toString()).build()).isInstanceOf(IllegalArgumentException.class).hasMessage("Cannot reassign uuid");
}

