@Test
public void viewVersionDeduplication() {
    // all view versions have the same ID
    // additionally, there are duplicate view versions that only differ in their creation timestamp
    ViewVersion viewVersionOne = newViewVersion(1, "select * from ns.tbl");
    ViewVersion viewVersionTwo = newViewVersion(1, "select count(*) from ns.tbl");
    ViewVersion viewVersionThree = newViewVersion(1, "select count(*) as count from ns.tbl");
    ViewVersion viewVersionOneUpdated = ImmutableViewVersion.builder().from(viewVersionOne).timestampMillis(1000).build();
    ViewVersion viewVersionTwoUpdated = ImmutableViewVersion.builder().from(viewVersionTwo).timestampMillis(100).build();
    ViewVersion viewVersionThreeUpdated = ImmutableViewVersion.builder().from(viewVersionThree).timestampMillis(10).build();
    ViewMetadata viewMetadata = ViewMetadata.builder().setLocation("custom-location").addSchema(new Schema(Types.NestedField.required(1, "x", Types.LongType.get()))).addVersion(viewVersionOne).addVersion(viewVersionTwo).addVersion(viewVersionThree).addVersion(viewVersionOneUpdated).addVersion(viewVersionTwoUpdated).addVersion(viewVersionThreeUpdated).setCurrentVersionId(3).build();
    assertThat(viewMetadata.currentVersion()).isEqualTo(ImmutableViewVersion.builder().from(viewVersionThree).versionId(3).build());
    // IDs of the view versions should be re-assigned and view versions should be de-duplicated
    assertThat(viewMetadata.versions()).hasSize(3).containsExactly(viewVersionOne, ImmutableViewVersion.builder().from(viewVersionTwo).versionId(2).build(), ImmutableViewVersion.builder().from(viewVersionThree).versionId(3).build());
}

