@Test
public void droppingDialectFailsWhenSwitchingViewVersionId() {
    Schema schema = new Schema(Types.NestedField.required(1, "x", Types.LongType.get()));
    ViewRepresentation spark = ImmutableSQLViewRepresentation.builder().dialect("spark").sql("select * from tbl").build();
    ViewRepresentation trino = ImmutableSQLViewRepresentation.builder().dialect("trino").sql("select * from tbl").build();
    ViewVersion sparkOnly = ImmutableViewVersion.builder().versionId(1).schemaId(0).timestampMillis(System.currentTimeMillis()).defaultNamespace(Namespace.empty()).addRepresentations(spark).build();
    ViewVersion trinoOnly = ImmutableViewVersion.builder().versionId(2).schemaId(0).timestampMillis(System.currentTimeMillis()).defaultNamespace(Namespace.empty()).addRepresentations(trino).build();
    ViewVersion trinoAndSpark = ImmutableViewVersion.builder().versionId(3).schemaId(0).timestampMillis(System.currentTimeMillis()).defaultNamespace(Namespace.empty()).addRepresentations(trino).addRepresentations(spark).build();
    // add all different view versions and set it to using sparkOnly
    ViewMetadata metadata = ViewMetadata.builder().setLocation("custom-location").addSchema(schema).addVersion(sparkOnly).addVersion(trinoOnly).addVersion(trinoAndSpark).setCurrentVersionId(1).build();
    assertThatThrownBy(() -> ViewMetadata.buildFrom(metadata).// switches from sparkOnly to trinoOnly. Intermediate versionId updates are
    // ignored
    setCurrentVersionId(trinoAndSpark.versionId()).setCurrentVersionId(sparkOnly.versionId()).setCurrentVersionId(trinoOnly.versionId()).build()).isInstanceOf(IllegalStateException.class).hasMessage("Cannot replace view due to loss of view dialects (replace.drop-dialect.allowed=false):\n" + "Previous dialects: [spark]\n" + "New dialects: [trino]");
    assertThatThrownBy(() -> ViewMetadata.buildFrom(ViewMetadata.buildFrom(metadata).setCurrentVersionId(trinoAndSpark.versionId()).build()).// switches from trinoAndSpark back to trinoOnly. Intermediate versionId
    // updates are ignored
    setCurrentVersionId(sparkOnly.versionId()).setCurrentVersionId(trinoOnly.versionId()).build()).isInstanceOf(IllegalStateException.class).hasMessage("Cannot replace view due to loss of view dialects (replace.drop-dialect.allowed=false):\n" + "Previous dialects: [trino, spark]\n" + "New dialects: [trino]");
}

