@Test
public void concurrentReplaceViewVersion() {
    TableIdentifier identifier = TableIdentifier.of("ns", "view");
    if (requiresNamespaceCreate()) {
        catalog().createNamespace(identifier.namespace());
    }
    assertThat(catalog().viewExists(identifier)).as("View should not exist").isFalse();
    View view = catalog().buildView(identifier).withSchema(SCHEMA).withDefaultNamespace(identifier.namespace()).withQuery("trino", "select * from ns.tbl").withProperty(ViewProperties.REPLACE_DROP_DIALECT_ALLOWED, "true").create();
    assertThat(catalog().viewExists(identifier)).as("View should exist").isTrue();
    ReplaceViewVersion replaceViewVersionOne = view.replaceVersion().withQuery("trino", "select count(id) from ns.tbl").withSchema(SCHEMA).withDefaultNamespace(identifier.namespace());
    ReplaceViewVersion replaceViewVersionTwo = view.replaceVersion().withQuery("spark", "select count(some_id) from ns.tbl").withSchema(OTHER_SCHEMA).withDefaultNamespace(identifier.namespace());
    // simulate a concurrent replace of the view version
    ViewOperations viewOps = ((BaseView) view).operations();
    ViewMetadata current = viewOps.current();
    ViewMetadata trinoUpdate = ((ViewVersionReplace) replaceViewVersionTwo).internalApply();
    ViewMetadata sparkUpdate = ((ViewVersionReplace) replaceViewVersionOne).internalApply();
    viewOps.commit(current, trinoUpdate);
    if (supportsServerSideRetry()) {
        // retry should succeed and the changes should be applied
        viewOps.commit(current, sparkUpdate);
        View updatedView = catalog().loadView(identifier);
        ViewVersion viewVersion = updatedView.currentVersion();
        assertThat(viewVersion.versionId()).isEqualTo(3);
        assertThat(updatedView.versions()).hasSize(3);
        assertThat(updatedView.version(1)).isEqualTo(ImmutableViewVersion.builder().timestampMillis(updatedView.version(1).timestampMillis()).versionId(1).schemaId(0).summary(updatedView.version(1).summary()).defaultNamespace(identifier.namespace()).addRepresentations(ImmutableSQLViewRepresentation.builder().sql("select * from ns.tbl").dialect("trino").build()).build());
        assertThat(updatedView.version(2)).isEqualTo(ImmutableViewVersion.builder().timestampMillis(updatedView.version(2).timestampMillis()).versionId(2).schemaId(1).summary(updatedView.version(2).summary()).defaultNamespace(identifier.namespace()).addRepresentations(ImmutableSQLViewRepresentation.builder().sql("select count(some_id) from ns.tbl").dialect("spark").build()).build());
        assertThat(updatedView.version(3)).isEqualTo(ImmutableViewVersion.builder().timestampMillis(updatedView.version(3).timestampMillis()).versionId(3).schemaId(0).summary(updatedView.version(3).summary()).defaultNamespace(identifier.namespace()).addRepresentations(ImmutableSQLViewRepresentation.builder().sql("select count(id) from ns.tbl").dialect("trino").build()).build());
    } else {
        assertThatThrownBy(() -> viewOps.commit(current, sparkUpdate)).isInstanceOf(CommitFailedException.class).hasMessageContaining("Cannot commit");
        View updatedView = catalog().loadView(identifier);
        ViewVersion viewVersion = updatedView.currentVersion();
        assertThat(viewVersion.versionId()).isEqualTo(2);
        assertThat(updatedView.versions()).hasSize(2);
        assertThat(updatedView.version(1)).isEqualTo(ImmutableViewVersion.builder().timestampMillis(updatedView.version(1).timestampMillis()).versionId(1).schemaId(0).summary(updatedView.version(1).summary()).defaultNamespace(identifier.namespace()).addRepresentations(ImmutableSQLViewRepresentation.builder().sql("select * from ns.tbl").dialect("trino").build()).build());
        assertThat(updatedView.version(2)).isEqualTo(ImmutableViewVersion.builder().timestampMillis(updatedView.version(2).timestampMillis()).versionId(2).schemaId(1).summary(updatedView.version(2).summary()).defaultNamespace(identifier.namespace()).addRepresentations(ImmutableSQLViewRepresentation.builder().sql("select count(some_id) from ns.tbl").dialect("spark").build()).build());
    }
}

