@Test
public void writeAndValidateTimestamps() throws IOException {
    TimeZone currentTz = TimeZone.getDefault();
    try {
        Schema timestampSchema = new Schema(required(1, "tsTzCol", Types.TimestampType.withZone()), required(2, "tsCol", Types.TimestampType.withoutZone()));
        // Write using America/New_York timezone
        TimeZone.setDefault(TimeZone.getTimeZone("America/New_York"));
        GenericRecord record1 = GenericRecord.create(timestampSchema);
        record1.setField("tsTzCol", OffsetDateTime.parse("2017-01-16T17:10:34-08:00"));
        record1.setField("tsCol", LocalDateTime.parse("1970-01-01T00:01:00"));
        GenericRecord record2 = GenericRecord.create(timestampSchema);
        record2.setField("tsTzCol", OffsetDateTime.parse("2017-05-16T17:10:34-08:00"));
        record2.setField("tsCol", LocalDateTime.parse("1970-05-01T00:01:00"));
        GenericRecord record3 = GenericRecord.create(timestampSchema);
        record3.setField("tsTzCol", OffsetDateTime.parse("1935-01-16T17:10:34-08:00"));
        record3.setField("tsCol", LocalDateTime.parse("1935-01-01T00:01:00"));
        GenericRecord record4 = GenericRecord.create(timestampSchema);
        record4.setField("tsTzCol", OffsetDateTime.parse("1935-05-16T17:10:34-08:00"));
        record4.setField("tsCol", LocalDateTime.parse("1935-05-01T00:01:00"));
        File testFile = temp.resolve("test-file" + System.nanoTime()).toFile();
        try (FileAppender<Record> writer = ORC.write(Files.localOutput(testFile)).schema(timestampSchema).createWriterFunc(GenericOrcWriter::buildWriter).build()) {
            writer.add(record1);
            writer.add(record2);
            writer.add(record3);
            writer.add(record4);
        }
        // Read using Asia/Kolkata timezone
        TimeZone.setDefault(TimeZone.getTimeZone("Asia/Kolkata"));
        List<Record> rows;
        try (CloseableIterable<Record> reader = ORC.read(Files.localInput(testFile)).project(timestampSchema).createReaderFunc(fileSchema -> GenericOrcReader.buildReader(timestampSchema, fileSchema)).build()) {
            rows = Lists.newArrayList(reader);
        }
        assertThat(rows).element(0).satisfies(record -> {
            assertThat(record.getField("tsTzCol")).isEqualTo(OffsetDateTime.parse("2017-01-17T01:10:34Z"));
            assertThat(record.getField("tsCol")).isEqualTo(LocalDateTime.parse("1970-01-01T00:01:00"));
        });
        assertThat(rows).element(1).satisfies(record -> {
            assertThat(record.getField("tsTzCol")).isEqualTo(OffsetDateTime.parse("2017-05-17T01:10:34Z"));
            assertThat(record.getField("tsCol")).isEqualTo(LocalDateTime.parse("1970-05-01T00:01:00"));
        });
        assertThat(rows).element(2).satisfies(record -> {
            assertThat(record.getField("tsTzCol")).isEqualTo(OffsetDateTime.parse("1935-01-17T01:10:34Z"));
            assertThat(record.getField("tsCol")).isEqualTo(LocalDateTime.parse("1935-01-01T00:01:00"));
        });
        assertThat(rows).element(3).satisfies(record -> {
            assertThat(record.getField("tsTzCol")).isEqualTo(OffsetDateTime.parse("1935-05-17T01:10:34Z"));
            assertThat(record.getField("tsCol")).isEqualTo(LocalDateTime.parse("1935-05-01T00:01:00"));
        });
    } finally {
        TimeZone.setDefault(currentTz);
    }
}

