@Test
public void testTwoLevelList() throws IOException {
    Schema schema = new Schema(optional(1, "arraybytes", Types.ListType.ofRequired(3, Types.BinaryType.get())), optional(2, "topbytes", Types.BinaryType.get()));
    org.apache.avro.Schema avroSchema = AvroSchemaUtil.convert(schema.asStruct());
    File testFile = temp.resolve("test-file" + System.nanoTime()).toFile();
    ParquetWriter<org.apache.avro.generic.GenericRecord> writer = AvroParquetWriter.<org.apache.avro.generic.GenericRecord>builder(new Path(testFile.toURI())).withDataModel(GenericData.get()).withSchema(avroSchema).config("parquet.avro.add-list-element-records", "true").config("parquet.avro.write-old-list-structure", "true").build();
    GenericRecordBuilder recordBuilder = new GenericRecordBuilder(avroSchema);
    List<ByteBuffer> expectedByteList = new ArrayList();
    byte[] expectedByte = { 0x00, 0x01 };
    ByteBuffer expectedBinary = ByteBuffer.wrap(expectedByte);
    expectedByteList.add(expectedBinary);
    recordBuilder.set("arraybytes", expectedByteList);
    recordBuilder.set("topbytes", expectedBinary);
    GenericData.Record expectedRecord = recordBuilder.build();
    writer.write(expectedRecord);
    writer.close();
    // test reuseContainers
    try (CloseableIterable<Record> reader = Parquet.read(Files.localInput(testFile)).project(schema).reuseContainers().createReaderFunc(fileSchema -> GenericParquetReaders.buildReader(schema, fileSchema)).build()) {
        for (Record actualRecord : reader) {
            assertThat(actualRecord.get(0, ArrayList.class)).first().isEqualTo(expectedBinary);
            assertThat(actualRecord.get(1, ByteBuffer.class)).isEqualTo(expectedBinary);
        }
        assertThat(Lists.newArrayList(reader)).hasSize(1);
    }
}

@Test
public void testTwoLevelList() throws IOException {
    Schema schema = new Schema(optional(1, "arraybytes", Types.ListType.ofRequired(3, Types.BinaryType.get())), optional(2, "topbytes", Types.BinaryType.get()));
    org.apache.avro.Schema avroSchema = AvroSchemaUtil.convert(schema.asStruct());
    File testFile = temp.resolve("test-file" + System.nanoTime()).toFile();
    SecureRandom rand = new SecureRandom();
    rand.nextBytes(FILE_DEK.array());
    rand.nextBytes(AAD_PREFIX.array());
    FileEncryptionProperties fileEncryptionProperties = FileEncryptionProperties.builder(FILE_DEK.array()).withAADPrefix(AAD_PREFIX.array()).build();
    ParquetWriter<org.apache.avro.generic.GenericRecord> writer = AvroParquetWriter.<org.apache.avro.generic.GenericRecord>builder(new Path(testFile.toURI())).withDataModel(GenericData.get()).withSchema(avroSchema).withEncryption(fileEncryptionProperties).config("parquet.avro.add-list-element-records", "true").config("parquet.avro.write-old-list-structure", "true").build();
    GenericRecordBuilder recordBuilder = new GenericRecordBuilder(avroSchema);
    List<ByteBuffer> expectedByteList = new ArrayList();
    byte[] expectedByte = { 0x00, 0x01 };
    ByteBuffer expectedBinary = ByteBuffer.wrap(expectedByte);
    expectedByteList.add(expectedBinary);
    recordBuilder.set("arraybytes", expectedByteList);
    recordBuilder.set("topbytes", expectedBinary);
    GenericData.Record expectedRecord = recordBuilder.build();
    writer.write(expectedRecord);
    writer.close();
    // test reuseContainers
    try (CloseableIterable<Record> reader = Parquet.read(Files.localInput(testFile)).project(schema).withFileEncryptionKey(FILE_DEK).withAADPrefix(AAD_PREFIX).reuseContainers().createReaderFunc(fileSchema -> GenericParquetReaders.buildReader(schema, fileSchema)).build()) {
        CloseableIterator it = reader.iterator();
        assertThat(it).hasNext();
        while (it.hasNext()) {
            GenericRecord actualRecord = (GenericRecord) it.next();
            assertThat(actualRecord.get(0, ArrayList.class)).first().isEqualTo(expectedBinary);
            assertThat(actualRecord.get(1, ByteBuffer.class)).isEqualTo(expectedBinary);
            assertThat(it).isExhausted();
        }
    }
}

