@Test
public void testEqualityDeletePlanningStatsPartitionPruningIgnoreResidual() throws IOException {
    table.updateSpec().addField("category").commit();
    PartitionData partitionData = new PartitionData(table.spec().partitionType());
    DataFile evenFile = FileHelpers.writeDataFile(table, Files.localOutput(createTempFile()), evenRecords, partitionData.copyFor(Row.of("even")));
    DataFile oddFile = FileHelpers.writeDataFile(table, Files.localOutput(createTempFile()), oddRecords, partitionData.copyFor(Row.of("odd")));
    table.newAppend().appendFile(evenFile).appendFile(oddFile).commit();
    Schema deleteRowSchema = table.schema().select("data");
    Record delete = GenericRecord.create(deleteRowSchema);
    List<Record> oddDeletes = Lists.newArrayList();
    oddDeletes.add(delete.copy("data", "a"));
    oddDeletes.add(delete.copy("data", "c"));
    List<Record> evenDeletes = Lists.newArrayList();
    evenDeletes.add(delete.copy("data", "b"));
    DeleteFile oddDeleteFile = FileHelpers.writeDeleteFile(table, Files.localOutput(createTempFile()), partitionData.copyFor(Row.of("odd")), oddDeletes, deleteRowSchema);
    DeleteFile evenDeleteFile = FileHelpers.writeDeleteFile(table, Files.localOutput(createTempFile()), partitionData.copyFor(Row.of("even")), evenDeletes, deleteRowSchema);
    // Create a manifest that only has deletes for the "odd" partition
    table.newRowDelta().addDeletes(oddDeleteFile).commit();
    // Create a manifest which has deletes for both "even" and "odd" partitions
    table.newRowDelta().addDeletes(oddDeleteFile).addDeletes(evenDeleteFile).commit();
    Expression expr = Expressions.equal("category", "even");
    InMemoryMetricsReporter reporter = new InMemoryMetricsReporter();
    List<FileScanTask> tasks;
    try (CloseableIterable<FileScanTask> tasksIterable = table.newScan().filter(expr).metricsReporter(reporter).ignoreResiduals().planFiles()) {
        tasks = Lists.newArrayList(tasksIterable);
    }
    assertThat(tasks).as("Should produce one task since we filtered out one partition").hasSize(1);
    FileScanTask task = tasks.get(0);
    assertThat(task.partition()).isEqualTo(partitionData.copyFor(Row.of("even")));
    assertThat(task.deletes()).as("Should have one delete file, ignoreResiduals prevents filtering out the delete file").hasSize(1);
    ScanMetricsResult scanReport = reporter.scanReport().scanMetrics();
    assertThat(scanReport.totalDeleteManifests().value()).as("Should be 2 delete manifests, one for odds and one with both odds and evens").isEqualTo(2);
    assertThat(scanReport.skippedDeleteManifests().value()).as("The manifest with only odd deletes should be skipped").isEqualTo(1);
    assertThat(scanReport.equalityDeleteFiles().value()).as("The even deletefile entry should be scanned").isEqualTo(1);
    assertThat(scanReport.skippedDeleteFiles().value()).as("The odd deletefile entry should be skipped").isEqualTo(1);
}

