    ecsCatalog.createTable(TableIdentifier.of("a", "t1"), SCHEMA);
    assertThatThrownBy(() -> ecsCatalog.dropNamespace(Namespace.of("unknown"))).isInstanceOf(NoSuchNamespaceException.class).hasMessage("Namespace unknown does not exist");
