@Test
void testDeleteOrphanFilesFailure() throws Exception {
    Table table = createTable();
    insert(table, 1, "a");
    insert(table, 2, "b");
    insert(table, 3, "c");
    insert(table, 4, "d");
    assertFileNum(table, 4, 0);
    Path inData = relative(table, "metadata/in_data");
    Path inMetadata = relative(table, "metadata/in_metadata");
    createFiles(inData);
    createFiles(inMetadata);
    assertThat(inMetadata).exists();
    assertThat(inData).exists();
    appendDeleteOrphanFiles();
    // Mock error in the delete files operator
    Long parentId = table.currentSnapshot().parentId();
    for (ManifestFile manifestFile : table.snapshot(parentId).allManifests(table.io())) {
        table.io().deleteFile(manifestFile.path());
    }
    runAndWaitForResult(infra.env(), infra.source(), infra.sink(), false, /* generateFailure */
    () -> checkDeleteFinished(table.name(), 0L), false);
    // An error occurred; the file should not be deleted. And the job should not be failed.
    assertThat(inMetadata).exists();
    assertThat(inData).exists();
    // Check the metrics
    MetricsReporterFactoryForTests.assertCounters(new ImmutableMap.Builder<List<String>, Long>().put(ImmutableList.of(PLANNER_TASK_NAME + "[0]", table.name(), DUMMY_TASK_NAME, "0", ERROR_COUNTER), 0L).put(ImmutableList.of(READER_TASK_NAME + "[0]", table.name(), DUMMY_TASK_NAME, "0", ERROR_COUNTER), 1L).put(ImmutableList.of(FILESYSTEM_FILES_TASK_NAME + "[0]", table.name(), DUMMY_TASK_NAME, "0", ERROR_COUNTER), 0L).put(ImmutableList.of(METADATA_FILES_TASK_NAME + "[0]", table.name(), DUMMY_TASK_NAME, "0", ERROR_COUNTER), 0L).put(ImmutableList.of(DELETE_FILES_TASK_NAME + "[0]", table.name(), DUMMY_TASK_NAME, "0", DELETE_FILE_FAILED_COUNTER), 0L).put(ImmutableList.of(DELETE_FILES_TASK_NAME + "[0]", table.name(), DUMMY_TASK_NAME, "0", DELETE_FILE_SUCCEEDED_COUNTER), 0L).build());
