    ExpireSnapshots.builder().parallelism(1).planningWorkerPoolSize(2).deleteBatchSize(3).maxSnapshotAge(Duration.ZERO).retainLast(1).uidSuffix(UID_SUFFIX).append(infra.triggerStream(), DUMMY_TABLE_NAME, DUMMY_TASK_NAME, 0, tableLoader(), "OTHER", StreamGraphGenerator.DEFAULT_SLOT_SHARING_GROUP, 1).sinkTo(infra.sink());
