    DynamicCommitter dynamicCommitter = new CommitHookEnabledDynamicCommitter(commitHook, CATALOG_EXTENSION.catalog(), Maps.newHashMap(), overwriteMode, workerPoolSize, sinkId, committerMetrics);
    ThrowingCallable commitExecutable = () -> dynamicCommitter.commit(Sets.newHashSet(commitRequest1, commitRequest2, commitRequest3));
    // First fail pre-commit
    assertThatThrownBy(commitExecutable);
    assertThat(FailBeforeAndAfterCommit.failedBeforeCommit).isTrue();
    // Second fail during commit
    assertThatThrownBy(commitExecutable);
    assertThat(FailBeforeAndAfterCommit.failedDuringCommit).isTrue();
    // Third fail after commit
    assertThatThrownBy(commitExecutable);
    assertThat(FailBeforeAndAfterCommit.failedAfterCommit).isTrue();
    // Finally commit must go through, although it is a NOOP because the third failure is directly
    // after the commit finished.
    try {
        commitExecutable.call();
    } catch (Throwable e) {
        fail("Should not have thrown an exception");
    }
    table.refresh();
    // Three committables, but only two snapshots! WriteResults from different checkpoints are not
    // getting
    // combined due to one writeResult2 containing a delete file.
    assertThat(table.snapshots()).hasSize(2);
    Snapshot snapshot1 = Iterables.getFirst(table.snapshots(), null);
    assertThat(snapshot1.summary()).containsAllEntriesOf(ImmutableMap.<String, String>builder().put("added-data-files", "1").put("added-records", "42").put("changed-partition-count", "1").put("flink.job-id", jobId).put("flink.max-committed-checkpoint-id", "" + checkpointId1).put("flink.operator-id", operatorId).put("total-data-files", "1").put("total-delete-files", "0").put("total-equality-deletes", "0").put("total-files-size", "0").put("total-position-deletes", "0").put("total-records", "42").build());
    Snapshot snapshot2 = Iterables.get(table.snapshots(), 1);
    assertThat(snapshot2.summary()).containsAllEntriesOf(ImmutableMap.<String, String>builder().put("added-data-files", "1").put("added-records", "42").put("changed-partition-count", "1").put("flink.job-id", jobId).put("flink.max-committed-checkpoint-id", "" + checkpointId2).put("flink.operator-id", operatorId).put("total-data-files", "2").put("total-delete-files", "1").put("total-equality-deletes", "0").put("total-files-size", "0").put("total-position-deletes", "24").put("total-records", "84").build());
}

