    List<DynamicIcebergDataImpl> rows = Lists.newArrayList(new DynamicIcebergDataImpl(SimpleDataUtil.SCHEMA, "t1", "main", PartitionSpec.unpartitioned()), new DynamicIcebergDataImpl(SimpleDataUtil.SCHEMA, "t2", "main", PartitionSpec.unpartitioned()));
