@EnumSource(StatisticsType.class)
public void receiveOlderStatisticsEventTest(StatisticsType type) {
    AggregatedStatisticsTracker tracker = createTracker(type);
    StatisticsEvent checkpoint2Subtask0StatisticsEvent = createStatisticsEvent(type, TASK_STATISTICS_SERIALIZER, 2L, CHAR_KEYS.get("a"), CHAR_KEYS.get("b"), CHAR_KEYS.get("b"));
    CompletedStatistics completedStatistics = tracker.updateAndCheckCompletion(0, checkpoint2Subtask0StatisticsEvent);
    assertThat(completedStatistics).isNull();
    assertThat(tracker.aggregationsPerCheckpoint().keySet()).containsExactlyInAnyOrder(2L);
    AggregatedStatisticsTracker.Aggregation aggregation = tracker.aggregationsPerCheckpoint().get(2L);
    assertThat(aggregation.currentType()).isEqualTo(StatisticsUtil.collectType(type));
    if (StatisticsUtil.collectType(type) == StatisticsType.Map) {
        assertThat(aggregation.mapStatistics()).isEqualTo(ImmutableMap.of(CHAR_KEYS.get("a"), 1L, CHAR_KEYS.get("b"), 2L));
    } else {
        assertThat(aggregation.sketchStatistics().getResult().getSamples()).containsExactlyInAnyOrder(CHAR_KEYS.get("a"), CHAR_KEYS.get("b"), CHAR_KEYS.get("b"));
    }
    StatisticsEvent checkpoint1Subtask1StatisticsEvent = createStatisticsEvent(type, TASK_STATISTICS_SERIALIZER, 1L, CHAR_KEYS.get("b"));
    completedStatistics = tracker.updateAndCheckCompletion(1, checkpoint1Subtask1StatisticsEvent);
    assertThat(completedStatistics).isNull();
    // both checkpoints are tracked
    assertThat(tracker.aggregationsPerCheckpoint().keySet()).containsExactlyInAnyOrder(1L, 2L);
    aggregation = tracker.aggregationsPerCheckpoint().get(1L);
    assertThat(aggregation.currentType()).isEqualTo(StatisticsUtil.collectType(type));
    if (StatisticsUtil.collectType(type) == StatisticsType.Map) {
        assertThat(aggregation.mapStatistics()).isEqualTo(ImmutableMap.of(CHAR_KEYS.get("b"), 1L));
    } else {
        assertThat(aggregation.sketchStatistics().getResult().getSamples()).containsExactlyInAnyOrder(CHAR_KEYS.get("b"));
    }
    StatisticsEvent checkpoint3Subtask0StatisticsEvent = createStatisticsEvent(type, TASK_STATISTICS_SERIALIZER, 3L, CHAR_KEYS.get("x"));
    completedStatistics = tracker.updateAndCheckCompletion(1, checkpoint3Subtask0StatisticsEvent);
    assertThat(completedStatistics).isNull();
    assertThat(tracker.aggregationsPerCheckpoint().keySet()).containsExactlyInAnyOrder(1L, 2L, 3L);
    aggregation = tracker.aggregationsPerCheckpoint().get(3L);
    assertThat(aggregation.currentType()).isEqualTo(StatisticsUtil.collectType(type));
    if (StatisticsUtil.collectType(type) == StatisticsType.Map) {
        assertThat(aggregation.mapStatistics()).isEqualTo(ImmutableMap.of(CHAR_KEYS.get("x"), 1L));
    } else {
        assertThat(aggregation.sketchStatistics().getResult().getSamples()).containsExactlyInAnyOrder(CHAR_KEYS.get("x"));
    }
    StatisticsEvent checkpoint2Subtask1StatisticsEvent = createStatisticsEvent(type, TASK_STATISTICS_SERIALIZER, 2L, CHAR_KEYS.get("a"), CHAR_KEYS.get("b"), CHAR_KEYS.get("b"));
    completedStatistics = tracker.updateAndCheckCompletion(1, checkpoint2Subtask1StatisticsEvent);
    // checkpoint 1 is cleared along with checkpoint 2. checkpoint 3 remains
    assertThat(tracker.aggregationsPerCheckpoint().keySet()).containsExactlyInAnyOrder(3L);
    aggregation = tracker.aggregationsPerCheckpoint().get(3L);
    assertThat(aggregation.currentType()).isEqualTo(StatisticsUtil.collectType(type));
    if (StatisticsUtil.collectType(type) == StatisticsType.Map) {
        assertThat(aggregation.mapStatistics()).isEqualTo(ImmutableMap.of(CHAR_KEYS.get("x"), 1L));
    } else {
        assertThat(aggregation.sketchStatistics().getResult().getSamples()).containsExactlyInAnyOrder(CHAR_KEYS.get("x"));
    }
    assertThat(completedStatistics).isNotNull();
    assertThat(completedStatistics.type()).isEqualTo(StatisticsUtil.collectType(type));
    assertThat(completedStatistics.checkpointId()).isEqualTo(2L);
    if (StatisticsUtil.collectType(type) == StatisticsType.Map) {
        assertThat(completedStatistics.keyFrequency()).isEqualTo(ImmutableMap.of(CHAR_KEYS.get("a"), 2L, CHAR_KEYS.get("b"), 4L));
    } else {
        assertThat(completedStatistics.keySamples()).containsExactly(CHAR_KEYS.get("a"), CHAR_KEYS.get("b"), CHAR_KEYS.get("b"), CHAR_KEYS.get("a"), CHAR_KEYS.get("b"), CHAR_KEYS.get("b"));
    }
}

