    LOG.info("Map parallelism {}: max skew statistics over {} iterations: mean = {}, min = {}, max = {}", parallelism, ITERATIONS, format("%.4f", maxSkewStats.getAverage()), format("%.4f", maxSkewStats.getMin()), format("%.4f", maxSkewStats.getMax()));
