        assertThat(pk1.get(1, String.class)).isEqualTo(record.get(0));
        pk2.partition(rowWrapper.wrap(row));
        assertThat(pk2.size()).isEqualTo(2);
        assertThat(pk2.get(0, String.class)).isEqualTo(record.get(0));
