    ///////////////////////////////
    // assert second batch with full batch of 2 records
    ArrayBatchRecords<RowData> batch1 = (ArrayBatchRecords<RowData>) recordBatchIterator.next();
    assertThat(batch1.records()).containsExactlyInAnyOrder(batch0.records());
