@Test
public void testMultipleFilesWithSeekPosition() throws Exception {
    List<Record> records0 = RandomGenericData.generate(TestFixtures.SCHEMA, 1, 1);
    FileScanTask fileTask0 = ReaderUtil.createFileTask(records0, File.createTempFile("junit", null, temporaryFolder.toFile()), FILE_FORMAT, appenderFactory);
