@Test
public void testLike() {
    UnboundPredicate<?> expected = org.apache.iceberg.expressions.Expressions.startsWith("field5", "abc");
    Expression expr = resolve(ApiExpressionUtils.unresolvedCall(BuiltInFunctionDefinitions.LIKE, Expressions.$("field5"), Expressions.lit("abc%")));
    Optional<org.apache.iceberg.expressions.Expression> actual = FlinkFilters.convert(expr);
    assertThat(actual).isPresent();
    assertPredicatesMatch(expected, actual.get());
    expr = resolve(ApiExpressionUtils.unresolvedCall(BuiltInFunctionDefinitions.LIKE, Expressions.$("field5"), Expressions.lit("%abc")));
    actual = FlinkFilters.convert(expr);
    assertThat(actual).isNotPresent();
    expr = resolve(ApiExpressionUtils.unresolvedCall(BuiltInFunctionDefinitions.LIKE, Expressions.$("field5"), Expressions.lit("%abc%")));
    actual = FlinkFilters.convert(expr);
    assertThat(actual).isNotPresent();
    expr = resolve(ApiExpressionUtils.unresolvedCall(BuiltInFunctionDefinitions.LIKE, Expressions.$("field5"), Expressions.lit("abc%d")));
    actual = FlinkFilters.convert(expr);
    assertThat(actual).isNotPresent();
    expr = resolve(ApiExpressionUtils.unresolvedCall(BuiltInFunctionDefinitions.LIKE, Expressions.$("field5"), Expressions.lit("%")));
    actual = FlinkFilters.convert(expr);
    assertThat(actual).isNotPresent();
    expr = resolve(ApiExpressionUtils.unresolvedCall(BuiltInFunctionDefinitions.LIKE, Expressions.$("field5"), Expressions.lit("a_")));
    actual = FlinkFilters.convert(expr);
    assertThat(actual).isNotPresent();
    expr = resolve(ApiExpressionUtils.unresolvedCall(BuiltInFunctionDefinitions.LIKE, Expressions.$("field5"), Expressions.lit("a%b")));
    actual = FlinkFilters.convert(expr);
    assertThat(actual).isNotPresent();
}

