void testSchemaEvolutionFieldOrderChanges() throws Exception {
    Schema schema = new Schema(Types.NestedField.required(0, "id", Types.IntegerType.get()), Types.NestedField.required(1, "data", Types.StringType.get()));
    Schema expectedSchema = new Schema(Types.NestedField.required(1, "id", Types.IntegerType.get()), Types.NestedField.required(2, "data", Types.StringType.get()));
    Schema schema2 = new Schema(Types.NestedField.required(0, "id", Types.IntegerType.get()), Types.NestedField.required(1, "extra", Types.StringType.get()), Types.NestedField.required(2, "data", Types.StringType.get()));
    Schema expectedSchema2 = new Schema(Types.NestedField.required(1, "id", Types.IntegerType.get()), Types.NestedField.optional(3, "extra", Types.StringType.get()), Types.NestedField.required(2, "data", Types.StringType.get()));
    List<DynamicIcebergDataImpl> rows = Lists.newArrayList(new DynamicIcebergDataImpl(schema, expectedSchema, "t1", "main", PartitionSpec.unpartitioned()), new DynamicIcebergDataImpl(schema, expectedSchema, "t1", "main", PartitionSpec.unpartitioned()), new DynamicIcebergDataImpl(schema, expectedSchema, "t1", "main", PartitionSpec.unpartitioned()), new DynamicIcebergDataImpl(schema2, expectedSchema2, "t1", "main", PartitionSpec.unpartitioned()), new DynamicIcebergDataImpl(schema2, expectedSchema2, "t1", "main", PartitionSpec.unpartitioned()));
    for (DynamicIcebergDataImpl row : rows) {
        if (row.schemaExpected == expectedSchema) {
            // We manually adjust the expected Row to match the second expected schema
            row.rowExpected = Row.of(row.rowProvided.getField(0), null, row.rowProvided.getField(1));
        }
    }
    runTest(rows);
}

