@Test
void testAggregator() throws Exception {
    CATALOG_EXTENSION.catalog().createTable(TableIdentifier.of("table"), new Schema());
    CATALOG_EXTENSION.catalog().createTable(TableIdentifier.of("table2"), new Schema());
    DynamicWriteResultAggregator aggregator = new DynamicWriteResultAggregator(CATALOG_EXTENSION.catalogLoader());
    try (OneInputStreamOperatorTestHarness<CommittableMessage<DynamicWriteResult>, CommittableMessage<DynamicCommittable>> testHarness = new OneInputStreamOperatorTestHarness<>(aggregator)) {
        testHarness.open();
        WriteTarget writeTarget1 = new WriteTarget("table", "branch", 42, 0, true, Sets.newHashSet());
        DynamicWriteResult dynamicWriteResult1 = new DynamicWriteResult(writeTarget1, WriteResult.builder().build());
        WriteTarget writeTarget2 = new WriteTarget("table2", "branch", 42, 0, true, Sets.newHashSet(1, 2));
        DynamicWriteResult dynamicWriteResult2 = new DynamicWriteResult(writeTarget2, WriteResult.builder().build());
        CommittableWithLineage<DynamicWriteResult> committable1 = new CommittableWithLineage<>(dynamicWriteResult1, 0, 0);
        StreamRecord<CommittableMessage<DynamicWriteResult>> record1 = new StreamRecord<>(committable1);
        testHarness.processElement(record1);
        CommittableWithLineage<DynamicWriteResult> committable2 = new CommittableWithLineage<>(dynamicWriteResult2, 0, 0);
        StreamRecord<CommittableMessage<DynamicWriteResult>> record2 = new StreamRecord<>(committable2);
        testHarness.processElement(record2);
        assertThat(testHarness.getOutput()).isEmpty();
        testHarness.prepareSnapshotPreBarrier(1L);
        // Contains a CommittableSummary + DynamicCommittable
        assertThat(testHarness.getRecordOutput()).hasSize(3);
        testHarness.prepareSnapshotPreBarrier(2L);
        // Only contains a CommittableSummary
        assertThat(testHarness.getRecordOutput()).hasSize(4);
    }
}

@Test
void testRoundtrip() throws IOException {
    DynamicWriteResult dynamicWriteResult = new DynamicWriteResult(new WriteTarget("table", "branch", 42, 23, false, Sets.newHashSet(1, 2)), WriteResult.builder().addDataFiles(DATA_FILE).build());
    DynamicWriteResultSerializer serializer = new DynamicWriteResultSerializer();
    DynamicWriteResult copy = serializer.deserialize(serializer.getVersion(), serializer.serialize(dynamicWriteResult));
    assertThat(copy.writeResult().dataFiles()).hasSize(1);
    DataFile dataFile = copy.writeResult().dataFiles()[0];
    // DataFile doesn't implement equals, but we can still do basic checks
    assertThat(dataFile.path()).isEqualTo("/path/to/data-1.parquet");
    assertThat(dataFile.recordCount()).isEqualTo(42L);
}

