    RowData oldData = generator.generateFlinkRowData();
    Schema oldSchema = generator.icebergSchema();
    Types.NestedField structField = oldSchema.columns().get(1);
    Schema newSchema = new Schema(oldSchema.columns().get(0), Types.NestedField.optional(10, "newFieldOptionalField", Types.StructType.of(Types.NestedField.optional(structField.fieldId(), structField.name(), Types.StructType.of(optional(101, "id", Types.IntegerType.get()), // Required columns which leads to nulling the entire struct
    required(103, "required", Types.StringType.get()), required(102, "name", Types.StringType.get()))))));
    RowData expectedData = GenericRowData.of(StringData.fromString("row_id_value"), null);
    assertThat(convert(oldData, oldSchema, newSchema)).isEqualTo(expectedData);
}

