    Supplier<RowDataSerializer> creator1a = () -> cache.serializer("table", schema1, PartitionSpec.unpartitioned());
    Supplier<RowDataSerializer> creator1b = () -> cache.serializer("table", schema2, PartitionSpec.unpartitioned());
