@Test
public void coordinatorSwitchToSketchOverThreshold() {
    int parallelism = 3;
    int downstreamParallelism = 3;
    int switchToSketchThreshold = 3;
    AggregatedStatisticsTracker tracker = new AggregatedStatisticsTracker("testOperator", parallelism, Fixtures.SCHEMA, Fixtures.SORT_ORDER, downstreamParallelism, StatisticsType.Auto, switchToSketchThreshold, null);
    StatisticsEvent checkpoint1Subtask0StatisticsEvent = createStatisticsEvent(StatisticsType.Map, TASK_STATISTICS_SERIALIZER, 1L, CHAR_KEYS.get("a"), CHAR_KEYS.get("b"));
    CompletedStatistics completedStatistics = tracker.updateAndCheckCompletion(0, checkpoint1Subtask0StatisticsEvent);
    assertThat(completedStatistics).isNull();
    assertThat(tracker.aggregationsPerCheckpoint().keySet()).containsExactlyInAnyOrder(1L);
    AggregatedStatisticsTracker.Aggregation aggregation = tracker.aggregationsPerCheckpoint().get(1L);
    assertThat(aggregation.subtaskSet()).containsExactlyInAnyOrder(0);
    assertThat(aggregation.currentType()).isEqualTo(StatisticsType.Map);
    assertThat(aggregation.sketchStatistics()).isNull();
    assertThat(aggregation.mapStatistics()).isEqualTo(ImmutableMap.of(CHAR_KEYS.get("a"), 1L, CHAR_KEYS.get("b"), 1L));
    StatisticsEvent checkpoint1Subtask1StatisticsEvent = createStatisticsEvent(StatisticsType.Map, TASK_STATISTICS_SERIALIZER, 1L, CHAR_KEYS.get("c"), CHAR_KEYS.get("d"));
    completedStatistics = tracker.updateAndCheckCompletion(1, checkpoint1Subtask1StatisticsEvent);
    assertThat(completedStatistics).isNull();
    assertThat(tracker.aggregationsPerCheckpoint().keySet()).containsExactlyInAnyOrder(1L);
    aggregation = tracker.aggregationsPerCheckpoint().get(1L);
    assertThat(aggregation.subtaskSet()).containsExactlyInAnyOrder(0, 1);
    // converted to sketch statistics as map size is 4 (over the switch threshold of 3)
    assertThat(aggregation.currentType()).isEqualTo(StatisticsType.Sketch);
    assertThat(aggregation.mapStatistics()).isNull();
    assertThat(aggregation.sketchStatistics().getResult().getSamples()).containsExactlyInAnyOrder(CHAR_KEYS.get("a"), CHAR_KEYS.get("b"), CHAR_KEYS.get("c"), CHAR_KEYS.get("d"));
    StatisticsEvent checkpoint1Subtask2StatisticsEvent = createStatisticsEvent(StatisticsType.Map, TASK_STATISTICS_SERIALIZER, 1L, CHAR_KEYS.get("e"), CHAR_KEYS.get("f"));
    completedStatistics = tracker.updateAndCheckCompletion(2, checkpoint1Subtask2StatisticsEvent);
    assertThat(tracker.aggregationsPerCheckpoint()).isEmpty();
