@Test
public void testRequestGlobalStatisticsEventHandling() throws Exception {
    try (DataStatisticsCoordinator dataStatisticsCoordinator = createCoordinator(StatisticsType.Sketch)) {
        dataStatisticsCoordinator.start();
        tasksReady(dataStatisticsCoordinator);
        // receive request before global statistics is ready
        dataStatisticsCoordinator.handleEventFromOperator(0, 0, new RequestGlobalStatisticsEvent());
        assertThat(receivingTasks.getSentEventsForSubtask(0)).isEmpty();
        assertThat(receivingTasks.getSentEventsForSubtask(1)).isEmpty();
        StatisticsEvent checkpoint1Subtask0DataStatisticEvent = Fixtures.createStatisticsEvent(StatisticsType.Sketch, Fixtures.TASK_STATISTICS_SERIALIZER, 1L, CHAR_KEYS.get("a"));
        StatisticsEvent checkpoint1Subtask1DataStatisticEvent = Fixtures.createStatisticsEvent(StatisticsType.Sketch, Fixtures.TASK_STATISTICS_SERIALIZER, 1L, CHAR_KEYS.get("b"));
        // Handle events from operators for checkpoint 1
        dataStatisticsCoordinator.handleEventFromOperator(0, 0, checkpoint1Subtask0DataStatisticEvent);
        dataStatisticsCoordinator.handleEventFromOperator(1, 0, checkpoint1Subtask1DataStatisticEvent);
        waitForCoordinatorToProcessActions(dataStatisticsCoordinator);
        Awaitility.await("wait for statistics event").pollInterval(Duration.ofMillis(10)).atMost(Duration.ofSeconds(10)).until(() -> receivingTasks.getSentEventsForSubtask(0).size() == 1);
        assertThat(receivingTasks.getSentEventsForSubtask(0).get(0)).isInstanceOf(StatisticsEvent.class);
        Awaitility.await("wait for statistics event").pollInterval(Duration.ofMillis(10)).atMost(Duration.ofSeconds(10)).until(() -> receivingTasks.getSentEventsForSubtask(1).size() == 1);
        assertThat(receivingTasks.getSentEventsForSubtask(1).get(0)).isInstanceOf(StatisticsEvent.class);
        dataStatisticsCoordinator.handleEventFromOperator(1, 0, new RequestGlobalStatisticsEvent());
        // coordinator should send a response to subtask 1
        Awaitility.await("wait for statistics event").pollInterval(Duration.ofMillis(10)).atMost(Duration.ofSeconds(10)).until(() -> receivingTasks.getSentEventsForSubtask(1).size() == 2);
        assertThat(receivingTasks.getSentEventsForSubtask(1).get(0)).isInstanceOf(StatisticsEvent.class);
        assertThat(receivingTasks.getSentEventsForSubtask(1).get(1)).isInstanceOf(StatisticsEvent.class);
    }
}

@Test
public void testMultipleRequestGlobalStatisticsEvents() throws Exception {
    try (DataStatisticsCoordinator dataStatisticsCoordinator = createCoordinator(StatisticsType.Map)) {
        dataStatisticsCoordinator.start();
        tasksReady(dataStatisticsCoordinator);
        StatisticsEvent checkpoint1Subtask0DataStatisticEvent = Fixtures.createStatisticsEvent(StatisticsType.Map, Fixtures.TASK_STATISTICS_SERIALIZER, 1L, CHAR_KEYS.get("a"));
        StatisticsEvent checkpoint1Subtask1DataStatisticEvent = Fixtures.createStatisticsEvent(StatisticsType.Map, Fixtures.TASK_STATISTICS_SERIALIZER, 1L, CHAR_KEYS.get("b"));
        dataStatisticsCoordinator.handleEventFromOperator(0, 0, checkpoint1Subtask0DataStatisticEvent);
        dataStatisticsCoordinator.handleEventFromOperator(1, 0, checkpoint1Subtask1DataStatisticEvent);
        waitForCoordinatorToProcessActions(dataStatisticsCoordinator);
        // signature is null
        dataStatisticsCoordinator.handleEventFromOperator(0, 0, new RequestGlobalStatisticsEvent());
        // Checkpoint StatisticEvent + RequestGlobalStatisticsEvent
        Awaitility.await("wait for first statistics event").pollInterval(Duration.ofMillis(10)).atMost(Duration.ofSeconds(10)).until(() -> receivingTasks.getSentEventsForSubtask(0).size() == 2);
        // Simulate the scenario where a subtask send global statistics request with the same hash
        // code. The coordinator would skip the response after comparing the request contained hash
        // code with latest global statistics hash code.
        int correctSignature = dataStatisticsCoordinator.globalStatistics().hashCode();
        dataStatisticsCoordinator.handleEventFromOperator(0, 0, new RequestGlobalStatisticsEvent(correctSignature));
        waitForCoordinatorToProcessActions(dataStatisticsCoordinator);
        // Checkpoint StatisticEvent + RequestGlobalStatisticsEvent
        assertThat(receivingTasks.getSentEventsForSubtask(0).size()).isEqualTo(2);
        // signature is different
        dataStatisticsCoordinator.handleEventFromOperator(0, 0, new RequestGlobalStatisticsEvent(correctSignature + 1));
        // Checkpoint StatisticEvent + RequestGlobalStatisticsEvent + RequestGlobalStatisticsEvent
        Awaitility.await("wait for second statistics event").pollInterval(Duration.ofMillis(10)).atMost(Duration.ofSeconds(10)).until(() -> receivingTasks.getSentEventsForSubtask(0).size() == 3);
    }
}

