@Test
public void testNestedProjection() {
    Schema schema = new Schema(Types.NestedField.required(0, "id", Types.LongType.get()), Types.NestedField.optional(3, "location", Types.StructType.of(Types.NestedField.required(1, "lat", Types.FloatType.get()), Types.NestedField.required(2, "long", Types.FloatType.get()))));
    GenericRowData rowData = GenericRowData.of(1L, GenericRowData.of(1.0f, 1.0f));
    GenericRowData copyRowData = GenericRowData.of(1L, GenericRowData.of(1.0f, 1.0f));
    GenericRowData otherRowData = GenericRowData.of(2L, GenericRowData.of(2.0f, 2.0f));
    GenericRowData rowDataNullStruct = GenericRowData.of(1L, null);
    GenericRowData copyRowDataNullStruct = GenericRowData.of(1L, null);
    GenericRowData otherRowDataNullStruct = GenericRowData.of(2L, null);
    // Project id only.
    Schema idOnly = new Schema(Types.NestedField.required(0, "id", Types.LongType.get()));
    assertThat(idOnly.columns()).isNotEmpty();
    generateAndValidate(schema, idOnly);
    testEqualsAndHashCode(schema, idOnly, rowData, copyRowData, otherRowData);
    testEqualsAndHashCode(schema, idOnly, rowDataNullStruct, copyRowDataNullStruct, otherRowDataNullStruct);
    // Project lat only.
    Schema latOnly = new Schema(Types.NestedField.optional(3, "location", Types.StructType.of(Types.NestedField.required(1, "lat", Types.FloatType.get()))));
    assertThat(latOnly.columns()).isNotEmpty();
    generateAndValidate(schema, latOnly);
    testEqualsAndHashCode(schema, latOnly, rowData, copyRowData, otherRowData);
    testEqualsAndHashCode(schema, latOnly, rowDataNullStruct, copyRowDataNullStruct, otherRowDataNullStruct, true);
    // Project long only.
    Schema longOnly = new Schema(Types.NestedField.optional(3, "location", Types.StructType.of(Types.NestedField.required(2, "long", Types.FloatType.get()))));
    assertThat(longOnly.columns()).isNotEmpty();
    generateAndValidate(schema, longOnly);
    testEqualsAndHashCode(schema, longOnly, rowData, copyRowData, otherRowData);
    testEqualsAndHashCode(schema, longOnly, rowDataNullStruct, copyRowDataNullStruct, otherRowDataNullStruct, true);
    // Project location.
    Schema locationOnly = schema.select("location");
    assertThat(locationOnly.columns()).isNotEmpty();
    generateAndValidate(schema, locationOnly);
    testEqualsAndHashCode(schema, locationOnly, rowData, copyRowData, otherRowData);
    testEqualsAndHashCode(schema, locationOnly, rowDataNullStruct, copyRowDataNullStruct, otherRowDataNullStruct, true);
}

