        processAndCheck(source, new TaskResult(0, time, true, Lists.newArrayList()));
        processAndCheck(source, new TaskResult(1, 0L, true, Lists.newArrayList()));
        processAndCheck(source, new TaskResult(1, 0L, true, Lists.newArrayList()));
        processAndCheck(source, new TaskResult(0, time, false, Lists.newArrayList()));
        processAndCheck(source, new TaskResult(0, time, true, Lists.newArrayList()));
        processAndCheck(source, new TaskResult(1, 0L, true, Lists.newArrayList()));
        Awaitility.await().until(() -> MetricsReporterFactoryForTests.counter(ImmutableList.of(DUMMY_TASK_NAME, DUMMY_TABLE_NAME, TASKS[1], "1", SUCCEEDED_TASK_COUNTER)).equals(3L));
        // Final check all the counters
        MetricsReporterFactoryForTests.assertCounters(new ImmutableMap.Builder<List<String>, Long>().put(ImmutableList.of(DUMMY_TASK_NAME, DUMMY_TABLE_NAME, TASKS[0], "0", SUCCEEDED_TASK_COUNTER), 2L).put(ImmutableList.of(DUMMY_TASK_NAME, DUMMY_TABLE_NAME, TASKS[0], "0", FAILED_TASK_COUNTER), 1L).put(ImmutableList.of(DUMMY_TASK_NAME, DUMMY_TABLE_NAME, TASKS[1], "1", SUCCEEDED_TASK_COUNTER), 3L).put(ImmutableList.of(DUMMY_TASK_NAME, DUMMY_TABLE_NAME, TASKS[1], "1", FAILED_TASK_COUNTER), 0L).put(ImmutableList.of(DUMMY_TASK_NAME, DUMMY_TABLE_NAME, TASKS[2], "2", SUCCEEDED_TASK_COUNTER), 0L).put(ImmutableList.of(DUMMY_TASK_NAME, DUMMY_TABLE_NAME, TASKS[2], "2", FAILED_TASK_COUNTER), 0L).build());
        assertThat(MetricsReporterFactoryForTests.gauge(ImmutableList.of(DUMMY_TASK_NAME, DUMMY_TABLE_NAME, TASKS[0], "0", LAST_RUN_DURATION_MS))).isPositive();
        assertThat(MetricsReporterFactoryForTests.gauge(ImmutableList.of(DUMMY_TASK_NAME, DUMMY_TABLE_NAME, TASKS[1], "1", LAST_RUN_DURATION_MS))).isGreaterThan(time);
        assertThat(MetricsReporterFactoryForTests.gauge(ImmutableList.of(DUMMY_TASK_NAME, DUMMY_TABLE_NAME, TASKS[2], "2", LAST_RUN_DURATION_MS))).isZero();
    } finally {
        closeJobClient(jobClient);
    }
}

/**
 * The test checks if the recovery watermark is only removed if the watermark has arrived from
 * both upstream sources.
 *
 * @throws Exception if any
 */
@Test
void testRecovery() throws Exception {
    StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
    ManualSource<TaskResult> source1 = new ManualSource<>(env, TypeInformation.of(TaskResult.class));
    ManualSource<TaskResult> source2 = new ManualSource<>(env, TypeInformation.of(TaskResult.class));
    source1.dataStream().union(source2.dataStream()).transform(DUMMY_TASK_NAME, TypeInformation.of(Void.class), new LockRemover(DUMMY_TABLE_NAME, new TestingLockFactory(), Lists.newArrayList(TASKS[0]))).setParallelism(1);
    JobClient jobClient = null;
    try {
        jobClient = env.executeAsync();
        RECOVERY_LOCK.tryLock();
        assertThat(RECOVERY_LOCK.isHeld()).isTrue();
        processAndCheck(source1, new TaskResult(0, 0L, true, Lists.newArrayList()));
        source1.sendRecord(new TaskResult(0, 1L, true, Lists.newArrayList()));
        // we receive the second result - this will not happen in real use cases, but with this we can
        // be sure that the previous watermark is processed
        Awaitility.await().until(() -> MetricsReporterFactoryForTests.counter(ImmutableList.of(DUMMY_TASK_NAME, DUMMY_TABLE_NAME, TASKS[0], "0", SUCCEEDED_TASK_COUNTER)).equals(2L));
        // We did not remove the recovery lock, as no watermark received from the other source
        assertThat(RECOVERY_LOCK.isHeld()).isTrue();
        // Recovery arrives
        source1.sendWatermark(10L);
        source2.sendWatermark(10L);
        Awaitility.await().until(() -> !RECOVERY_LOCK.isHeld());
    } finally {
        closeJobClient(jobClient);
    }
}

