@Test
void testTableBranchAtomicCommitWithFailures() throws Exception {
    Table table = catalog.loadTable(TableIdentifier.of(TABLE1));
    assertThat(table.snapshots()).isEmpty();
    DynamicWriteResultAggregator aggregator = new DynamicWriteResultAggregator(CATALOG_EXTENSION.catalogLoader());
    OneInputStreamOperatorTestHarness aggregatorHarness = new OneInputStreamOperatorTestHarness(aggregator);
    aggregatorHarness.open();
    WriteTarget writeTarget1 = new WriteTarget(TABLE1, "branch", 42, 0, false, Sets.newHashSet());
    // writeTarget2 has a different schema
    WriteTarget writeTarget2 = new WriteTarget(TABLE1, "branch", 23, 0, false, Sets.newHashSet());
    WriteTarget writeTarget3 = new WriteTarget(TABLE1, "branch", 23, 0, false, Sets.newHashSet());
    WriteResult writeResult1 = WriteResult.builder().addDataFiles(DATA_FILE).build();
    WriteResult writeResult2 = WriteResult.builder().addDeleteFiles(DELETE_FILE).build();
    WriteResult writeResult3 = WriteResult.builder().addDataFiles(DATA_FILE).build();
    final String jobId = JobID.generate().toHexString();
    final String operatorId = new OperatorID().toHexString();
    final int checkpointId1 = 1;
    final int checkpointId2 = 2;
    byte[] deltaManifest1 = aggregator.writeToManifest(writeTarget1, Sets.newHashSet(new DynamicWriteResult(writeTarget1, writeResult1)), checkpointId1);
    CommitRequest<DynamicCommittable> commitRequest1 = new MockCommitRequest<>(new DynamicCommittable(writeTarget1, deltaManifest1, jobId, operatorId, checkpointId1));
    byte[] deltaManifest2 = aggregator.writeToManifest(writeTarget2, Sets.newHashSet(new DynamicWriteResult(writeTarget2, writeResult2)), checkpointId2);
    CommitRequest<DynamicCommittable> commitRequest2 = new MockCommitRequest<>(new DynamicCommittable(writeTarget2, deltaManifest2, jobId, operatorId, checkpointId2));
    byte[] deltaManifest3 = aggregator.writeToManifest(writeTarget3, Sets.newHashSet(new DynamicWriteResult(writeTarget3, writeResult3)), checkpointId2);
    CommitRequest<DynamicCommittable> commitRequest3 = new MockCommitRequest<>(new DynamicCommittable(writeTarget3, deltaManifest3, jobId, operatorId, checkpointId2));
    boolean overwriteMode = false;
    int workerPoolSize = 1;
    String sinkId = "sinkId";
    UnregisteredMetricsGroup metricGroup = new UnregisteredMetricsGroup();
    DynamicCommitterMetrics committerMetrics = new DynamicCommitterMetrics(metricGroup);
    // Use special hook to fail during various states of the commit operation
    CommitHook commitHook = new FailBeforeAndAfterCommit();
    DynamicCommitter dynamicCommitter = new CommitHookEnabledDynamicCommitter(commitHook, CATALOG_EXTENSION.catalog(), Maps.newHashMap(), overwriteMode, workerPoolSize, sinkId, committerMetrics);
    ThrowingCallable commitExecutable = () -> dynamicCommitter.commit(Sets.newHashSet(commitRequest1, commitRequest2, commitRequest3));
    // First fail pre-commit
    assertThatThrownBy(commitExecutable);
    assertThat(FailBeforeAndAfterCommit.failedBeforeCommit).isTrue();
    // Second fail during commit
    assertThatThrownBy(commitExecutable);
    assertThat(FailBeforeAndAfterCommit.failedDuringCommit).isTrue();
    // Third fail after commit
    assertThatThrownBy(commitExecutable);
    assertThat(FailBeforeAndAfterCommit.failedAfterCommit).isTrue();
    // Finally commit must go through, although it is a NOOP because the third failure is directly
    // after the commit finished.
    try {
        commitExecutable.call();
    } catch (Throwable e) {
        fail("Should not have thrown an exception");
    }
    table.refresh();
    // Three committables, but only two snapshots! WriteResults from different checkpoints are not
    // getting
    // combined due to one writeResult2 containing a delete file.
    assertThat(table.snapshots()).hasSize(2);
    Snapshot snapshot1 = Iterables.getFirst(table.snapshots(), null);
    assertThat(snapshot1.summary()).containsAllEntriesOf(ImmutableMap.<String, String>builder().put("added-data-files", "1").put("added-records", "42").put("changed-partition-count", "1").put("flink.job-id", jobId).put("flink.max-committed-checkpoint-id", "" + checkpointId1).put("flink.operator-id", operatorId).put("total-data-files", "1").put("total-delete-files", "0").put("total-equality-deletes", "0").put("total-files-size", "0").put("total-position-deletes", "0").put("total-records", "42").build());
    Snapshot snapshot2 = Iterables.get(table.snapshots(), 1);
    assertThat(snapshot2.summary()).containsAllEntriesOf(ImmutableMap.<String, String>builder().put("added-data-files", "1").put("added-records", "42").put("changed-partition-count", "1").put("flink.job-id", jobId).put("flink.max-committed-checkpoint-id", "" + checkpointId2).put("flink.operator-id", operatorId).put("total-data-files", "2").put("total-delete-files", "1").put("total-equality-deletes", "0").put("total-files-size", "0").put("total-position-deletes", "24").put("total-records", "84").build());
}

