@Test
public void testDurationConf() {
    Map<String, String> writeOptions = ImmutableMap.of("write-prop", "111s");
    ConfigOption<Duration> configOption = ConfigOptions.key("conf-prop").durationType().noDefaultValue();
    Configuration flinkConf = new Configuration();
    flinkConf.setString(configOption.key(), "222s");
    Table table = mock(Table.class);
    when(table.properties()).thenReturn(ImmutableMap.of("table-prop", "333s"));
    FlinkConfParser confParser = new FlinkConfParser(table, writeOptions, flinkConf);
    Duration defaultVal = Duration.ofMillis(999);
    Duration result = confParser.durationConf().option("write-prop").defaultValue(defaultVal).parse();
    assertThat(result).isEqualTo(Duration.ofSeconds(111));
    result = confParser.durationConf().flinkConfig(configOption).defaultValue(defaultVal).parse();
    assertThat(result).isEqualTo(Duration.ofSeconds(222));
    result = confParser.durationConf().tableProperty("table-prop").defaultValue(defaultVal).parse();
    assertThat(result).isEqualTo(Duration.ofSeconds(333));
}

@Test
public void testFlinkDataTypeEqual() {
    matchLiteral("field1", 1, 1);
    matchLiteral("field2", 10L, 10L);
    matchLiteral("field3", 1.2F, 1.2F);
    matchLiteral("field4", 3.4D, 3.4D);
    matchLiteral("field5", "abcd", "abcd");
    matchLiteral("field6", true, true);
    matchLiteral("field7", new byte[] { 'a', 'b' }, ByteBuffer.wrap(new byte[] { 'a', 'b' }));
    matchLiteral("field8", BigDecimal.valueOf(10.12), BigDecimal.valueOf(10.12));
    LocalDate date = LocalDate.parse("2020-12-23");
    matchLiteral("field9", date, DateTimeUtil.daysFromDate(date));
    LocalTime time = LocalTime.parse("12:13:14");
    matchLiteral("field10", time, DateTimeUtil.microsFromTime(time));
    LocalDateTime dateTime = LocalDateTime.parse("2020-12-23T12:13:14");
    matchLiteral("field11", dateTime, DateTimeUtil.microsFromTimestamp(dateTime));
    Instant instant = Instant.parse("2020-12-23T12:13:14.00Z");
    matchLiteral("field12", instant, DateTimeUtil.microsFromInstant(instant));
}

