@Test
public void tokenWithExpiration() {
    HttpRequest mockRequest = HttpRequest.request("/v1/credentials").withMethod(HttpMethod.GET.name());
    Credential credential = ImmutableCredential.builder().prefix("gs").config(ImmutableMap.of(GCPProperties.GCS_OAUTH2_TOKEN, "gcsToken", GCPProperties.GCS_OAUTH2_TOKEN_EXPIRES_AT, Long.toString(Instant.now().plus(5, ChronoUnit.MINUTES).toEpochMilli()))).build();
    HttpResponse mockResponse = HttpResponse.response(LoadCredentialsResponseParser.toJson(ImmutableLoadCredentialsResponse.builder().addCredentials(credential).build())).withStatusCode(200);
    mockServer.when(mockRequest).respond(mockResponse);
    OAuth2RefreshCredentialsHandler handler = OAuth2RefreshCredentialsHandler.create(PROPERTIES);
    AccessToken accessToken = handler.refreshAccessToken();
    assertThat(accessToken.getTokenValue()).isEqualTo(credential.config().get(GCPProperties.GCS_OAUTH2_TOKEN));
    assertThat(accessToken.getExpirationTime().toInstant().toEpochMilli()).isEqualTo(Long.parseLong(credential.config().get(GCPProperties.GCS_OAUTH2_TOKEN_EXPIRES_AT)));
    // refresh always fetches a new token
    AccessToken refreshedToken = handler.refreshAccessToken();
    assertThat(refreshedToken).isNotSameAs(accessToken);
    mockServer.verify(mockRequest, VerificationTimes.exactly(2));
}

