    CachedClientPool clientPool = new CachedClientPool(HIVE_METASTORE_EXTENSION.hiveConf(), ImmutableMap.of(CatalogProperties.CLIENT_POOL_CACHE_EVICTION_INTERVAL_MS, String.valueOf(EVICTION_INTERVAL)));
