    verify(coordinator, timeout(1000)).start();
    verify(coordinator, timeout(1000).atLeast(1)).process();
    verify(coordinator, times(0)).stop();
    assertThat(coordinatorThread.isTerminated()).isFalse();
    coordinatorThread.terminate();
    verify(coordinator, timeout(1000)).stop();
    assertThat(coordinatorThread.isTerminated()).isTrue();
}

@Test
public void testSave() {
    when(config.catalogName()).thenReturn("catalog");
    try (MockedStatic<KafkaUtils> mockKafkaUtils = mockStatic(KafkaUtils.class)) {
        ConsumerGroupMetadata consumerGroupMetadata = mock(ConsumerGroupMetadata.class);
        mockKafkaUtils.when(() -> KafkaUtils.consumerGroupMetadata(any())).thenReturn(consumerGroupMetadata);
        SinkTaskContext context = mock(SinkTaskContext.class);
        TopicPartition topicPartition = new TopicPartition(SRC_TOPIC_NAME, 0);
        when(context.assignment()).thenReturn(ImmutableSet.of(topicPartition));
        IcebergWriterResult writeResult = new IcebergWriterResult(TableIdentifier.parse(TABLE_NAME), ImmutableList.of(EventTestUtil.createDataFile()), ImmutableList.of(), StructType.of());
        Map<TopicPartition, Offset> offsets = ImmutableMap.of(topicPartition, new Offset(1L, EventTestUtil.now()));
        SinkWriterResult sinkWriterResult = new SinkWriterResult(ImmutableList.of(writeResult), offsets);
        SinkWriter sinkWriter = mock(SinkWriter.class);
        when(sinkWriter.completeWrite()).thenReturn(sinkWriterResult);
        Worker worker = new Worker(config, clientFactory, sinkWriter, context);
        worker.start();
        // init consumer after subscribe()
        initConsumer();
        // save a record
        Map<String, Object> value = ImmutableMap.of();
        SinkRecord rec = new SinkRecord(SRC_TOPIC_NAME, 0, null, "key", null, value, 0L);
        worker.save(ImmutableList.of(rec));
        UUID commitId = UUID.randomUUID();
        Event commitRequest = new Event(config.connectGroupId(), new StartCommit(commitId));
        byte[] bytes = AvroUtil.encode(commitRequest);
        consumer.addRecord(new ConsumerRecord<>(CTL_TOPIC_NAME, 0, 1, "key", bytes));
        worker.process();
        assertThat(producer.history()).hasSize(2);
        Event event = AvroUtil.decode(producer.history().get(0).value());
        assertThat(event.payload().type()).isEqualTo(PayloadType.DATA_WRITTEN);
        DataWritten dataWritten = (DataWritten) event.payload();
        assertThat(dataWritten.commitId()).isEqualTo(commitId);
        event = AvroUtil.decode(producer.history().get(1).value());
        assertThat(event.type()).isEqualTo(PayloadType.DATA_COMPLETE);
        DataComplete dataComplete = (DataComplete) event.payload();
        assertThat(dataComplete.commitId()).isEqualTo(commitId);
        assertThat(dataComplete.assignments()).hasSize(1);
        assertThat(dataComplete.assignments().get(0).offset()).isEqualTo(1L);
    }
}

@ParameterizedTest
@ValueSource(booleans = { true, false })
@SuppressWarnings("unchecked")
public void testAutoCreateTable(boolean partitioned) {
    Catalog catalog = mock(Catalog.class, withSettings().extraInterfaces(SupportsNamespaces.class));
    when(catalog.loadTable(any())).thenThrow(new NoSuchTableException("no such table"));
    TableSinkConfig tableConfig = mock(TableSinkConfig.class);
    if (partitioned) {
        when(tableConfig.partitionBy()).thenReturn(ImmutableList.of("data"));
    }
    IcebergSinkConfig config = mock(IcebergSinkConfig.class);
    when(config.autoCreateProps()).thenReturn(ImmutableMap.of("test-prop", "foo1"));
    when(config.tableConfig(any())).thenReturn(tableConfig);
    SinkRecord record = mock(SinkRecord.class);
    when(record.value()).thenReturn(ImmutableMap.of("id", 123, "data", "foo2"));
    IcebergWriterFactory factory = new IcebergWriterFactory(catalog, config);
    factory.autoCreateTable("foo1.foo2.foo3.bar", record);
    ArgumentCaptor<TableIdentifier> identCaptor = ArgumentCaptor.forClass(TableIdentifier.class);
    ArgumentCaptor<Schema> schemaCaptor = ArgumentCaptor.forClass(Schema.class);
    ArgumentCaptor<PartitionSpec> specCaptor = ArgumentCaptor.forClass(PartitionSpec.class);
    ArgumentCaptor<Map<String, String>> propsCaptor = ArgumentCaptor.forClass(Map.class);
    verify(catalog).createTable(identCaptor.capture(), schemaCaptor.capture(), specCaptor.capture(), propsCaptor.capture());
    assertThat(identCaptor.getValue()).isEqualTo(TableIdentifier.of(Namespace.of("foo1", "foo2", "foo3"), "bar"));
    assertThat(schemaCaptor.getValue().findField("id").type()).isEqualTo(LongType.get());
    assertThat(schemaCaptor.getValue().findField("data").type()).isEqualTo(StringType.get());
    assertThat(specCaptor.getValue().isPartitioned()).isEqualTo(partitioned);
    assertThat(propsCaptor.getValue()).containsKey("test-prop");
    ArgumentCaptor<Namespace> namespaceCaptor = ArgumentCaptor.forClass(Namespace.class);
    verify((SupportsNamespaces) catalog, times(3)).createNamespace(namespaceCaptor.capture());
    List<Namespace> capturedArguments = namespaceCaptor.getAllValues();
    assertThat(capturedArguments.get(0)).isEqualTo(Namespace.of("foo1"));
    assertThat(capturedArguments.get(1)).isEqualTo(Namespace.of("foo1", "foo2"));
    assertThat(capturedArguments.get(2)).isEqualTo(Namespace.of("foo1", "foo2", "foo3"));
}

