@Test
public void testListNamespaces() throws NessieConflictException, NessieNotFoundException {
    assertThat(catalog.listNamespaces()).isEmpty();
    assertThat(anotherCatalog.listNamespaces()).isEmpty();
    // listing a non-existent namespace should throw an NoSuchNamespaceExists exception
    Namespace namespaceDb1 = Namespace.of("db1");
    assertThatThrownBy(() -> catalog.listNamespaces(namespaceDb1)).isInstanceOf(NoSuchNamespaceException.class).hasMessage("Namespace does not exist: %s", namespaceDb1);
    assertThatThrownBy(() -> anotherCatalog.listNamespaces(namespaceDb1)).isInstanceOf(NoSuchNamespaceException.class).hasMessage("Namespace does not exist: %s", namespaceDb1);
    catalog.createNamespace(Namespace.of("db1"), Collections.emptyMap());
    assertThat(catalog.listNamespaces()).containsExactlyInAnyOrder(Namespace.of("db1"));
    assertThat(anotherCatalog.listNamespaces()).containsExactlyInAnyOrder(Namespace.of("db1"));
    // another client creates a namespace with the same nessie server
    anotherCatalog.createNamespace(Namespace.of("db2"), Collections.emptyMap());
    assertThat(catalog.listNamespaces()).containsExactlyInAnyOrder(Namespace.of("db1"), Namespace.of("db2"));
    assertThat(anotherCatalog.listNamespaces()).containsExactlyInAnyOrder(Namespace.of("db1"), Namespace.of("db2"));
    api.deleteBranch().branch((Branch) api.getReference().refName(branch).get()).delete();
    assertThatThrownBy(() -> catalog.listNamespaces()).isInstanceOf(NoSuchNamespaceException.class).hasMessageContaining("Cannot list top-level namespaces: ref '%s' is no longer valid", branch);
    assertThatThrownBy(() -> anotherCatalog.listNamespaces(Namespace.of("db1"))).isInstanceOf(NoSuchNamespaceException.class).hasMessageContaining("Cannot list child namespaces from 'db1': ref '%s' is no longer valid", branch);
}

@Test
public void testLoadNamespaceMetadata() throws NessieConflictException, NessieNotFoundException {
    assertThatThrownBy(() -> catalog.loadNamespaceMetadata(Namespace.of("namespace1"))).isInstanceOf(NoSuchNamespaceException.class).hasMessageContaining("Namespace does not exist: namespace1");
    assertThatThrownBy(() -> anotherCatalog.loadNamespaceMetadata(Namespace.of("namespace1"))).isInstanceOf(NoSuchNamespaceException.class).hasMessageContaining("Namespace does not exist: namespace1");
    catalog.createNamespace(Namespace.of("namespace1"), Collections.emptyMap());
    // both clients should see the namespace because we read the HEAD of the ref
    assertThat(catalog.listNamespaces()).containsExactlyInAnyOrder(Namespace.of("namespace1"));
    assertThat(anotherCatalog.listNamespaces()).containsExactlyInAnyOrder(Namespace.of("namespace1"));
    // the other client should not be able to update the namespace
    // because it is still on the old ref hash
    assertThatThrownBy(() -> anotherCatalog.setProperties(Namespace.of("namespace1"), Collections.singletonMap("k1", "v1"))).isInstanceOf(NoSuchNamespaceException.class).hasMessageContaining("Namespace does not exist: namespace1");
    // the same client adds a metadata to the namespace: expect success
    catalog.setProperties(Namespace.of("namespace1"), Collections.singletonMap("k1", "v1"));
    // load metadata from the same client and another client both should work fine
    // because we read the HEAD of the ref
    assertThat(anotherCatalog.loadNamespaceMetadata(Namespace.of("namespace1"))).containsExactly(Map.entry("k1", "v1"));
    assertThat(catalog.loadNamespaceMetadata(Namespace.of("namespace1"))).containsExactly(Map.entry("k1", "v1"));
    api.deleteBranch().branch((Branch) api.getReference().refName(branch).get()).delete();
    assertThatThrownBy(() -> catalog.loadNamespaceMetadata(Namespace.of("namespace1"))).isInstanceOf(RuntimeException.class).hasMessageContaining("Cannot load namespace 'namespace1': ref '%s' is no longer valid", branch);
    assertThatThrownBy(() -> anotherCatalog.loadNamespaceMetadata(Namespace.of("namespace1"))).isInstanceOf(RuntimeException.class).hasMessageContaining("Cannot load namespace 'namespace1': ref '%s' is no longer valid", branch);
}

