    NessieCatalog newCatalog = new NessieCatalog();
    newCatalog.setConf(hadoopConfig);
    ImmutableMap.Builder<String, String> options = ImmutableMap.<String, String>builder().put(CatalogProperties.URI, uri).put(CatalogProperties.WAREHOUSE_LOCATION, temp.toUri().toString()).put("client-api-version", version);
