/**
 * Verify that Nessie always returns the globally-current global-content w/ only DMLs.
 */
@Test
public void verifyStateMovesForDML() throws Exception {
    //  1. initialize table
    Table icebergTable = catalog.loadTable(TABLE_IDENTIFIER);
    icebergTable.updateSchema().addColumn("initial_column", Types.LongType.get()).commit();
    //  2. create 2nd branch
    String testCaseBranch = "verify-global-moving";
    api.createReference().sourceRefName(BRANCH).reference(Branch.of(testCaseBranch, catalog.currentHash())).create();
    try (NessieCatalog ignore = initCatalog(testCaseBranch)) {
        IcebergTable contentInitialMain = getTable(BRANCH, KEY);
        IcebergTable contentInitialBranch = getTable(testCaseBranch, KEY);
        Table tableInitialMain = catalog.loadTable(TABLE_IDENTIFIER);
        // verify table-metadata-location + snapshot-id
        assertThat(contentInitialMain).as("global-contents + snapshot-id equal on both branches in Nessie").isEqualTo(contentInitialBranch);
        assertThat(tableInitialMain.currentSnapshot()).isNull();
        //  3. modify table in "main" branch (add some data)
        DataFile file1 = makeDataFile(icebergTable, addRecordsToFile(icebergTable, "file1"));
        icebergTable.newAppend().appendFile(file1).commit();
        IcebergTable contentsAfter1Main = getTable(KEY);
        IcebergTable contentsAfter1Branch = getTable(testCaseBranch, KEY);
        Table tableAfter1Main = catalog.loadTable(TABLE_IDENTIFIER);
        //  --> assert getValue() against both branches returns the updated metadata-location
        // verify table-metadata-location
        assertThat(contentInitialMain.getMetadataLocation()).describedAs("metadata-location must change on %s", BRANCH).isNotEqualTo(contentsAfter1Main.getMetadataLocation());
        assertThat(contentInitialBranch.getMetadataLocation()).describedAs("metadata-location must not change on %s", testCaseBranch).isEqualTo(contentsAfter1Branch.getMetadataLocation());
        assertThat(contentsAfter1Main).extracting(IcebergTable::getSchemaId).describedAs("on-reference-state must not be equal on both branches").isEqualTo(contentsAfter1Branch.getSchemaId());
        // verify manifests
        assertThat(tableAfter1Main.currentSnapshot().allManifests(tableAfter1Main.io())).describedAs("verify number of manifests on 'main'").hasSize(1);
        //  4. modify table in "main" branch (add some data) again
        DataFile file2 = makeDataFile(icebergTable, addRecordsToFile(icebergTable, "file2"));
        icebergTable.newAppend().appendFile(file2).commit();
        IcebergTable contentsAfter2Main = getTable(KEY);
        IcebergTable contentsAfter2Branch = getTable(testCaseBranch, KEY);
        Table tableAfter2Main = catalog.loadTable(TABLE_IDENTIFIER);
        //  --> assert getValue() against both branches returns the updated metadata-location
        // verify table-metadata-location
        assertThat(contentsAfter2Main.getMetadataLocation()).describedAs("metadata-location must change on %s", BRANCH).isNotEqualTo(contentsAfter1Main.getMetadataLocation());
        assertThat(contentsAfter2Branch.getMetadataLocation()).describedAs("on-reference-state must not change on %s", testCaseBranch).isEqualTo(contentsAfter1Branch.getMetadataLocation());
        // verify manifests
        assertThat(tableAfter2Main.currentSnapshot().allManifests(tableAfter2Main.io())).describedAs("verify number of manifests on 'main'").hasSize(2);
    }
}

