@Test
public void testRegisterTableFailureScenarios() throws NessieConflictException, NessieNotFoundException {
    List<String> metadataVersionFiles = metadataVersionFiles(tableLocation);
    assertThat(1).isEqualTo(metadataVersionFiles.size());
    // Case 1: Branch does not exist
    ImmutableTableReference defaultTableReference = ImmutableTableReference.builder().reference("default").name(TABLE_NAME).build();
    TableIdentifier defaultIdentifier = TableIdentifier.of(DB_NAME, defaultTableReference.toString());
    assertThatThrownBy(() -> catalog.registerTable(defaultIdentifier, "file:" + metadataVersionFiles.get(0))).isInstanceOf(IllegalArgumentException.class).hasMessage("Nessie ref 'default' does not exist");
    // Case 2: Table Already Exists
    assertThatThrownBy(() -> catalog.registerTable(TABLE_IDENTIFIER, "file:" + metadataVersionFiles.get(0))).isInstanceOf(AlreadyExistsException.class).hasMessage("Table already exists: db.tbl");
    // Case 3: Registering using a tag
    ImmutableTableReference branchTableReference = ImmutableTableReference.builder().reference(BRANCH).name(TABLE_NAME).build();
    TableIdentifier branchIdentifier = TableIdentifier.of(DB_NAME, branchTableReference.toString());
    assertThat(catalog.dropTable(branchIdentifier, false)).isTrue();
    String hash = api.getReference().refName(BRANCH).get().getHash();
    api.createReference().sourceRefName(BRANCH).reference(Tag.of("tag_1", hash)).create();
    ImmutableTableReference tagTableReference = ImmutableTableReference.builder().reference("tag_1").name(TABLE_NAME).build();
    TableIdentifier tagIdentifier = TableIdentifier.of(DB_NAME, tagTableReference.toString());
    assertThatThrownBy(() -> catalog.registerTable(tagIdentifier, "file:" + metadataVersionFiles.get(0))).isInstanceOf(IllegalArgumentException.class).hasMessage("You can only mutate tables/views when using a branch without a hash or timestamp.");
    // Case 4: non-null metadata path with null metadata location
    assertThatThrownBy(() -> catalog.registerTable(TABLE_IDENTIFIER, "file:" + metadataVersionFiles.get(0) + "invalidName")).isInstanceOf(NotFoundException.class).hasMessageContaining("Failed to open input stream for file");
    // Case 5: null identifier
    assertThatThrownBy(() -> catalog.registerTable(null, "file:" + metadataVersionFiles.get(0) + "invalidName")).isInstanceOf(IllegalArgumentException.class).hasMessage("Invalid identifier: null");
}

