@ParameterizedTest
@FieldSource("PRIMITIVES")
public void testShreddedPrimitiveTypes(VariantValue value) throws IOException {
    Metrics metrics = writeParquet((id, name) -> ParquetVariantUtil.toParquetSchema(value), Variant.of(EMPTY, value), Variant.of(EMPTY, Variants.ofNull()), null);
    assertThat(metrics.valueCounts()).isEqualTo(Map.of(1, 3L, 2, 3L));
    assertThat(metrics.nullValueCounts()).isEqualTo(Map.of(1, 0L, 2, 1L));
    assertThat(metrics.nanValueCounts()).isEqualTo(Map.of());
    assertThat(metrics.lowerBounds()).hasSize(2);
    assertThat(metrics.lowerBounds().get(1)).extracting(bytes -> Conversions.fromByteBuffer(Types.LongType.get(), bytes)).isEqualTo(0L);
    assertThat(metrics.lowerBounds().get(2)).extracting(bytes -> {
        VariantObject bounds = Variant.from(bytes).value().asObject();
        return bounds.get(ROOT_FIELD);
    }).isEqualTo(value);
    assertThat(metrics.upperBounds()).hasSize(2);
    assertThat(metrics.upperBounds().get(1)).extracting(bytes -> Conversions.fromByteBuffer(Types.LongType.get(), bytes)).isEqualTo(2L);
    assertThat(metrics.upperBounds().get(2)).extracting(bytes -> {
        VariantObject bounds = Variant.from(bytes).value().asObject();
        return bounds.get(ROOT_FIELD);
    }).isEqualTo(value);
    assertThat(metrics).extracting("originalTypes").isEqualTo(Map.of(1, Types.LongType.get(), 2, Types.VariantType.get()));
}

