@Test
public void testShreddedObject() throws IOException {
    VariantValue date = Variants.ofIsoDate("2025-03-17");
    VariantValue num = Variants.of(34);
    VariantValue str = Variants.of("iceberg");
    VariantValue dec = Variants.of(new BigDecimal("123456.789"));
    ShreddedObject inner = Variants.object(METADATA);
    inner.put("e", dec);
    ShreddedObject object = Variants.object(METADATA);
    object.put("a", date);
    object.put("b", num);
    object.put("c", str);
    object.put("d", inner);
    Metrics metrics = writeParquet((id, name) -> ParquetVariantUtil.toParquetSchema(object), Variant.of(EMPTY, num), Variant.of(EMPTY, Variants.object(EMPTY)), Variant.of(METADATA, object), Variant.of(EMPTY, Variants.ofNull()), null);
    assertThat(metrics.valueCounts()).isEqualTo(Map.of(1, 5L, 2, 5L));
    assertThat(metrics.nullValueCounts()).isEqualTo(Map.of(1, 0L, 2, 1L));
    assertThat(metrics.nanValueCounts()).isEqualTo(Map.of());
    VariantMetadata boundMetadata = Variants.metadata("$['a']", "$['b']", "$['c']", "$['d']['e']");
    ShreddedObject expectedBounds = Variants.object(boundMetadata);
    expectedBounds.put("$['a']", date);
    expectedBounds.put("$['b']", num);
    expectedBounds.put("$['c']", str);
    expectedBounds.put("$['d']['e']", dec);
    assertThat(metrics.lowerBounds()).hasSize(2);
    assertThat(metrics.lowerBounds().get(1)).extracting(bytes -> Conversions.fromByteBuffer(Types.LongType.get(), bytes)).isEqualTo(0L);
    assertThat(metrics.lowerBounds().get(2)).extracting(bytes -> Variant.from(bytes).value()).isEqualTo(expectedBounds);
    assertThat(metrics.upperBounds()).hasSize(2);
    assertThat(metrics.upperBounds().get(1)).extracting(bytes -> Conversions.fromByteBuffer(Types.LongType.get(), bytes)).isEqualTo(4L);
    assertThat(metrics.upperBounds().get(2)).extracting(bytes -> Variant.from(bytes).value()).isEqualTo(expectedBounds);
    assertThat(metrics).extracting("originalTypes").isEqualTo(Map.of(1, Types.LongType.get(), 2, Types.VariantType.get()));
}

