@Test
public void testRewritePath() throws Exception {
    String targetTableLocation = targetTableLocation();
    // check the data file location before the rebuild
    List<String> validDataFiles = spark.read().format("iceberg").load(tableLocation + "#files").select("file_path").as(Encoders.STRING()).collectAsList();
    assertThat(validDataFiles).hasSize(2);
    RewriteTablePath.Result result = actions().rewriteTablePath(table).rewriteLocationPrefix(tableLocation, targetTableLocation).endVersion("v3.metadata.json").execute();
    assertThat(result.latestVersion()).isEqualTo("v3.metadata.json");
    checkFileNum(3, 2, 2, 9, result);
    // copy the metadata files and data files
    copyTableFiles(result);
    // verify the data file path after the rebuild
    List<String> validDataFilesAfterRebuilt = spark.read().format("iceberg").load(targetTableLocation + "#files").select("file_path").as(Encoders.STRING()).collectAsList();
    assertThat(validDataFilesAfterRebuilt).hasSize(2).allMatch(item -> item.startsWith(targetTableLocation));
    // verify data rows
    List<Object[]> actual = rows(targetTableLocation);
    List<Object[]> expected = rows(tableLocation);
    assertEquals("Rows should match after copy", expected, actual);
}

