@Test
public void testManifestRewriteAndIncrementalCopy() throws Exception {
    RewriteTablePath.Result initialResult = actions().rewriteTablePath(table).rewriteLocationPrefix(table.location(), targetTableLocation()).stagingLocation(stagingLocation()).execute();
    checkFileNum(3, 2, 2, 9, initialResult);
    // rewrite manifest without change data files
