    assertDataFilePartitions(dataFiles, Arrays.asList(1, 2, 2));
    List<GenericData.Record> expected = Lists.newArrayList();
    expected.add(builder.set("partition", partitionBuilder.set("id", 1).build()).set("record_count", 1L).set("file_count", 1).set("total_data_file_size_in_bytes", dataFiles.get(0).fileSizeInBytes()).set("position_delete_record_count", 0L).set("position_delete_file_count", 0).set("equality_delete_record_count", 0L).set("equality_delete_file_count", 0).set("spec_id", 0).set("last_updated_at", table.snapshot(firstCommitId).timestampMillis() * 1000).set("last_updated_snapshot_id", firstCommitId).build());
    expected.add(builder.set("partition", partitionBuilder.set("id", 2).build()).set("record_count", 2L).set("file_count", 2).set("total_data_file_size_in_bytes", dataFiles.get(1).fileSizeInBytes() + dataFiles.get(2).fileSizeInBytes()).set("position_delete_record_count", 0L).set("position_delete_file_count", 0).set("equality_delete_record_count", 0L).set("equality_delete_file_count", 0).set("spec_id", 0).set("last_updated_at", table.snapshot(secondCommitId).timestampMillis() * 1000).set("last_updated_snapshot_id", secondCommitId).build());
