    List<Row> filtered = spark.read().format("iceberg").load(loadLocation(tableIdentifier, "partitions")).filter("partition.id < 2").collectAsList();
    assertThat(filtered).as("Actual results should have one row").hasSize(1);
    TestHelpers.assertEqualsSafe(partitionsTable.schema().asStruct(), expected.get(0), filtered.get(0));
    // check for snapshot expiration
    // if snapshot with firstCommitId is expired,
    // we expect the partition of id=1 will no longer have last updated timestamp and snapshotId
    SparkActions.get().expireSnapshots(table).expireSnapshotId(firstCommitId).execute();
    GenericData.Record newPartitionRecord = builder.set("partition", partitionBuilder.set("id", 1).build()).set("record_count", 1L).set("file_count", 1).set("total_data_file_size_in_bytes", dataFiles.get(0).fileSizeInBytes()).set("position_delete_record_count", 0L).set("position_delete_file_count", 0).set("equality_delete_record_count", 0L).set("equality_delete_file_count", 0).set("spec_id", 0).set("last_updated_at", null).set("last_updated_snapshot_id", null).build();
    expected.remove(0);
    expected.add(0, newPartitionRecord);
    List<Row> actualAfterSnapshotExpiration = spark.read().format("iceberg").load(loadLocation(tableIdentifier, "partitions")).collectAsList();
    assertThat(actualAfterSnapshotExpiration).as("Actual results should have two rows").hasSize(2);
    for (int i = 0; i < 2; i += 1) {
        TestHelpers.assertEqualsSafe(partitionsTable.schema().asStruct(), expected.get(i), actualAfterSnapshotExpiration.get(i));
    }
}

