public void testEqualityDeletes() throws Exception {
    Table sourceTable = createTableWithSnapshots(newTableLocation(), 1);
    // Add more varied data
    List<ThreeColumnRecord> records = Lists.newArrayList(new ThreeColumnRecord(2, "AAAAAAAAAA", "AAAA"), new ThreeColumnRecord(3, "BBBBBBBBBB", "BBBB"), new ThreeColumnRecord(4, "CCCCCCCCCC", "CCCC"), new ThreeColumnRecord(5, "DDDDDDDDDD", "DDDD"));
    spark.createDataFrame(records, ThreeColumnRecord.class).coalesce(1).select("c1", "c2", "c3").write().format("iceberg").mode("append").save(newTableLocation());
    Schema deleteRowSchema = sourceTable.schema().select("c2");
    Record dataDelete = GenericRecord.create(deleteRowSchema);
    List<Record> dataDeletes = Lists.newArrayList(dataDelete.copy("c2", "AAAAAAAAAA"), dataDelete.copy("c2", "CCCCCCCCCC"));
    File file = new File(removePrefix(sourceTable.location()) + "/data/deeply/nested/file.parquet");
    DeleteFile equalityDeletes = FileHelpers.writeDeleteFile(sourceTable, sourceTable.io().newOutputFile(file.toURI().toString()), TestHelpers.Row.of(0), dataDeletes, deleteRowSchema);
    sourceTable.newRowDelta().addDeletes(equalityDeletes).commit();
    RewriteTablePath.Result result = actions().rewriteTablePath(sourceTable).stagingLocation(stagingLocation()).rewriteLocationPrefix(newTableLocation(), targetTableLocation()).execute();
    // We have four metadata files: for the table creation, for the initial snapshot, for the
    // second append here, and for commit with equality deletes. Thus, we have three manifest lists.
    // We have a data file for each snapshot (two with data, one with equality deletes)
    checkFileNum(4, 3, 3, 13, result);
    // copy the metadata files and data files
    copyTableFiles(result);
    // Equality deletes affect three rows, so just two rows must remain
    assertThat(spark.read().format("iceberg").load(targetTableLocation()).collectAsList()).hasSize(2);
}

@Test
public void testFullTableRewritePathWithDeletedVersionFiles() throws Exception {
    String location = newTableLocation();
    Table sourceTable = createTableWithSnapshots(location, 2);
