    int expiredManifestListCount = 1;
    ExpireSnapshots.Result expireResult = actions().expireSnapshots(sourceTable).expireSnapshotId(staticTable.currentSnapshot().snapshotId()).execute();
    assertThat(expireResult.deletedManifestListsCount()).isEqualTo(expiredManifestListCount);
