    assertNoLeak("testDecimalNotAllPagesDictionaryEncoded", allocator -> {
        Parquet.ReadBuilder readBuilder = Parquet.read(Files.localInput(path.toFile())).project(schema).createBatchedReaderFunc(type -> VectorizedSparkParquetReaders.buildReader(schema, type, ImmutableMap.of(), null, allocator));
        try (CloseableIterable<ColumnarBatch> batchReader = readBuilder.build()) {
            Iterator<Row> expectedIter = expected.iterator();
            Iterator<ColumnarBatch> batches = batchReader.iterator();
            int numRowsRead = 0;
