    // sleep for 1 second to ensure files will be old enough
    Thread.sleep(1000);
    SparkActions actions = SparkActions.get();
    DeleteOrphanFiles.Result result1 = actions.deleteOrphanFiles(table).location(table.location() + "/metadata").olderThan(System.currentTimeMillis()).execute();
    assertThat(result1.orphanFileLocations()).as("Should not delete any metadata files").isEmpty();
