@Test
public void testUpdatedRowsWithDuplication() {
    List<Row> rowsWithDuplication = Lists.newArrayList(// two rows with same identifier fields(id, name)
    new GenericRowWithSchema(new Object[] { 1, "a", "data", DELETE, 0, 0 }, null), new GenericRowWithSchema(new Object[] { 1, "a", "data", DELETE, 0, 0 }, null), new GenericRowWithSchema(new Object[] { 1, "a", "new_data", INSERT, 0, 0 }, null), new GenericRowWithSchema(new Object[] { 1, "a", "new_data", INSERT, 0, 0 }, null));
    Iterator<Row> iterator = ChangelogIterator.computeUpdates(rowsWithDuplication.iterator(), SCHEMA, IDENTIFIER_FIELDS);
    assertThatThrownBy(() -> Lists.newArrayList(iterator)).isInstanceOf(IllegalStateException.class).hasMessage("Cannot compute updates because there are multiple rows with the same identifier fields([id,name]). Please make sure the rows are unique.");
    // still allow extra insert rows
    rowsWithDuplication = Lists.newArrayList(new GenericRowWithSchema(new Object[] { 1, "a", "data", DELETE, 0, 0 }, null), new GenericRowWithSchema(new Object[] { 1, "a", "new_data1", INSERT, 0, 0 }, null), new GenericRowWithSchema(new Object[] { 1, "a", "new_data2", INSERT, 0, 0 }, null));
    Iterator<Row> iterator1 = ChangelogIterator.computeUpdates(rowsWithDuplication.iterator(), SCHEMA, IDENTIFIER_FIELDS);
    assertEquals("Rows should match.", Lists.newArrayList(new Object[] { 1, "a", "data", UPDATE_BEFORE, 0, 0 }, new Object[] { 1, "a", "new_data1", UPDATE_AFTER, 0, 0 }, new Object[] { 1, "a", "new_data2", INSERT, 0, 0 }), rowsToJava(Lists.newArrayList(iterator1)));
}

@Test
public void testCarryRowsRemoveWithDuplicates() {
    // assume rows are sorted by id and change type
    List<Row> rowsWithDuplication = Lists.newArrayList(// keep all delete rows for id 0 and id 1 since there is no insert row for them
