    List<ThreeColumnRecord> records = Lists.newArrayList(new ThreeColumnRecord(2, "AAAAAAAAAA", "AAAA"), new ThreeColumnRecord(3, "BBBBBBBBBB", "BBBB"), new ThreeColumnRecord(4, "CCCCCCCCCC", "CCCC"), new ThreeColumnRecord(5, "DDDDDDDDDD", "DDDD"));
    spark.createDataFrame(records, ThreeColumnRecord.class).coalesce(1).select("c1", "c2", "c3").write().format("iceberg").mode("append").save(newTableLocation());
    Schema deleteRowSchema = sourceTable.schema().select("c2");
