    RewriteTablePath.Result result = actions().rewriteTablePath(sourceTable).stagingLocation(stagingLocation()).rewriteLocationPrefix(newTableLocation(), targetTableLocation()).execute();
    // We have four metadata files: for the table creation, for the initial snapshot, for the
