    Table staticTable = newStaticTable(location + "metadata/v2.metadata.json", table.io());
    int expiredManifestListCount = 1;
    ExpireSnapshots.Result expireResult = actions().expireSnapshots(sourceTable).expireSnapshotId(staticTable.currentSnapshot().snapshotId()).execute();
    assertThat(expireResult.deletedManifestListsCount()).isEqualTo(expiredManifestListCount);
    // create 100 more snapshots
    List<ThreeColumnRecord> records = Lists.newArrayList(new ThreeColumnRecord(1, "AAAAAAAAAA", "AAAA"));
    Dataset<Row> df = spark.createDataFrame(records, ThreeColumnRecord.class).coalesce(1);
    for (int i = 0; i < 100; i++) {
        df.select("c1", "c2", "c3").write().format("iceberg").mode("append").save(location);
    }
    sourceTable.refresh();
    // each iteration generate 1 version file, 1 manifest list, 1 manifest and 1 data file
    int totalIteration = 102;
    // v1/v2/v3.metadata.json has been deleted in v104.metadata.json, and there is no way to find
    // the first snapshot
    // from the version file history
    int missingVersionFile = 1;
    // since first snapshot cannot be found, first data files will also be skipped
    int missingDataFile = 1;
    RewriteTablePath.Result result = actions().rewriteTablePath(sourceTable).stagingLocation(stagingLocation()).rewriteLocationPrefix(location, targetTableLocation()).execute();
    checkFileNum(totalIteration - missingVersionFile, totalIteration - expiredManifestListCount, totalIteration, totalIteration * 4 - missingVersionFile - expiredManifestListCount - missingDataFile, result);
}

