    Snapshot oldest = SnapshotUtil.oldestAncestor(tableWith3Snaps);
    String oldestDataFilePath = Iterables.getOnlyElement(tableWith3Snaps.snapshot(oldest.snapshotId()).addedDataFiles(tableWith3Snaps.io())).location();
    String deletedDataFilePathInTargetLocation = String.format("%sdata/%s", targetTableLocation(), fileName(oldestDataFilePath));
    // expire the oldest snapshot and remove oldest DataFile
    ExpireSnapshots.Result expireResult = actions().expireSnapshots(tableWith3Snaps).expireSnapshotId(oldest.snapshotId()).execute();
    assertThat(expireResult).as("Should deleted 1 data files in root snapshot").extracting(ExpireSnapshots.Result::deletedManifestListsCount, ExpireSnapshots.Result::deletedManifestsCount, ExpireSnapshots.Result::deletedDataFilesCount).contains(1L, 1L, 1L);
    RewriteTablePath.Result result = actions().rewriteTablePath(tableWith3Snaps).stagingLocation(stagingLocation()).rewriteLocationPrefix(tableWith3Snaps.location(), targetTableLocation()).execute();
    // 5 version files include 1 table creation 3 overwrite and 1 snapshot expiration
    // 3 overwrites generate 3 manifest list and 5 manifests with 3 data files
    // snapshot expiration removed 1 of each
    checkFileNum(5, 2, 4, 13, result);
    // copy the metadata files and data files
    copyTableFiles(result);
    // expect deleted data file is excluded from rewrite and copy
    List<String> copiedDataFiles = spark.read().format("iceberg").load(targetTableLocation() + "#all_files").select("file_path").as(Encoders.STRING()).collectAsList();
    assertThat(copiedDataFiles).hasSize(2).doesNotContain(deletedDataFilePathInTargetLocation);
    // expect manifest entries still contain deleted entry
    List<String> copiedEntries = spark.read().format("iceberg").load(targetTableLocation() + "#all_entries").filter("status == 2").select("data_file.file_path").as(Encoders.STRING()).collectAsList();
    assertThat(copiedEntries).contains(deletedDataFilePathInTargetLocation);
}

