@Test
public void testDeleteFrom() throws Exception {
    Map<String, String> properties = Maps.newHashMap();
    properties.put("format-version", "2");
    properties.put("write.delete.mode", "merge-on-read");
    String tableName = "v2tbl";
    Table sourceTable = createMetastoreTable(newTableLocation(), properties, "default", tableName, 0);
    // ingest data
    List<ThreeColumnRecord> records = Lists.newArrayList(new ThreeColumnRecord(1, "AAAAAAAAAA", "AAAA"), new ThreeColumnRecord(2, "AAAAAAAAAA", "AAAA"), new ThreeColumnRecord(3, "AAAAAAAAAA", "AAAA"));
    Dataset<Row> df = spark.createDataFrame(records, ThreeColumnRecord.class).coalesce(1);
    df.select("c1", "c2", "c3").write().format("iceberg").mode("append").saveAsTable("hive.default." + tableName);
    sourceTable.refresh();
    // generate position delete files
    spark.sql(String.format("delete from hive.default.%s where c1 = 1", tableName));
    sourceTable.refresh();
    List<Object[]> originalData = rowsToJava(spark.read().format("iceberg").load("hive.default." + tableName).sort("c1", "c2", "c3").collectAsList());
    // two rows
    assertThat(originalData).hasSize(2);
    // copy table and check the results
    RewriteTablePath.Result result = actions().rewriteTablePath(sourceTable).rewriteLocationPrefix(newTableLocation(), targetTableLocation()).execute();
    checkFileNum(3, 2, 2, 9, result);
    // one data and one metadata file
    copyTableFiles(result);
    // register table
    String metadataLocation = currentMetadata(sourceTable).metadataFileLocation();
    String versionFile = fileName(metadataLocation);
    String targetTableName = "copiedV2Table";
    TableIdentifier tableIdentifier = TableIdentifier.of("default", targetTableName);
    catalog.registerTable(tableIdentifier, targetTableLocation() + "/metadata/" + versionFile);
    List<Object[]> copiedData = rowsToJava(spark.read().format("iceberg").load("hive.default." + targetTableName).sort("c1", "c2", "c3").collectAsList());
    assertEquals("Rows must match", originalData, copiedData);
}

