@Test
public synchronized void testSnapshotReadAfterDropColumn() {
    TableIdentifier tableIdentifier = TableIdentifier.of("db", "table");
    Table table = createTable(tableIdentifier, SCHEMA2, PartitionSpec.unpartitioned());
    List<Row> originalRecords = Lists.newArrayList(RowFactory.create(1, "x", "A"), RowFactory.create(2, "y", "A"), RowFactory.create(3, "z", "B"));
    StructType originalSparkSchema = SparkSchemaUtil.convert(SCHEMA2);
    Dataset<Row> inputDf = spark.createDataFrame(originalRecords, originalSparkSchema);
    inputDf.select("id", "data", "category").write().format("iceberg").mode(SaveMode.Append).save(loadLocation(tableIdentifier));
    table.refresh();
    Dataset<Row> resultDf = spark.read().format("iceberg").load(loadLocation(tableIdentifier));
    assertThat(resultDf.orderBy("id").collectAsList()).as("Records should match").containsExactlyElementsOf(originalRecords);
    long tsBeforeDropColumn = waitUntilAfter(System.currentTimeMillis());
    table.updateSchema().deleteColumn("data").commit();
    long tsAfterDropColumn = waitUntilAfter(System.currentTimeMillis());
    List<Row> newRecords = Lists.newArrayList(RowFactory.create(4, "B"), RowFactory.create(5, "C"));
    StructType newSparkSchema = SparkSchemaUtil.convert(SCHEMA3);
    Dataset<Row> inputDf2 = spark.createDataFrame(newRecords, newSparkSchema);
    inputDf2.select("id", "category").write().format("iceberg").mode(SaveMode.Append).save(loadLocation(tableIdentifier));
    table.refresh();
    List<Row> updatedRecords = Lists.newArrayList(RowFactory.create(1, "A"), RowFactory.create(2, "A"), RowFactory.create(3, "B"), RowFactory.create(4, "B"), RowFactory.create(5, "C"));
    Dataset<Row> resultDf2 = spark.read().format("iceberg").load(loadLocation(tableIdentifier));
    assertThat(resultDf2.orderBy("id").collectAsList()).as("Records should match").containsExactlyElementsOf(updatedRecords);
    Dataset<Row> resultDf3 = spark.read().format("iceberg").option(SparkReadOptions.AS_OF_TIMESTAMP, tsBeforeDropColumn).load(loadLocation(tableIdentifier));
    assertThat(resultDf3.orderBy("id").collectAsList()).as("Records should match").containsExactlyElementsOf(originalRecords);
    assertThat(resultDf3.schema()).as("Schemas should match").isEqualTo(originalSparkSchema);
    // At tsAfterDropColumn, there has been a schema change, but no new snapshot,
    // so the snapshot as of tsAfterDropColumn is the same as that as of tsBeforeDropColumn.
    Dataset<Row> resultDf4 = spark.read().format("iceberg").option(SparkReadOptions.AS_OF_TIMESTAMP, tsAfterDropColumn).load(loadLocation(tableIdentifier));
    assertThat(resultDf4.orderBy("id").collectAsList()).as("Records should match").containsExactlyElementsOf(originalRecords);
    assertThat(resultDf4.schema()).as("Schemas should match").isEqualTo(originalSparkSchema);
}

